    *keyArray = malloc(sizeof(int) * MAX_RECORDS);
    *valueArray = calloc(MAX_RECORDS, sizeof(float));  // zeroed out
}

void initRecordsAndHashTable(Record** records, long* offsets, int* keys, float* values) {
    srand((unsigned int)time(NULL));
    *records = malloc(sizeof(Record) * MAX_RECORDS);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        (*records)[i].key = keys[i] = rand();  // Generating unique random keys
        (*records)[i].offset = &offsets[i];
        values[i] = (float)rand() / (float)(RAND_MAX) * MAX_VALUE + MIN_VALUE;  // Random float value within a range
        hashTable[keys[i]] = malloc(sizeof(HashNode));
    }
}

