['Rust's concurrency model allows for safe sharing of mutable data between threads, but it is not automatically parallelized by the language itself. To leverage multiple cores, you would need to use a runtime like `rayon` or create your own thread pool manually. 

The following is an abstract example of how this could be done:

```rust
use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::fs::File;
use std::io::Read;
use std::path::PathBuf;

#[derive(Debug)]
struct Cache {
    file_content: String,
    llvm_ir: Option<String>,
}

pub struct Parser {
    cache: Arc<RwLock<HashMap<String, Cache>>>,
}

impl Parser {
    pub fn new() -> Self {
        let cache = Arc::new(RwLock::new(HashMap::new()));
        Parser { cache }
    }

    // Assuming the following functions exist: 
    //   parse_to_llvm_ir(input: &str) -> String
    //   handle_directive(&self, directive: &str, llvm_ir: &mut String)

    pub fn generate_llvm_ir(&self, path: String) -> Option<String> {
        let cache = self.cache.read().unwrap();

        if let Some(cached) = cache.get(&path) {
            return cached.llvm_ir.clone();  // Clone for thread safety
        }

        match PathBuf::from(path).exists() {
            false => {
                printlnlog: &formatprintln("Error: File does not exist.");
                None
            },
            true => {
                let mut file = match File::open(&path) {
                    Err(_) => return None,
                    Ok(file) => file,
                };

                let mut content = String::new();
                match file.read_to_string(&mut content) {
                    Err(_) => return None,
                    _ => (),
                }

                if !path.ends_with(".ext") {  // Replace with actual grammar extension
                    printlnlog: &formatprintln("Error: Invalid file extension.");
                    return None;
                }

                let mut llvm_ir = Self::parse_to_llvm_ir(&content);

                for directive in Self::extract_directives(path.clone()) {
                    Self::handle_directive(&directive, &mut llvm_ir);
                }

                let mut cache = self.cache.write().unwrap();
                cache.insert(path, Cache { file_content: content, llvm_ir: Some(llvm_ir) });

                Some(llvm_ir)
            },
        }
    }

    // This should be implemented for your specific use case 
    fn extract_directives(_path: String) -> Vec<String> { vec![/* directives */] }
}
