```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class QueryExecutor
{
    private readonly string connectionString;
    private readonly int timeoutDuration;

    public QueryExecutor(string connectionString, int timeoutDuration)
    {
        this.connectionString = connectionString;
        this.timeoutDuration = timeoutDuration;
    }

    public async Task<Dictionary<string, IDataReader>> ExecuteQueriesAsync(List<string> queries)
    {
        var queryResults = new Dictionary<string, IDataReader>();

        using (var connection = new SqlConnection(connectionString))
        {
            await connection.OpenAsync();

            foreach (var query in queries)
            {
                using (var command = new SqlCommand(query, connection))
                {
                    command.CommandTimeout = timeoutDuration;

                    // Execute the query and retrieve the result set asynchronously
                    var reader = await command.ExecuteReaderAsync();

                    // Add the result to the dictionary
                    queryResults[query] = reader;
                }
            }
        }

        return queryResults;
    }
}
```

This code uses the `System.Data.SqlClient` namespace to interact with a SQL Server database, and the `System.Threading.Tasks` namespace for asynchronous operations. The method ExecuteQueriesAsync accepts a list of SQL queries and executes them concurrently using async/await patterns.

