<?php
class UserAccount {
    private $pdo;

    public function __construct($host = 'localhost', $dbname = 'test', $username = 'root', $password = '', $charset = 'utf8') {
        $this->pdo = new PDO("mysql:host=$host;dbname=$dbname;charset=$charset", $username, $password);
    }

    public function handleRequest($request) {
        if (isset($request['id']) && is_int((int)$request['id'])) {
            // update an existing user account
            $user = $this->getUserById($request['id']);
            if (!$user) {
                return json_encode(['message' => 'error', 'reason' => 'No such user.']);
            }
        } else {
            // create a new user account
            $user = [];
        }

        $validationResult = $this->validateUserData($request);
        if ($validationResult !== true) {
            return json_encode(['message' => 'error', 'reason' => $validationResult]);
        }

        // update user data with request data
        $user = array_merge($user, $request);

        if (isset($request['sub_action']) && $request['sub_action'] === 'delete') {
            // delete the user account
            $this->deleteUserById($user['id']);
        } else {
            // save the updated data to database
            $this->saveUserData($user);
        }

        return json_encode(['message' => 'success']);
    }

    private function validateUserData($data) {
        if (strlen($data['name']) < 3) {
            return "Name must be at least 3 characters long.";
        } elseif (!filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
            return "Email is not valid.";
        } elseif (strlen($data['password']) < 8) {
            return "Password must be at least 8 characters long.";
        } elseif (!in_array($data['role'], ['user', 'admin'])) { // assume predefined roles are 'user' and 'admin'
            return "Role is not recognized.";
        }

        return true;
    }

    private function getUserById($id) {
        $stmt = $this->pdo->prepare('SELECT * FROM users WHERE id = :id');
        $stmt->execute(['id' => $id]);
        return $stmt->fetch();
    }

    private function deleteUserById($id) {
        $stmt = $this->pdo->prepare('DELETE FROM users WHERE id = :id');
        $stmt->execute(['id' => $id]);
    }

    private function saveUserData($data) {
        // upsert operation (update if exists, insert otherwise)
        $this->pdo->beginTransaction();

        $stmt = $this->pdo->prepare('INSERT INTO users VALUES (:id, :name, :email, :password, :role) ON DUPLICATE KEY UPDATE name = :name, email = :email, password = :password, role = :role');
        $stmt->execute($data);

        $this->pdo->commit();
    }
}
?>
```
