['```java
import java.io.*;
import java.util.*;
import java.security.*;
import java.nio.file.*;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class StateObjectLoader {
    private static final Logger logger = LogManager.getLogger(StateObjectLoader.class);

    // Cache map storing state object and timestamp
    private volatile Map<String, Pair<StateObject, Long>> cacheMap = new ConcurrentHashMap<>();
    private MessageDigest digest;

    public StateObjectLoader() {
        try {
            digest = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            logger.error(e);
        }
    }

    // Method to load state object from a file
    public StateObject loadStateFromFile(String filename) {
        Pair<StateObject, Long> cachedPair = cacheMap.get(filename);

        // Check the cache for recently loaded object 
        if (cachedPair != null && System.currentTimeMillis() - cachedPair.second < 10 * 60 * 1000) {
            return cachedPair.first;
        }

        try (ObjectInputStream in = new ObjectInputStream(new FileInputStream(filename))) {

            // Calculate the checksum of file before loading
            String actualChecksum = getFileChecksum(Paths.get(filename), digest);
            byte[] expectedBytes = Files.readAllBytes(Paths.get(filename + ".checksum"));
            String expectedChecksum = new String(expectedBytes, StandardCharsets.UTF_8).trim();

            // If checksums don't match - log error and return null
            if (!actualChecksum.equals(expectedChecksum)) {
                logger.error("File is corrupted: " + filename);
                return null;
            }

            StateObject state = (StateObject) in.readObject();

            // Add loaded object to cache 
            cacheMap.put(filename, new Pair<>(state, System.currentTimeMillis()));

            logger.info("Successfully loaded state from file: " + filename);

            return state;
        } catch (IOException | ClassNotFoundException e) {
            logger.error(e);
        }

        return null;
    }

    // Helper method to calculate checksum of a file 
    private String getFileChecksum(Path path, MessageDigest digest) throws IOException {
        byte[] fileBytes = Files.readAllBytes(path);
        byte[] digestBytes = digest.digest(fileBytes);

        // Convert the byte to hex format
        StringBuilder sb = new StringBuilder();
        for (byte b : digestBytes) {
            sb.append(String.format("%02x", b));
        }

        return sb.toString();
    }

    public static class Pair<A, B> {
        public final A first;
        public final B second;

        public Pair(A a, B b) {
            this.first = a;
            this.second = b;
        }
    }
}
```
