["Here's an example code that implements a JavaScript function to solve this task. Note that this code requires `axios` for HTTP requests and it's assumed that there is a Bible API available at `BIBLE_API_URL` endpoint with endpoints like `/books`, `/chapters/{bookId}` etc., which return the required information.

```javascript
const axios = require('axios');

// Define regex patterns for books and chapters
const booksPattern =  /(?:old|old\s?testament):? ([\w\s]+)(?: up)?/gi;
const chaptersPattern = /(\d+|first) (chapter|chapters) of (\w+)/gi;

// Normalize book names for consistent matching
const normalizeBookNames = str => {
  const normalizationMap = { 'gen':'Genesis', /*...*/ }; // add more mappings as necessary

  return Object.entries(normalizationMap).reduce((acc, [key, value]) => 
    acc.replace(new RegExp(`\\b${key}\\b`, 'gi'), value), str);
}

async function processText(text) {
  const normalized = normalizeBookNames(text);

  // Match and count books
  let match;
  const bookCounts = {};
  while ((match = booksPattern.exec(normalized)) !== null) {
    if (bookCounts[match[1]]) {
      bookCounts[match[1]] += 1;
    } else {
      bookCounts[match[1]] = 1;
    }
  }

  // Match and count chapters within books
  const chapterCounts = {};
  while ((match = chaptersPattern.exec(normalized)) !== null) {
    if (chapterCounts[`${match[3]} ${match[1]}`]) {
      chapterCounts[`${match[3]} ${match[1]}`] += 1;
    } else {
      chapterCounts[`${match[3]} ${match[1]}`] = 1;
    }
  }

  // Get additional metadata for books from API
  const books = await axios.get(`${BIBLE_API_URL}/books`);
  let apiCallsMade = 0;
  const bookMetadata = {};
  for (const [book, count] of Object.entries(bookCounts)) {
    if (!bookMetadata[book]) { // only make an API call once per book to minimize calls
      const metadataResponse = await axios.get(`${BIBLE_API_URL}/books/${encodeURIComponent(book)}`);
      bookMetadata[book] = metadataResponse.data;
      apiCallsMade++;
    }
  }

  return {
    books: bookCounts,
    chapters: chapterCounts,
    booksMetaData: bookMetadata
  };
}
```
Please note that you need to update the `booksPattern`, `chaptersPattern`, and `normalizeBookNames` function according to your requirements. Also handle API errors accordingly in production code.
