["Here's a basic implementation using Node.js' built-in Buffer class for handling binary data streams:

```javascript
const { EventEmitter } = require('events');
const fs = require('fs');

class AsyncDataReader extends EventEmitter {
    constructor(dataSource, chunkSize) {
        super();
        this.offset = 0;
        this.chunkSize = chunkSize;
        this.dataSource = dataSource;
    }

    readChunk() {
        const chunk = Buffer.alloc(this.chunkSize);
        let bytesRead = 0;

        while (bytesRead < this.chunkSize) {
            try {
                bytesRead += fs.readSync(this.dataSource, chunk, bytesRead, this.chunkSize - bytesRead, null);
            } catch (e) {
                if (bytesRead > 0) {
                    break;
                } else {
                    throw e;
                }
            }
        }

        return bytesRead === this.chunkSize ? chunk : chunk.slice(0, bytesRead);
    }

    readData(size) {
        const buffer = Buffer.allocUnsafe(size).fill(0);
        let copiedBytes = 0;
        while (copiedBytes < size) {
            const dataChunk = this.readChunk();
            copiedBytes += dataChunk.copy(buffer, copiedBytes);
        }

        return buffer;
    }
}
```
To use the above code, you would do something like:

```javascript
const reader = new AsyncDataReader(fs.openSync('path/to/file'), 1024); // Open file in sync mode and create a reader instance
const buffer = reader.readData(512); // Reads 512 bytes of data from the file, pads with zeros if needed
console.log(buffer);
```

Please note that JavaScript doesn't support true asynchronous I/O operations natively like some other languages (like Python or C#), so managing resources and handling large files can be challenging. Asynchronous approaches in Node.js often involve callbacks, promises, or async/await syntax which can become complex for more complicated applications, and managing resources without leaks requires a deep understanding of the event loop.
"]

