['Here is an example of how you might implement this in Java using NIO. This code does not handle all edge cases such as handling back pressure, but it can be used as a starting point for managing multiple remote addresses efficiently. It also includes connection timeouts and gracefully handles failures.

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.*;

public class MultiConnectionManager {
    private Selector selector;
    private Map<SelectionKey, Queue<ByteBuffer>> pendingData = new HashMap<>();

    public void startConnections(String[] hosts, int[] ports) throws IOException {
        this.selector = Selector.open();

        for (int i = 0; i < hosts.length; i++) {
            String host = hosts[i];
            int port = ports[i];

            SocketChannel client = SocketChannel.open(new InetSocketAddress(host, port));
            client.configureBlocking(false);

            client.register(selector, SelectionKey.OP_CONNECT | SelectionKey.OP_WRITE | SelectionKey.OP_READ);
        }
    }

    public void manageConnections() throws IOException {
        while (true) {
            int readyChannels = selector.selectNow();

            if(readyChannels == 0) continue;

            Set<SelectionKey> keys = selector.selectedKeys();
            Iterator<SelectionKey> iter = keys.iterator();

            while (iter.hasNext()) {
                SelectionKey key = iter.next();

                if(key.isConnectable()) handleConnection(key);
                if(key.isWritable())    handleWrite(key);
                if(key.isReadable())    handleRead(key);

                iter.remove();
            }
        }
    }

    private void handleConnection(SelectionKey key) {
        SocketChannel client = (SocketChannel) key.channel();

        // Check if the connection was successful
        if(client.isConnectionPending()) {
            client.finishConnect();
        }

        pendingData.put(key, new LinkedList<>());
    }

    private void handleWrite(SelectionKey key) throws IOException {
        SocketChannel client = (SocketChannel) key.channel();
        Queue<ByteBuffer> queue = pendingData.get(key);

        while(!queue.isEmpty()) {
            ByteBuffer buf = queue.peek();
            int bytesWritten = client.write(buf);

            if(bytesWritten == -1) {
                key.cancel();
                ((SocketChannel) key.channel()).close();

                System.out.println("C: Connection problem");
                return;
            }

            if(buf.hasRemaining()) return;
            queue.remove();
        }

        if(queue.isEmpty()) {
            key.interestOps(SelectionKey.OP_READ);
        }
    }

    private void handleRead(SelectionKey key) throws IOException {
        ByteBuffer buf = ByteBuffer.allocateDirect(8192);

        int numRead = -1;
        try {
            numRead = ((SocketChannel) key.channel()).read(buf);
        } catch (IOException e) {
            System.out.println("C: Could not read from remote host");
            return;
        }

        if (numRead == -1) {
            pendingData.remove(key);
            key.cancel();

            ((SocketChannel) key.channel()).close();

            System.out.println("C: Connection closed by remote host");
        } else if (numRead > 0) {
            buf.flip(); // ready for reading

            // Process the read data...
        }
    }
}
```
This code uses non-blocking IO with a single thread to manage multiple connections to multiple remote hosts. It does not use any third party libraries and it is suitable for managing small numbers of persistent connections. However, for handling larger number of connections or more complex networking scenarios you might want to consider using Netty or similar libraries which provide much higher-level abstractions over Java NIO.
']

['The following is an example of how this task can be implemented in Python using a thread-safe `Cache` class with basic error handling. The JSON validation uses the `jsonschema` library. This code also assumes that there are predefined default values available as a dictionary.

```python
import json
import os
import requests
from jsonschema import validate, ValidationError
from threading import Lock

class Cache:
    def __init__(self):
        self._cache = {}
        self._lock = Lock()

    def update(self, key, value):
        with self._lock:
            self._cache[key] = value

    def get(self, key):
        return self._cache.get(key)

class ConfigCache:
    def __init__(self, cache_root='./config', remote_url='http://example.com/remoteConfig', schema={}, defaults={}):
        self.defaults = defaults
        self.schema = schema
        self.cache = Cache()
        self.cache_root = cache_root
        self.remote_url = remote_url

    def is_stale(self, key):
        # This method will depend on the specifics of your configuration
        # For now it always returns True to ensure a refresh every time
        return True 

    def refresh_config(self, key):
        if self.is_stale(key) or not os.path.exists(os.path.join(self.cache_root, key)):
            try:
                response = requests.get(self.remote_url)  # Make the HTTP request

                # If the GET failed due to a network problem, it will raise a requests.exceptions.RequestException
                response.raise_for_status()              

            except (requests.exceptions.HTTPError, requests.exceptions.ConnectionError, requests.exceptions.Timeout, requests.exceptions.RequestException) as err:
                print(f"Failed to refresh config due to {err}. Retrying...")
                return self.refresh_config(key)  # Retry on failure

            if response.status_code == 200:
                data = response.json()  

                try:
                    validate(instance=data, schema=self.schema)    # Validate the config with a JSON Schema

                except ValidationError as err:
                    print(f"Invalid configuration: {err}")
                    return 

                self.cache.update(key, data)  

    def initialize_defaults(self):
        if not os.path.exists(self.cache_root):
            os.makedirs(self.cache_root)

            for key, value in self.defaults.items():
                with open(os.path.join(self.cache_root, key), 'w') as f:
                    json.dump(value, f)

    def get_config(self, key):
        if not os.path.exists(self.cache_root):
            self.initialize_defaults()

        if self.is_stale(key):
            self.refresh_config(key)

        return self.cache.get(key)
```
You can then instantiate this class with the relevant parameters and call `get_config` method to get your configuration:

```python
schema = {...}  # Define your JSON Schema here
defaults = {...}  # Define your default values here
myConfigCache = ConfigCache(remote_url='http://example.com/config', schema=schema, defaults=defaults)
print(myConfigCache.get_config('someKey'))
```
']

