```java
import java.util.Scanner;
import java.util.Random;
import java.lang.*;  // for handling overflow

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();

        if (n < 1 || n > 10_000) {
            System.err.println("Invalid input size: " + n);
            return;
        }

        Integer[] numbers = new Integer[n];
        for (int i = 0; i < n; ++i) {
            int number = scanner.nextInt();
            if (number > Integer.MAX_VALUE || number < Integer.MIN_VALUE) {
                System.err.println("Invalid input: " + number);
                return;
            }
            numbers[i] = number;
        }

        int maxValue = Integer.MIN_VALUE;
        for (Integer number : numbers) {
            if(Math.addExact(number, 0) > maxValue){
                maxValue = Math.addExact(number, 0);
            }
        }

        System.out.println("Max Value: " + maxValue);

        Random rand = new Random();
        while (true) {
            try {
                int delay = rand.nextInt(10000); // random delay between 0 and 9999 milliseconds
                Thread.sleep(delay);

                String message = "Service started";
                System.out.println(message);

                delay = rand.nextInt(10000); // another random delay for service stop
                Thread.sleep(delay);

                sendMessageToMessagingSystem("Service stopped");
            } catch (InterruptedException e) {
                System.out.println("Service was interrupted: " + e.getMessage());
            }
        }
    }

