    let start_time = Instant::now();

    catch_with_exit_code(|| {
        Command::new("rustc")
            .args(&["--crate-type", "bin"]) // example rustc arguments, replace with actual args
            .spawn()?;

        Ok(())
    })?;

    let end_time = start_time.elapsed();
    let after_usage = Rusage::read_current().unwrap();

