class Security {
    private $attemptLimit;
    private $sessionDuration;
    private $failedLoginTracker = [];

    public function __construct($attemptLimit = 5, $sessionDuration = 60) {
        $this->attemptLimit = $attemptLimit;
        $this->sessionDuration = $sessionDuration;
    }

    public function generateString($length = 32) {
        if (function_exists('random_bytes')) {
            $string = bin2hex(random_bytes($length));
        } elseif (function_exists('mcrypt_create_iv')) {
            $string = bin2hex(mcrypt_create_iv($length, MCRYPT_DEV_URANDOM));
        } else {
            throw new \Exception("No CSPRNG available.");
        }

        $hash = $this->generateHash($string);
        return $hash;
    }

    public function generateSessionId() {
        session_start([
            'cookie_lifetime' => $this->sessionDuration,
        ]);

        if (!isset($_SESSION['id'])) {
            $_SESSION['id'] = $this->generateString();
        } elseif (time() - $_SESSION['LAST_ACTIVITY'] > $this->sessionDuration) {
            session_regenerate_id();
            $_SESSION['id'] = $this->generateString();
        }
        $_SESSION['LAST_ACTIVITY'] = time();

        return $_SESSION['id'];
    }

    public function generateHash($password) {
        $hash = password_hash($password, PASSWORD_BCRYPT);

        if ($hash === false) {
            throw new \Exception("Hashing failed.");
        }

        return $hash;
    }

    public function verifyPassword($user, $password) {
        $storedHash = $this->fetchStoredHashForUser($user);
        if (password_verify($password, $storedHash)) {
            if (isset($this->failedLoginTracker[$user])) {
                unset($this->failedLoginTracker[$user]);
            }

            return true;
        } else {
            if (!isset($this->failedLoginTracker[$user])) {
                $this->failedLoginTracker[$user] = 0;
            }
            $this->failedLoginTracker[$user]++;

            return false;
        }
    }

    public function isBruteForceAttempt($user) {
        if (!isset($this->failedLoginTracker[$user])) {
            $this->failedLoginTracker[$user] = 0;
        }

        return $this->failedLoginTracker[$user] >= $this->attemptLimit;
    }

    private function fetchStoredHashForUser($user) {
        // Fetch and return the stored hash for this user from your database here.
    }
}
?>
