["```c
#include <stdlib.h>

// Assuming FSA and State are defined as follows
typedef struct {
    int *transitions;
    struct State* next;
} State;

typedef struct {
    // Assume the rest of the structure is defined here
    State* lastState;
} Automaton;

void *safeMalloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        exit(EXIT_FAILURE);  // Or handle error as appropriate for your program
    }
    return ptr;
}

State* generateStates(int* transitions, int numTransitions, Automaton* automaton, State* lastState, int isDeterministic) {
    State* newList = NULL;

    if (isDeterministic) {
        // Handle deterministic case
        newList = safeMalloc(sizeof(State));
        newList->transitions = transitions;
        newList->next = NULL;

        lastState->next = newList;  // Update the 'next' pointer of the last state to point to the newly created list
    } else {
        // Handle non-deterministic case, where we generate all possible transitions
        for (int i = 0; i < numTransitions; ++i) {
            State* newState = safeMalloc(sizeof(State));
            newState->transitions = &transitions[i];  // Set the transition to the current one
            newState->next = NULL;

            if (newList == NULL) {
                newList = newState;
            } else {
                State* temp = newList;

                while(temp->next != NULL){
                    temp = temp->next;
                }
                temp->next = newState;
            }
        }
    }

    return newList;
}
``` 
