```cpp
#include <vector>
#include <stdexcept>

struct OctreeNode {
    std::vector<OctreeNode*> children;
    bool isLeaf;
};

class Octree {
public:
    static constexpr int NUM_CHILDREN = 8;

    Octree(int featureSize, int capacity) : _featureSize{featureSize}, _capacity{capacity} {}

    ~Octree() {
        deleteNode(_root);
    }

    void insertData(const std::vector<int>& dataPoints) {
        if (dataPoints.size() > _capacity) 
            throw std::runtime_error("Capacity exceeded");

        for (auto dataPoint : dataPoints) 
            insert(_root, 0, dataPoint);
    }

private:
    void deleteNode(OctreeNode* node) {
        if (!node) return;

        for (auto child : node->children) 
            deleteNode(child);

        delete node;
    }

    void insert(OctreeNode*& node, int level, int dataPoint) {
        // This is just a simple example. In reality, you'll need to split the space and determine where to put this point
        if (node == nullptr) 
            node = new OctreeNode();

        if (level == _featureSize) {
            node->isLeaf = true;
            return;
        }

        int childIndex = dataPoint % NUM_CHILDREN; // this should be calculated based on the actual space partitioning algorithm 
        insert(node->children[childIndex], level + 1, dataPoint);
    }

    OctreeNode* _root{nullptr};
    int _featureSize;
    int _capacity;
};
```
This is a simple octree implementation where each node has exactly 8 children. `insertData` method accepts an array of datapoints and inserts them into the tree, and it ensures that data capacity isn't exceeded. Note: in practice, you would need to implement proper space partitioning algorithm based on your requirements.

