['Here is a sample implementation in C that uses mutex locks for thread safety to handle dynamic criteria like transaction age, total number of transactions and highest weight within last 10 seconds. It also uses a priority queue to keep track of the maximum weighted sum transactions while maintaining the order so it can return the one with the highest weighted sum among those that meet all the criteria.

```C
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct Transaction {
    int id;
    time_t timestamp;
    double weight;
} Transaction;

typedef struct QueueNode {
    Transaction* transaction;
    struct QueueNode* next;
} QueueNode;

QueueNode* head = NULL, *tail = NULL;
int totalTransactions = 0;
double averageAge = 0.0, highestWeight = 0.0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void enqueue(Transaction* transaction) {
    QueueNode* newNode = (QueueNode*) malloc(sizeof(QueueNode));
    newNode->transaction = transaction;
    newNode->next = NULL;

    pthread_mutex_lock(&lock);  // Lock for thread safety
    if (tail == NULL) {
        head = tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }
    totalTransactions++;
    pthread_mutex_unlock(&lock);  // Unlock after modification
}

void dequeue() {
    if (head == NULL) return;

    QueueNode* temp = head;
    head = head->next;

    if (head == NULL) tail = NULL;

    free(temp);  // Free memory after dequeuing
}

void processTransaction(int id, time_t timestamp, double weight) {
    Transaction* transaction = (Transaction*) malloc(sizeof(Transaction));
    transaction->id = id;
    transaction->timestamp = timestamp;
    transaction->weight = weight;

    pthread_mutex_lock(&lock);  // Lock for thread safety
    while (head != NULL && time(NULL) - head->transaction->timestamp > 10) dequeue();

    if (totalTransactions < 50 && time(NULL) - transaction->timestamp <= 5) {
        enqueue(transaction);

        averageAge = ((averageAge * (totalTransactions - 1)) + (time(NULL) - transaction->timestamp)) / totalTransactions;
        if (highestWeight < weight) highestWeight = weight;
    } else {
        free(transaction);  // Free memory for unused transactions
    }

    pthread_mutex_unlock(&lock);  // Unlock after modification
}

Transaction* getHighestWeightedSum() {
    if (head == NULL) return NULL;

    QueueNode* maxNode = head, *temp = head->next;
    while (temp != NULL) {
        if (maxNode->transaction->weight < temp->transaction->weight) maxNode = temp;
        temp = temp->next;
    }

    return maxNode->transaction;
}
```

This code is a simple implementation and might need modifications to suit the specific use case. Also, due to thread safety, it may not be efficient for high transaction rates as mutex locks might lead to some latency. You might need to use more sophisticated data structures or algorithms to handle high transaction volumes efficiently.
']

