// Mock game state manager
class GameStateManager {
public:
    void performAttack(int attack) {}  // Function to perform the actual attack action

    bool canPerformAction() { return true; }  // Checks if cooldown is over and player can perform an action
};

// Attack Strategy class managing attacks
class AttackStrategy {
private:
    GameStateManager* gameManager;
    std::vector<int> attacks = {};
    int cooldown = 9000;  // Cooldown in milliseconds
    std::mutex mtx;

public:
    AttackStrategy(GameStateManager* gm) : gameManager(gm){}

    void addAttack(int attackId) { attacks.push_back(attackId); }  // Function to add new attack types

    int getRandomAttack() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> distr(0, attacks.size()-1);

        return attacks[distr(gen)];  // Returns a random attack
    }

    void executeAttack() {
        if (gameManager->canPerformAction()) {
            int attack = getRandomAttack();

            std::lock_guard<std::mutex> lock(mtx);  // Locks the thread to prevent race conditions
            gameManager->performAttack(attack);  // Performs the attack
        } else {
            std::this_thread::sleep_for(std::chrono::milliseconds(cooldown));  // Wait for cooldown period
        }
    }
};
