```csharp
using UnityEngine;

public class RandomValueGenerator {
    private float minValue;
    private float maxValue;
    private bool isInclusive = false;

    // Seed value for reproducibility
    private int seed = 0;
    private System.Random randomGen;

    public RandomValueGenerator(float min, float max, bool inclusive = false) {
        if (min >= max) 
            throw new ArgumentException("Minimum must be less than maximum");

        this.minValue = min;
        this.maxValue = max;
        this.isInclusive = inclusive;

        // Using Unity's Random class to generate seed value
        int unitySeed = (int)Random.value; 

        if(seed == 0) {
            // Use Unity's random seed as default seed
            seed = unitySeed;
        }

        // Initialize System.Random with the determined seed
        this.randomGen = new System.Random(seed);
    }

    public float GetFloat() {
        if (isInclusive) 
            return (float)(this.minValue + (this.maxValue - this.minValue) * randomGen.NextDouble());

        return (float)(this.minValue + (this.maxValue - this.minValue - float.Epsilon) * randomGen.NextDouble());
    }

    public int GetInt() {
        if (isInclusive) 
            return (int)(this.minValue + (this.maxValue + 1 - this.minValue) * randomGen.NextDouble());

        return (int)(this.minValue + (this.maxValue - this.minValue) * randomGen.NextDouble());
    }

    public override string ToString() {
        return $"Range: [{this.minValue}, {this.maxValue}] - Seed: {seed}";
    }
}
```

This class allows the user to specify a range (minimum and maximum values), as well as whether or not the range is inclusive, in its constructor. The `GetFloat` and `GetInt` methods return a random float and integer within that specified range respectively. 

The seed value for reproducibility is derived from Unity's Random class, but can be overridden with a custom value. The `ToString` method provides information about the current state of the generator. Edge case handling is implemented through throwing appropriate exceptions when invalid inputs are provided to the constructor.
