```javascript
async function asyncReduce(array, initialValue, callback) {
    try {
        let acc = initialValue;

        for (let i = 0; i < array.length; i++) {
            // If the current value is a Promise, await it before passing it to callback
            const value = Array.isArray(array[i]) ? 
                await Promise.all(array[i].map(async item => typeof item === 'object' && item instanceof Promise ? await item : item)) : 
                array[i];

            acc = await callback(acc, value);
        }

        return acc;
    } catch (error) {
        console.log('An error occurred during the reduction process:', error);
        throw error;
    }
}
```
