['Here is the C code for loading a resource bundle from a file:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Error codes
enum {
    SUCCESS = 0,
    FILE_OPEN_ERROR = -1,
    MEMORY_ALLOCATION_FAILURE = -2,
};

typedef struct ResourceBundle {
    char *path;
    int count; // number of items in the bundle
} ResourceBundle;

ResourceBundle **bundles = NULL;
int bundleCount = 0;

// Function to load resource bundle from a file
int loadResourceBundle(char *path, ResourceBundle ***bundle) {
    FILE *file;
    char line[256];
    int count = 0;

    // Open the file in read mode
    if ((file = fopen(path, "r")) == NULL) return FILE_OPEN_ERROR;

    // Count the number of items
    while (fgets(line, sizeof(line), file)) count++;

    // Allocate memory for new bundle
    ResourceBundle **newBundles = realloc(*bundle, (*bundleCount + 1) * sizeof(ResourceBundle*));
    if (newBundles == NULL) return MEMORY_ALLOCATION_FAILURE;

    bundles = newBundles;

    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (bundle == NULL) return MEMORY_ALLOCATION_FAILURE;

    bundle->path = strdup(path);
    if (bundle->path == NULL) return MEMORY_ALLOCATION_FAILURE;

    bundle->count = count;

    bundles[*bundleCount] = bundle;
    (*bundleCount)++;

    fclose(file);
    return SUCCESS;
}
```

This code opens a file in read mode, counts the number of lines (which it assumes are items in the resource bundle), allocates memory for a new bundle and its path, then stores these values. It also handles all errors that might occur during this process. 

Note: This is a simple solution to your problem. In a real world scenario you would probably want to expand this function or add more functionality based on the specific requirements of your application. For example, you could implement a `freeResourceBundle` function to free the memory allocated for each bundle when it's no longer needed.
']

