static pthread_mutex_t allocationLock = PTHREAD_MUTEX_INITIALIZER;

char* appendSlash(const char* input, size_t limit) {
    if (!input || limit < 0) return NULL;
    if (strlen(input) >= limit) return strdup(input);

    pthread_mutex_lock(&allocationLock); // Ensure thread-safety for allocations.

    size_t remaining = limit - strlen(input) - 1;
    char* result = malloc((remaining + 2)*sizeof(char));
    if (!result) {
        pthread_mutex_unlock(&allocationLock); // Unlock to avoid potential deadlocks.
        fprintf(stderr, "Allocation failed.\n");
        return NULL;
    }

    strncpy(result, input, remaining);
    result[remaining] = '/';
    result[remaining + 1] = '\0';

    pthread_mutex_unlock(&allocationLock); // Unlock to avoid potential deadlocks.

    return result;
}
```
