['Here is a C function that accomplishes this task:

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

char *modify_extension(const char *filename) {
    static char new_name[256];  // Array for the modified filename

    strncpy(new_name, filename, sizeof(new_name)-1);  // Copy original filename to new_name array

    const char *dot = strrchr(filename, '.');  // Find last occurrence of '.' in filename
    if (dot == NULL) {  
        sprintf(new_name, ".0%zu", strlen(filename));  // If no extension, append '0' and length of base part
    } else {
        size_t len = dot - filename;  // Length of base part

        new_name[len] = 0;  // Truncate original filename at the extension

        int checksum = 0;  // Variable to store checksum
        for (size_t i=0; i<len; ++i) {
            checksum += toupper(filename[i]);  // Calculate checksum by summing ASCII values of characters in base part
        }

        if (len < 5) {  
            sprintf(&new_name[len], ".0%zu", len);  // Append '0' and length of base part to new filename
        } else {
            sprintf(&new_name[len], ".1%zu%d", len, checksum % 256);  // Append '1', length of base part and checksum to new filename
        }
    }

    if (strlen(new_name) > 255) {  // If new filename is too long, truncate it
        new_name[255] = 0;
    }

    return new_name;  
}
```

In this function:
- We first copy the original filename to a static array `new_name`.
- Then we find the last occurrence of '.' in the original filename and get its position using `strrchr()`. 
- If there's no extension, we append '0' followed by the length of the base part.
- If there is an extension, we truncate the filename at the extension, calculate checksum, and then add it to the new name based on its length.
- If the new filename is too long (more than 255 characters), we truncate it and return it.
