```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

typedef struct {
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} AES_CBC_Cipher;

int setupAES(const unsigned char* password, const unsigned char* salt, int iterations, AES_CBC_Cipher* cipher) {
    if (PKCS5_PBKDF2_HMAC((char*)password, -1, salt, -1, iterations, EVP_aes_256_cbc(), 32, cipher->key)) {
        RAND_bytes(cipher->iv, sizeof(cipher->iv));
    } else return 0;

    return 1;
}

void encryptData(const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext, AES_CBC_Cipher* cipher) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv);

    int len;
    EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + len, &len);

    EVP_CIPHER_CTX_free(ctx);
}

void decryptData(const unsigned char* ciphertext, int ciphertext_len, unsigned char* plaintext, AES_CBC_Cipher* cipher) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv);

    int len;
    EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx, plaintext + len, &len);

    EVP_CIPHER_CTX_free(ctx);
}
```

