```C
#include <stdio.h>
#include "cjson/cJSON.h"
#include <regex.h>
#include <string.h>
#include <ctype.h>

bool validate_access_token(const char * access_token) {
    return (access_token != NULL && strlen(access_token) > 0);
}

bool validate_expires_in(cJSON* json, const char * expires_in) {
    cJSON* j = cJSON_GetObjectItemCaseSensitive(json, expires_in);
    if (j == NULL || !cJSON_IsNumber(j)) return false;

    int num = j->valueint;
    return (num > 0);
}

bool validate_token_type(const char * token_type) {
    const char* pattern = "Bearer";
    return strcmp(token_type, pattern) == 0;
}

// regex to match rt_ followed by 16 alphanumeric characters
bool validate_refresh_token(const char * refresh_token) {
    if (refresh_token == NULL) return true; // Optional field. If it's not present, the function should still return true.

    regex_t regex;
    int ret = regcomp(&regex, "^rt_[a-zA-Z0-9]{16}$", REG_NOSUB | REG_EXTENDED);

    if (ret != 0) return false; // Error compiling the regular expression

    ret = regexec(&regex, refresh_token, 0, NULL, 0);
    regfree(&regex);

    return (ret == 0); // If there's a match (0), it's valid. Otherwise, not.
}

bool validate_json(const char* json_string) {
    cJSON* json = cJSON_Parse(json_string);
    if (json == NULL) return false; // Malformed JSON

    bool result = validate_access_token(cJSON_GetObjectItemCaseSensitive(json, "access_token")->valuestring) && 
                  validate_expires_in(json, "expires_in") && 
