    public (string decryptedMessage, string md5Hash) DecryptAndComputeMd5(string encryptedBase64String, byte[] key, byte[] iv)
    {
        try
        {
            using var tripleDes = TripleDES.Create();
            tripleDes.Key = key;
            tripleDes.IV = iv;

            var decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);
            var encryptedBytes = Convert.FromBase64String(encryptedBase64String);

            using var memoryStream = new MemoryStream();
            using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Write))
            {
                cryptoStream.Write(encryptedBytes, 0, encryptedBytes.Length);
            }

            var decryptedMessageBytes = memoryStream.ToArray();
            var decryptedMessage = Encoding.UTF8.GetString(decryptedMessageBytes);

            using (var md5 = MD5.Create())
            {
                byte[] hash;
                using (var stream = new MemoryStream(decryptedMessageBytes))
                {
                    const int bufferSize = 4096; // Adjust this value based on your needs and available memory
                    var buffer = new byte[bufferSize];

                    long bytesRead;
                    while ((bytesRead = stream.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        md5.TransformBlock(buffer, 0, (int)bytesRead, null, 0);
                    }

                    md5.TransformFinalBlock(new byte[0], 0, 0); // Finalize the hash computation
                    hash = md5.Hash;
