const { exec } = require('child_process');
const sanitizeHtml = require('sanitize-html');

function executeShellCommand(command, callback) {
    // Sanitize and validate command input using a library like 'sanitize-html'
    const sanitizedCommand = sanitizeHtml(command, {
        allowedTags: [],
        allowedAttributes: {}
    });

    // Check if the command is not empty or contains only white spaces
    if (!sanitizedCommand.trim()) {
        callback("Invalid command input. Empty or whitespace-only commands are not permitted.", null);
        return;
    }

    exec(sanitizedCommand, (error, stdout, stderr) => {
        if (error) {
            console.error(`Error executing command: ${command}`, error);
            callback("An error occurred while executing the command.", null);
            return;
        }
        if (stderr) {
            console.warn(`Command stderr: ${stderr}`);
        }

        // Sanitize output before returning to browser to prevent Cross-Site Scripting (XSS) attacks
        const sanitizedStdout = sanitizeHtml(stdout, {
            allowedTags: [],
            allowedAttributes: {}
        });
        callback(null, sanitizedStdout);
    });
}
```

