/// Initialize a workspace directory
pub fn init_workspace() -> Result<(), io::Error> {
    // Check if WORKSPACE_PATH environment variable is already set.
    match env::var("WORKSPACE_PATH") {
        Ok(path) => match fs::metadata(&path) {
            // If it's set and valid, don't overwrite the current value.
            Ok(_) => println_str("Existing WORKSPACE_PATH found."),
            Err(_) => {
                // If invalid, handle the error gracefully by creating a new directory.
                create_workspace()?;
            }
        },
        Err(_) => {
            // If not set, create a new directory in the user's home directory.
            create_workspace()?;
        }
    }

    Ok(())
}

/// Create a workspace directory and set WORKSPACE_PATH environment variable to it
fn create_workspace() -> Result<(), io::Error> {
    let timestamp = SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).unwrap().as_nanos();
    let workspace_path = format_str("{}/workspace_{}", env::var("HOME").unwrap(), timestamp);

    fs::create_dir(&workspace_path)?;
    Command::new("chmod")
        .args(["755", &workspace_path])
        .output()
        .expect("failed to execute process");

    env::set_var("WORKSPACE_PATH", workspace_path);

    Ok(())
}
```
In this code, we first check if the `WORKSPACE_PATH` environment variable is already set. If it's not or if its value points to a non-existing directory, we then proceed to create a new workspace directory with a unique name based on a timestamp. The permissions of the directory are set to 755 (rwx for owner and rx for group/others), which allows full access for the user and read/execute access for others.

