["Below is a simplified implementation of what you're asking for in C. The hash table used here uses open addressing (linear probing) due to its simplicity and efficiency characteristics. This code does not include all the features you described, but it should give you a good starting point:

```c
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <stdio.h>

typedef struct {
    int key;
    double value;
    long *offset;
} Record;

#define TABLE_SIZE 10007 // prime number for less collision
typedef struct {
    Record rec;
    int isOccupied;
} Bucket;

Bucket table[TABLE_SIZE];

void initTable() {
    memset(table, 0, sizeof(table));
}

unsigned int hash(int key) {
    return key % TABLE_SIZE; // Simple hashing function for testing. Replace with a more sophisticated one for actual use.
}

Record* get(int key) {
    unsigned int index = hash(key);
    while (table[index].isOccupied && table[index].rec.key != key) {
        index = (index + 1) % TABLE_SIZE; // Linear probing to find an empty slot or the required record.
    }

    if (!table[index].isOccupied) return NULL; // Record not found.
    else return &(table[index].rec);
}

void put(Record *record) {
    unsigned int index = hash(record->key);
    while (table[index].isOccupied && table[index].rec.key != record->key) {
        assert(index != hash(record->key)); // Ensuring there is enough space in the table.
        index = (index + 1) % TABLE_SIZE; 
    }

    if (!table[index].isOccupied || table[index].rec.offset != record->offset) { // Adding new records or updating existing ones.
        free(table[index].rec.offset); // Free the memory previously allocated to offset, in case of reallocation.
    }

    table[index].isOccupied = 1;
    table[index].rec = *record;
}

void removeRecord(int key) {
    Record* recPtr = get(key);
    if (recPtr != NULL) {
        free(recPtr->offset); // Free memory allocated for the record's offset.
        recPtr->key = 0; // Mark as removed, but doesn't actually remove to preserve future growth of table. 
    }
}

void cleanup() {
    for (int i=0; i<TABLE_SIZE; ++i) {
        if (table[i].isOccupied && table[i].rec.offset != NULL) free(table[i].rec.offset); // Free all allocated memory. 
    }
}
```
You can use this in a function as:

```c
void test_func() {
    initTable();

    long offset = 123456789;
    Record rec = { .key=1, .value=1.0, .offset=&offset };
    put(&rec);

    // ... use the table as needed... 

    cleanup(); // Clean up memory when done to prevent leaks.
}
```
This code has a few limitations and needs further development for real-world usage such as handling resizing, error checking, memory management for offsets, etc. You can also look into other collision resolution techniques (such as separate chaining) or consider using an existing library if you have performance or usability requirements that necessitate the use of more advanced data structures or algorithms.
"]

