```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct {
    int id;
    float signal_strength;
    float latency;
    float error_rate;
    float throughput;
} NetworkStatistics;

NetworkStatistics* statsList = NULL;
int listSize = 0;
int maxSize = 1024;  // Predefined threshold M.
pthread_mutex_t mutex;

void updateNetworkStats(int index) {
    float noise = rand() / (float)RAND_MAX;  // Simulate environmental conditions.
    statsList[index].signal_strength -= noise;  // Decrease signal strength due to interference.
}

void* workerThread(void *arg) {
    while(1) {
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < listSize; i++) {
            updateNetworkStats(i);  // Update all statistics.
        }
        pthread_mutex_unlock(&mutex);
        sleep(1);  // Wait 1 second before the next update.
    }
}

void initializeList(int N) {
    if (N > maxSize) {
        return; // Exceeded predefined threshold M, error handling needed.
    }

    statsList = realloc(statsList, sizeof(NetworkStatistics)*N);  // Resize list.

    for (int i = listSize; i < N; i++) {
        statsList[i].id = i + 1;  // Assign unique identifier.
        statsList[i].signal_strength = 0.0f;
        statsList[i].latency = 0.0f;
        statsList[i].error_rate = 0.0f;
        statsList[i].throughput = 0.0f;
    }

    listSize = N;  // Update the actual size of the list.
}

void startWorkerThread() {
    pthread_t threadID;
    pthread_create(&threadID, NULL, workerThread, NULL);
}
```
