['Here's an example of how you might implement such a method in Java using Apache Commons Codec for SHA-256 hash calculation and Guava's concurrent map for thread safety and efficient handling of 10,000 concurrent calls. Please note that the logging configuration is implemented with Logback and SLF4J.

```java
import org.apache.commons.codec.digest.DigestUtils;
import com.google.common.util.concurrent.AtomicLongMap;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.LoggerContext;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;
import ch.qos.logback.classic.encoder.PatternLayoutEncoder;
import ch.qos.logback.core.ConsoleAppender;

public class HashingService {
    private final AtomicLongMap<String> computationCount = AtomicLongMap.create();
    private boolean loggingEnabled = true; // by default, enable logging

    public Map<String, String> hashStrings(List<String> input) {
        return input.stream()
                .collect(Collectors.toConcurrentMap(s -> s, this::computeHash));
    }

    private String computeHash(String input) {
        computationCount.incrementAndGet("total");

        if (input == null || input.trim().isEmpty()) {
            computationCount.incrementAndGet("invalid");

            if (loggingEnabled) {
                MDC.put("correlationId", Thread.currentThread().getId() + "");
                LoggerFactory.getLogger(HashingService.class).error("Invalid input: {}", input);
                MDC.remove("correlationId");
            }

            return null; // or throw exception, depending on requirements
        }

        try {
            String hash = DigestUtils.sha256Hex(input);
            computationCount.incrementAndGet("success");
            return hash;
        } catch (NoSuchAlgorithmException e) {
            computationCount.incrementAndGet("failure");

            if (loggingEnabled) {
                MDC.put("correlationId", Thread.currentThread().getId() + "");
                LoggerFactory.getLogger(HashingService.class).error("Failed to compute hash for input: {}", input, e);
                MDC.remove("correlationId");
            }

            return null; // or throw exception, depending on requirements
        }
    }

    public long getComputationCount(String type) {
        return computationCount.get(type);
    }

    public void setLoggingEnabled(boolean loggingEnabled) {
        this.loggingEnabled = loggingEnabled;
    }

    public boolean isLoggingEnabled() {
        return loggingEnabled;
    }

    public void setLogLevel(String levelStr) {
        Level level = Level.toLevel(levelStr);

        LoggerContext loggerContext = (LoggerContext) LoggerFactory.getILoggerFactory();
        ConsoleAppender<?> appender = (ConsoleAppender<?>)loggerContext.getLogger("root").getAppender("STDOUT");
        PatternLayoutEncoder encoder = (PatternLayoutEncoder)appender.getEncoder();

        encoder.setLevel(level);
    }
}
```
To use this service, you create an instance of `HashingService` and call the `hashStrings()` method with a list of strings:

```java
