public static string DecryptAndHashMessage(string encryptedBase64, byte[] key, byte[] iv, byte[] hmacKey)
{
    try
    {
        // Convert from Base64 to bytes
        byte[] encryptedBytes = Convert.FromBase64String(encryptedBase64);

        using (TripleDES desAlg = TripleDES.Create())
        {
            desAlg.Key = key;
            desAlg.IV = iv;

            // Create a decrypter to perform the stream transform.
            ICryptoTransform decryptor = desAlg.CreateDecryptor(desAlg.Key, desAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream(encryptedBytes))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    // Receive the message and compute MD5 hash in chunks
                    byte[] chunk;
                    int bytesRead = 0;
                    MD5 md5Hash = MD5.Create();

                    do
                    {
                        chunk = new byte[4096];
                        bytesRead = csDecrypt.Read(chunk, 0, chunk.Length);

                        if (bytesRead > 0)
                        {
                            // Compute the hash for the current chunk
                            md5Hash.TransformBlock(chunk, 0, bytesRead, null, 0);

                            // Verify HMAC-SHA256 in real time
                            using (HMACSHA256 hmacsha256 = new HMACSHA256(hmacKey))
                            {
                                byte[] hashValue = hmacsha256.ComputeHash(chunk, 0, bytesRead);

                                // Compare with the received HMAC-SHA256 signature
                                if (!hashValue.SequenceEqual(receivedHmacSignature))
                                {
                                    throw new CryptographicException("The message was tampered during transit.");
                                }
                            }
                        }
                    } while (bytesRead > 0);

                    // Finalize the hash computation
                    md5Hash.TransformFinalBlock(chunk, 0, bytesRead);

                    return BitConverter.ToString(md5Hash.Hash).Replace("-", "");
                }
            }
        }
    }
    catch (CryptographicException e)
    {
        Console.WriteLine(e.Message);

        return null;
    }
}
```
