typedef struct {
    const EVP_MD *type;
    std::string name;
} HashInfo;

std::vector<HashInfo> listAvailableCiphersAndHashes() {
    OpenSSL_add_all_digests();
    std::vector<HashInfo> hashList;

    for(int i = 0; i < EVP_MD_type(i); i++) {
        const EVP_MD *md = EVP_get_digestbynid(i);

        if(md != nullptr){
            HashInfo info;
            info.type = md;
            info.name = OBJ_nid2sn(EVP_MD_type(md));
