pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

void populateArray(NFAPI_CRC_INDICATION_PDU_T *array, int size) {
    pthread_mutex_lock(&lock); // Lock the mutex to prevent race conditions.

    for (int i = 0; i < size; i++) {
