['Below is an example of how you might implement such a function using libtiff and libjpeg. Please note that this is just a simple implementation for guidance, it does not include all error handling or resource management features mentioned above as they would complicate the code significantly. 

```C
#include <stdio.h>
#include <string.h>
#include <tiffio.h>
#include <jpeglib.h>

typedef struct ImageInfo {
    int bitDepth;
    int samplePerPixel;
    char* metadata;
} ImageInfo;

ImageInfo parseTIFF(char *filename) {
    TIFF* tiff = TIFFOpen(filename, "r");

    if (tiff == NULL) {
        fprintf(stderr, "Could not open TIFF file %s", filename);
        return (ImageInfo){0, 0, ""};
    }

    ImageInfo info;

    // Parse image data
    uint16 config, bps, sps;
    TIFFGetField(tiff, TIFFTAG_PHOTOMETRIC, &config);
    TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bps);
    TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &sps);

    info.bitDepth = bps;
    info.samplePerPixel = sps;

    // Parse metadata
    char *metadata;
    long length;
    if(TIFFGetField(tiff, TIFFTAG_ARTIST, &metadata, &length)) {
        info.metadata = malloc((length+1)*sizeof(char));
        strncpy(info.metadata, metadata, length);
        info.metadata[length] = '\0';
    } else {
        info.metadata = "";
    }

    TIFFClose(tiff);

    return info;
}
``` 

This function opens a TIFF image file in read-only mode and retrieves information about the image's bit depth, samples per pixel, and metadata using libtiff. The returned information is wrapped into a struct ImageInfo for easy access to data. 

