#include <pthread.h>
#include <stdlib.h>

typedef struct {
    int sessionDuration;
    int userEngagementLevels;
    int appCrashes;
    int batteryConsumption;
} UserActivity;

typedef struct {
    pthread_mutex_t mutex;
    int size;
    int capacity;
    UserActivity** entries;
} UserActivityLog;

UserActivityLog* createLog(int N, int M) {
    if (N <= 0 || M < N) return NULL;

    UserActivityLog* log = malloc(sizeof(UserActivityLog));
    pthread_mutex_init(&log->mutex, NULL);

    log->capacity = M;
    log->entries = calloc(M, sizeof(UserActivity*));

    for (int i = 0; i < N; ++i) {
        UserActivity* activity = malloc(sizeof(UserActivity));
        // initialize metrics here...

        pthread_mutex_lock(&log->mutex);
        log->entries[i] = activity;
        log->size++;
        pthread_mutex_unlock(&log->mutex);
    }

    return log;
}

void updateLog(UserActivityLog* log, int index) {
    if (index >= log->capacity) {
        pthread_mutex_lock(&log->mutex);
        log->entries = realloc(log->entries, 2 * log->capacity * sizeof(UserActivity*));
        log->capacity *= 2;
        pthread_mutex_unlock(&log->mutex);
    }

    UserActivity* activity = malloc(sizeof(UserActivity));
    // update metrics here...

    pthread_mutex_lock(&log->mutex);
    free(log->entries[index]);
    log->entries[index] = activity;
    pthread_mutex_unlock(&log->mutex);
}
``` 
