        return NULL; // Invalid parameters
    }

    unsigned char key[keyLength];
    encryption_context *ctx = malloc(sizeof(encryption_context));

    if (!PKCS5_PBKDF2_HMAC_SHA1(password, -1, salt, -1, iterations, keyLength, key)) {
        free(ctx);
        return NULL; // Failed to derive key
    }

    RAND_bytes(ctx->iv, sizeof(ctx->iv)); // Generate random IV

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, ctx->iv)) {
        free(ctx);
        return NULL; // Failed to initialize cipher context
    }

    return ctx;
}

void encrypt(encryption_context *ctx, const unsigned char *plaintext, int plaintextLength, unsigned char **ciphertext)
{
    *ciphertext = malloc(plaintextLength + EVP_CIPHER_CTX_block_size(ctx->ctx));
    int ciphertextLength = 0;

    if (!EVP_EncryptUpdate(ctx->ctx, *ciphertext, &ciphertextLength, plaintext, plaintextLength)) {
        free(*ciphertext);
        return;
    }
}

void decrypt(encryption_context *ctx, const unsigned char *ciphertext, int ciphertextLength, unsigned char **plaintext)
{
    *plaintext = malloc(ciphertextLength + EVP_CIPHER_CTX_block_size(ctx->ctx));
    int plaintextLength = 0;

    if (!EVP_DecryptUpdate(ctx->ctx, *plaintext, &plaintextLength, ciphertext, ciphertextLength)) {
        free(*plaintext);
        return;
    }
}

void cleanup(encryption_context *ctx)
{
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
```
