} aes256cbc_context;

aes256cbc_context* setup_cipher(const char *password, const unsigned char *salt, int nrounds) {
    if (strlen(password) < 16) return NULL; // Insufficient password entropy

    aes256cbc_context *ctx = malloc(sizeof(aes256cbc_context));
    if (!ctx) return NULL; // Memory allocation failure

    /* Derive key and IV */
    if(!EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha3_256(), salt, (unsigned char*)password, strlen(password), nrounds, ctx->key, ctx->iv)) {
        free(ctx); // Error handling
        return NULL;
    }

    /* Initialize cipher */
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv) <= 0) {
        cleanup_cipher(ctx); // Error handling
        return NULL;
    }

    log_operation("Cipher setup"); // Log operation
    return ctx;
}

void cleanup_cipher(aes256cbc_context *ctx) {
    if (!ctx) return;

    /* Disable cipher */
    EVP_CIPHER_CTX_free(ctx->ctx);

    /* Securely clear key and IV from memory */
    memset(ctx->key, 0, sizeof(ctx->key));
    memset(ctx->iv, 0, sizeof(ctx->iv));

    free(ctx);
    log_operation("Cipher cleaned up"); // Log operation
}
```
