```C#
public static DataTableReader ExecuteQuery(byte[] input)
{
    string connectionString = "YourConnectionString";
    using (SqlConnection connection = new SqlConnection(connectionString))
    {
        connection.Open();

        // Convert byte array to hexadecimal for SQL Server VARBINARY column
        StringBuilder sbHex = new StringBuilder(input.Length * 2);
        foreach (byte b in input)
            sbHex.AppendFormat("{0:x2}", b);

        string sqlQuery = $"SELECT * FROM YourTable WHERE YourColumn = {sbHex}";
