['```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>
#define INITIAL_CAPACITY 100

typedef struct {
    int CELL_ID;
    int PCI;
    float RSRP_LEVEL;
    time_t TIMESTAMP;
} NR_CELL_INFO_PDU_T;

typedef struct {
    size_t size;
    size_t capacity;
    NR_CELL_INFO_PDU_T *data;
    pthread_mutex_t lock;
} DynamicList;

DynamicList list = {0, INITIAL_CAPACITY, NULL, PTHREAD_MUTEX_INITIALIZER};

void dynamicListInit() {
    list.data = malloc(sizeof(NR_CELL_INFO_PDU_T) * INITIAL_CAPACITY);
}

void dynamicListAdd(const NR_CELL_INFO_PDU_T* entry) {
    pthread_mutex_lock(&list.lock);

    if (list.size >= list.capacity) {
        list.capacity *= 2;
        list.data = realloc(list.data, sizeof(NR_CELL_INFO_PDU_T) * list.capacity);
    }

    list.data[list.size++] = *entry;

    pthread_mutex_unlock(&list.lock);
}

float calculateRSCPForCell(int cellID, int timeWindowSeconds) {
    pthread_mutex_lock(&list.lock);

    float rscpSum = 0;
    int count = 0;
    time_t currentTime = time(NULL);

    for (size_t i = 0; i < list.size; ++i) {
        if (list.data[i].CELL_ID == cellID && 
            difftime(currentTime, list.data[i].TIMESTAMP) <= timeWindowSeconds) {
            rscpSum += list.data[i].RSRP_LEVEL;
            ++count;
        }
    }

    pthread_mutex_unlock(&list.lock);

    return count == 0 ? 0 : rscpSum / count;
}
```
In this code, we use a `DynamicList` structure to hold the list of `NR_CELL_INFO_PDU_T` entries and a mutex to ensure thread safety. The function `dynamicListAdd()` adds an entry to the end of the list, resizing the internal array if necessary. We calculate the average received signal power for a specific `CELL_ID` over the last `timeWindowSeconds` using the function `calculateRSCPForCell()`. The calculations are performed in a critical section protected by the mutex to ensure thread safety.
']

