["Here is an implementation of your request in C and JavaScript. 

In C, we will use a pthread mutex for synchronization, and dynamic resizing with realloc. We keep track of the sum of RSCP values per cell_id in order to calculate average later. The timestamp is used to remove old entries from our calculations.

Please note that this code is just an example and may need adjustments according to your exact requirements. For instance, the JavaScript function uses Node's child_process module, which should be available in any environment where you run Node (like a browser). Also, please be aware of potential security issues when running shell commands from JavaScript due to possible code injection attacks if user input is not properly sanitized and validated.

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int cell_id;
    int pci;
    double rsrp_level;
    time_t timestamp;
} NR_CELL_INFO_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    size_t max_size;
    size_t current_size;
    double* cell_id_sums;
    time_t* timestamps;
    NR_CELL_INFO_PDU_T** data;
} DynamicList;

void dynamic_list_init(DynamicList* list, size_t initial_size) {
    pthread_mutex_init(&list->mutex, NULL);
    list->max_size = initial_size;
    list->current_size = 0;
    list->data = malloc(initial_size * sizeof(NR_CELL_INFO_PDU_T*));
    list->cell_id_sums = calloc(initial_size, sizeof(double));
    list->timestamps = malloc(initial_size * sizeof(time_t));
}

void dynamic_list_add(DynamicList* list, NR_CELL_INFO_PDU_T* item) {
    pthread_mutex_lock(&list->mutex);

    if (list->current_size >= list->max_size) {
        // Resize the array when reaching maximum size
        list->max_size *= 2;
        list->data = realloc(list->data, list->max_size * sizeof(NR_CELL_INFO_PDU_T*));
        list->cell_id_sums = realloc(list->cell_id_sums, list->max_size * sizeof(double));
        list->timestamps = realloc(list->timestamps, list->max_size * sizeof(time_t));
    }

    // Add the item and update sums for its cell id
    list->data[list->current_size] = item;
    list->cell_id_sums[item->cell_id] += item->rsrp_level;
    list->timestamps[item->cell_id] = item->timestamp;
    ++(list->current_size);

    pthread_mutex_unlock(&list->mutex);
}

double dynamic_list_get_average_rscp(DynamicList* list, int cell_id) {
    double average = 0.0;

    // Remove old entries from calculation
    for (size_t i = 0; i < list->current_size; ++i) {
        NR_CELL_INFO_PDU_T* item = list->data[i];

        if (item->cell_id == cell_id && difftime(item->timestamp, list->timestamps[cell_id]) > TIMEWINDOW) {
            list->cell_id_sums[cell_id] -= item->rsrp_level;
        }
    }

    pthread_mutex_lock(&list->mutex);

    average = (list->current_size > 0) ? list->cell_id_sums[cell_id] / list->current_size : 0.0;

    pthread_mutex_unlock(&list->mutex);

    return average;
}
