['Here's how you might approach this problem using C programming language:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char request[1024];
    time_t timestamp;
} Request;

int processLogFile(char *filename, double bandwidthLimit) {

    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return 1;
    }

    Request **requests = malloc(sizeof(Request*));
    if (requests == NULL) {
        printf("Memory allocation error\n");
        return 2;
    }

    int numOfRequests = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {

        if (numOfRequests > 0 && ((double)strlen(line)/sizeof(line)) > bandwidthLimit) {
            printf("Bandwidth limit exceeded. Request ignored: %s\n", line);
            continue;
        }

        requests = realloc(requests, (numOfRequests+1)*sizeof(Request*));
        if (requests == NULL) {
            printf("Memory allocation error\n");
            return 2;
        }

        Request *new_req = malloc(sizeof(Request));
        if (new_req == NULL) {
            printf("Memory allocation error\n");
            return 2;
        }

        time(&new_req->timestamp);
        strncpy(new_req->request, line, sizeof(line)-1);
        new_req->request[sizeof(line)-1] = '\0';

        requests[numOfRequests++] = new_req;
    }

    fclose(file);

    if (numOfRequests == 0) {
        printf("No valid request found\n");
        free(requests);
        return 3;
    }

    double totalBandwidth = 0.0;
    for (int i=0; i<numOfRequests; ++i) {
        ++totalBandwidth;
    }

    printf("Total bandwidth usage: %.2f MB\n", totalBandwidth);

    for(int i = 0; i < numOfRequests; ++i) 
        free(requests[i]);

    free(requests);

    return 0;
}
```
The function reads a log file line by line, validates each request (size check and timestamp comparison), adds it to the requests array if it passes validation, then calculates total bandwidth. It cleans up any memory allocated during execution, prints appropriate error messages in case of an issue, and returns appropriate codes to indicate success/failure conditions.
