```python
import os
from PIL import Image
from PIL.ExifTags import TAGS
import exifread

def extract_metadata(image_path):
    try:
        with open(image_path, 'rb') as image_file:
            tags = exifread.process_file(image_file)
            return {TAGS.get(tag, tag): value for tag, value in tags.items()}
    except Exception as e:
        print(f"Error while reading metadata from {image_path}: {str(e)}")
        return {}

def traverse_directory(directory_path):
    resolution_sum = 0
    camera_model = ''
    unusual_metadata = []
    image_count = 0

    for root, dirs, files in os.walk(directory_path):
        for file in files:
            if not file.lower().endswith(('.jpg', '.jpeg')):
                continue

            image_path = os.path.join(root, file)
            metadata = extract_metadata(image_path)

            # Extract resolution and camera model info
            if 'EXIF ExifImageWidth' in metadata and 'EXIF ExifImageLength' in metadata:
                width, length = int(metadata['EXIF ExifImageWidth']), int(metadata['EXIF ExifImageLength'])
                resolution_sum += (width * length)

            if 'Image Make' in metadata:
                camera_model = metadata.get('Image Make', camera_model)

            # Detect unusual metadata patterns
            for tag, value in metadata.items():
                if str(value).startswith('Error'):
                    unusual_metadata.append((tag, str(value)))

            image_count += 1

    average_resolution = (resolution_sum / image_count) if image_count > 0 else 0
    return {
        'average_resolution': average_resolution,
        'most_common_camera_model': camera_model,
        'unusual_metadata': unusual_metadata
    }
```

