char* str_check(const char *str, size_t limit, int strict) {
    if (str == NULL) return NULL; // Handle potential null pointer dereferences

    size_t len = strlen(str); 

    if ((strict && len > limit) || (!strict && len >= limit)) {
        return NULL; // Return NULL if the input string exceeds the size limit
    }

    char *result = malloc(len + strlen(SUFFIX) + 1); // Allocate memory for result string

