    strcpy(new_str, str);
    if (len <= sizeLimit) {
        new_str[len] = '@';  // normal case
    } else if (strict && len > sizeLimit) {
        new_str[len] = '#';  // error case in strict mode
    } else {
        new_str[len] = '\0';  // string too long but not in strict mode, so return NULL
