char* check_file_size(const char* filepath, size_t maxSizeLimitInBytes, bool enforceStrictChecks) {
    if (filepath == NULL || *filepath == '\0') {
        fprintf(stderr, "Null or empty string provided as file path.\n");
        return NULL;
    }

    struct stat st;
    if (stat(filepath, &st) != 0) {
        perror("Failed to get file status: ");
        return NULL;
    }

    size_t fileSizeInBytes = st.st_size;

    if (enforceStrictChecks && maxSizeLimitInBytes < strlen(filepath)) {
        fprintf(stderr, "File path length exceeds the specified limit.\n");
        return NULL;
    }

    if (fileSizeInBytes > maxSizeLimitInBytes) {
        fprintf(stderr, "File size exceeded the maximum allowed file size.\n");
        return NULL;
    } 

    char* newPath = malloc((strlen(filepath) + 1) * sizeof(char));
    if (newPath == NULL) {
        perror("Failed to allocate memory for new path: ");
        return NULL;
    }

    strncpy(newPath, filepath, strlen(filepath) + 1); 
    return newPath;
}
```
