['Here is a basic implementation of your task using C with POSIX threads, memory mapping, and log4c for logging:

```C
#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <pthread.h>
#include <log4c.h>

typedef struct {
    char *filepath;
    size_t sizeLimit;
    log4c_category_t* logger;
} ThreadArgs;

void *processFile(void *arg) {
    ThreadArgs *threadArgs = (ThreadArgs *) arg;
    int fd = open(threadArgs->filepath, O_RDWR);
    if (fd == -1) {
        log4c_error(threadArgs->logger, "Could not open file: %s", threadArgs->filepath);
        return NULL;
    }

    struct stat sb;
    fstat(fd, &sb);

    char *data = mmap(NULL, sb.st_size, PROT_WRITE, MAP_SHARED, fd, 0);
    if (data == MAP_FAILED) {
        log4c_error(threadArgs->logger, "Could not map file: %s", threadArgs->filepath);
        return NULL;
    }

    for (char *p = data; p < data + sb.st_size; ++p) {
        if (*p == '\n' && (p - data + 1) > threadArgs->sizeLimit) {
            log4c_error(threadArgs->logger, "Line too large: %s", threadArgs->filepath);
            return NULL;
        } else if (*p == '\n') {
            *p = '/';
        }
    }

    msync(data, sb.st_size, MS_SYNC);
    munmap(data, sb.st_size);
    close(fd);

    return NULL;
}

void processFilesParallel(char *filepaths[], size_t fileCount, size_t sizeLimit, char *logPath) {
    log4c_init();
    log4c_category_t* logger = log4c_category_get("my.logger");
    log4c_appender_t* appender;

    if (access(logPath, F_OK) != -1 ) {
        remove(logPath);
    }

    appender = log4c_appender_file_open(logPath, "a");
    log4c_category_set_appender(logger, appender);
    log4c_category_set_priority(logger, LOG4C_PRIORITY_TRACE);

    pthread_t threads[fileCount];
    ThreadArgs threadArgsArray[fileCount];

    for (size_t i = 0; i < fileCount; ++i) {
        ThreadArgs *threadArgs = &threadArgsArray[i];
        threadArgs->filepath = filepaths[i];
        threadArgs->sizeLimit = sizeLimit;
        threadArgs->logger = logger;

        if (pthread_create(&threads[i], NULL, processFile, (void *) threadArgs)) {
            log4c_error(logger, "Could not create thread for file: %s", threadArgs->filepath);
        }
    }

    for (size_t i = 0; i < fileCount; ++i) {
        pthread_join(threads[i], NULL);
    }

    log4c_appender_close(appender);
    log4c_fini();
}
```
This code does not include the command line argument parsing, file statistics collection, and CSV exporting as these are quite specific and would need to be implemented separately. This is just a basic template of how you could set up your multi-threaded memory mapped I/O function with logging in C. Please note that this code uses POSIX threads and the log4c library, both of which may not be available on all systems.
']

