// Function to remove trailing slashes unless the path ends with a dot and resolve symbolic links
char* process_path(const char *path) {
    size_t len = strlen(path);

    // Allocate memory for new path, initialize null terminator to make it safe from overflowing
    char *newPath = malloc(len + 1);
    if (newPath == NULL) return NULL; 

    size_t i = 0, j = 0;
    while (i < len) {
        // If the path ends with a dot or slash, don't remove it
        if ((path[i] != '.' && path[i] != '/') || (isalpha(path[len-2]) != 0)) 
            newPath[j++] = path[i];
        i++;
    }

    // Null terminate the string and return
    newPath[j] = '\0';
    return newPath;
}
