        // Combine the results of the external API and the switch case
        List<String> weaknesses = new ArrayList<>();

        for (String move : moves) {
            if (move.equals("Fireball") && weather == WeatherReport.RAINY) {
                weaknesses.add("Weak to Water type");
            }

            // Handle other conditions...
        }

        return weaknesses;
    }
}
