        // Handle error here
    }

    // Compute the MD5 hash of the message in chunks to prevent excessive memory usage
    unsigned char md5[MD5_DIGEST_LENGTH];
    if (!computeMD5InChunks(decrypted, decrypted_len, md5)) {
        // Handle error here
