['C doesn't natively support multithreading, so we will use POSIX Threads (pthreads) for concurrency control. Here is a basic implementation of your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct {
    int CELL_ID;
    int PCI;
    int RSRP_LEVEL;
    time_t TIMESTAMP;
} NR_CELL_INFO_PDU_T;

typedef struct {
    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
    NR_CELL_INFO_PDU_T *data;
} DynamicArray;

DynamicArray* initArray(size_t capacity) {
    DynamicArray *arr = mmap(NULL, sizeof(*arr), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (arr == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }

    arr->capacity = capacity;
    arr->length = 0;
    pthread_mutex_init(&(arr->lock), NULL);
    arr->data = mmap(NULL, sizeof(*arr->data) * capacity, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (arr->data == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }

    return arr;
}

int addElement(DynamicArray *arr, NR_CELL_INFO_PDU_T elem) {
    pthread_mutex_lock(&(arr->lock));
    if (arr->length == arr->capacity) {
        size_t newCapacity = arr->capacity * 2;
        NR_CELL_INFO_PDU_T* newData = realloc(arr->data, sizeof(*newData) * newCapacity);
        if (newData == NULL) {
            perror("realloc");
            pthread_mutex_unlock(&(arr->lock));
            return -1;
        }

        arr->capacity = newCapacity;
        arr->data = newData;
    }

    memcpy(&(arr->data[arr->length++]), &elem, sizeof(elem));
    pthread_mutex_unlock(&(arr->lock));
    return 0;
}

