    while ((bytesRead = read(inputFD, buf, sizeof(buf))) > 0) {
        if (write(outputFD, buf, bytesRead) == -1) {
            perror("write");
            close(inputFD);
            close(outputFD);
            return;
        }
    }

    close(inputFD);
    close(outputFD);
}

int main() {
    DynamicArray *arr = initArray(50);
    if (arr == NULL) {
        exit(EXIT_FAILURE);
    }

    NR_CELL_INFO_PDU_T elem;
    // TODO: Assign values to elem.

    addElement(arr, elem);

    char* inputFileName = "input.txt";
    char* outputFileName = "output.txt";
    char* transformationRules = "rules";
