```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int rx_buffer;
} MAC_RX_BUFFER;

typedef struct {
    int buffer_size;
    MAC_RX_BUFFER *rx_buffers;
} MAC_CONTEXT_T;

void logError(const char* message) {
    printf("ERROR: %s\n", message);
}

MAC_CONTEXT_T initializeMACContext(int bufferLimit) {
    MAC_CONTEXT_T macContext;
    srand(time(NULL)); // Seed random number generator

    int bufferSize = rand() % bufferLimit + 1; // Generate random buffer size within limit.
    macContext.buffer_size = bufferSize;

    macContext.rx_buffers = malloc(macContext.buffer_size * sizeof(MAC_RX_BUFFER));
    if (macContext.rx_buffers == NULL) {
        logError("Failed to allocate memory for MAC_CONTEXT_T");
        exit(-1); // Terminate the program in case of error
    } else {
        printf("Successfully allocated memory for MAC_CONTEXT_T\n");
    }

    return macContext;
}
```
In this code, `initializeMACContext` initializes a MAC context with a random buffer size (not exceeding the provided limit). It uses dynamic memory allocation to allocate space for the `rx_buffers` array. If memory allocation fails (i.e., `malloc` returns NULL), an error message is logged and the program is terminated. This function also takes into account best practices for error handling in C, by immediately checking if the allocation was successful and logging any errors.
