    public DocumentHub(IUserService userService, IDocumentService documentService)
    {
        _userService = userService;
        _documentService = documentService;
    }

    // Authenticate the client and check if they have permissions to edit the document
    private async Task<bool> Authenticate(string userId, string token)
    {
        var isAuthenticated = await _userService.IsUserValidAsync(userId, token);
        if (!isAuthenticated) return false;

        var hasPermission = await _documentService.HasEditPermissionAsync(userId);
        return hasPermission;
    }

    public async Task JoinGroup(string userId, string token, int documentId)
    {
        if (await Authenticate(userId, token)) 
        {
            await Groups.AddToGroupAsync(Context.ConnectionId, $"Document_{documentId}");

            var documentData = await _documentService.GetDocumentDataAsync(documentId);
            await Clients.Caller.SendAsync("ReceiveDocument", documentData);
        } 
        else
        {
            Context.Abort();
        }
    }

    public async Task UpdateDocument(int documentId, string data)
    {
        var userId = Context.UserIdentifier;
        await _documentService.UpdateDocumentAsync(userId, documentId, data);

        await Clients.Group($"Document_{documentId}").SendAsync("ReceiveDocument", data);
    }

    public override async Task OnDisconnectedAsync(Exception exception)
    {
        // Handle stale connections here
        await base.OnDisconnectedAsync(exception);
    }
}
```
The `JoinGroup` method handles the initial connection and checks if the user has the necessary permissions to edit the document. The `UpdateDocument` method allows clients to update the document, which is then broadcasted to all other connected clients in the same group. 

This is a simplified example and real-world implementation would require handling more edge cases and optimizing for low latency such as connection pooling, batch updates etc. Also, you need to handle exceptions properly based on your business requirements. 

Make sure to install `Microsoft.AspNetCore.SignalR` nuget package before using this code. Also don't forget to register the SignalR service in your startup class like so:
```csharp
