```java
import java.io.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import org.apache.commons.codec.digest.*;
import org.slf4j.*;

public class StateObjectLoader {

    private static final Logger logger = LoggerFactory.getLogger(StateObjectLoader.class);
    private static final Digester digester = new Digester(DigestAlgorithm.SHA_256);

    // Cache to hold the deserialized objects
    private static LoadingCache<String, Object> cache;

    // Thread-safe way to calculate checksum
    public synchronized String getChecksum(File file) {
        try (InputStream is = new FileInputStream(file)) {
            return digester.digestAsHex(is);
        } catch (IOException | DigesterException e) {
            logger.error("Error while calculating checksum", e);
            return null;
        }
    }

    // Thread-safe method to load and cache the object
    public Object loadAndCacheObject(String filePath, String expectedChecksum) {
        try {
            File file = new File(filePath);
            String checksum = getChecksum(file);

            if (checksum == null || !checksum.equals(expectedChecksum)) {
                logger.error("File is corrupted");
                return null;
            }

            // Check the cache first
            Object cachedObject = cache.getIfPresent(filePath);
            if (cachedObject != null) {
                logger.info("Loaded from cache: " + filePath);
                return cachedObject;
            }

            try (FileInputStream fis = new FileInputStream(file);
                 ObjectInputStream ois = new ObjectInputStream(fis)) {

                 // Load the object and put it in the cache
                 Object loadedObject = ois.readObject();
                 cache.put(filePath, loadedObject);

                 logger.info("Loaded from file: " + filePath);
                 return loadedObject;
            } catch (IOException | ClassNotFoundException e) {
                logger.error("Error while loading object", e);
                return null;
            }
        } catch (ExecutionException e) {
            logger.error("Cache execution error", e);
            return null;
        }
    }

    // Cache setup, use guava library's LoadingCache for thread-safe cache operations
    static {
        cache = CacheBuilder.newBuilder()
                .maximumSize(100)  // adjust based on system capacity and requirements
                .expireAfterWrite(5, TimeUnit.MINUTES)  // set expiration time to 5 minutes
                .build(new CacheLoader<String, Object>() {
                    @Override
                    public Object load(String filePath) throws Exception {
                        return loadAndCacheObject(filePath, null);  // checksum check is handled in loadAndCacheObject method
                    }
                });
    }
}
```
This code includes a thread-safe cache, logging mechanism for troubleshooting, and file integrity verification using SHA-256 checksums. The cache automatically removes objects after a specified time limit (in this case, 5 minutes), which prevents memory leaks over time. This class is designed to scale well with increased load by utilizing caching to avoid redundant deserialization of the same files and by ensuring thread safety when multiple threads attempt to load the state object simultaneously.
