```javascript
function generateModuleOverview(modules) {
  let html = '';

  // Create loading indicator
  const loadingIndicator = `<div id="loading-indicator">Loading...</div>`;
  document.body.innerHTML += loadingIndicator;

  modules.forEach((module, index) => {
    html += `<div class="module" id="module_${index}">`;

    // Create collapsible section
    const collapsibleSection = `<details>
                                  <summary>${module.name}</summary>
                                  <p>${module.description}</p>
                                  ${(module.dependencies && module.dependencies.length > 0) ? 
                                    'Dependencies: <ul><li>' + module.dependencies.join('</li><li>') + '</li></ul>': 
                                    'No dependencies'}
                                </details>`;
    html += collapsibleSection;

    // End div for module
    html += '</div>';

    // Periodically update the DOM to ensure responsiveness
    if (index % 50 === 0) {
      document.body.innerHTML = loadingIndicator + html;
    }
  });

  // Remove loading indicator and append final HTML
  document.getElementById('loading-indicator').remove();
  document.body.innerHTML += html;

  return html;
}
```
This function dynamically generates the required HTML as a string, optimizes for performance by avoiding unnecessary DOM manipulations, and ensures efficient handling of large datasets by periodically updating the DOM to maintain responsiveness. It also includes a loading indicator while fetching module data asynchronously. 

