def read_and_sort(config_file):
    try:
        with open(config_file, 'r') as file:
            lines = file.readlines()

        # Sort the lines and extract the sequence number
        sorted_lines = sorted(lines)
        last_line = sorted_lines[-1]
        seq_num = int(last_line.split(' ')[1])  # Assume sequence number is second word in line

        return seq_num

