use std::fs::File;
use std::io::prelude::*;
use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use std::thread;
use serde_json;

// Struct to store configuration data
pub struct Config {
    pub settings: HashMap<String, String>,
}

impl Config {
    fn new() -> Self {
        Config {
            settings: HashMap::new(),
        }
    }

    // Load config from file
    pub fn load_from_file(&mut self, path: &str) -> Result<(), std::io::Error> {
        let mut file = File::open(path)?;
        let mut contents = String::new();
        file.read_to_string(&mut contents)?;
        let config: HashMap<String, String> = serde_json::from_str(&contents)?;
        self.settings = config;
        Ok(())
    }
}

pub fn main() {
    // Initialize configuration cache
    let cache = Arc::new(Mutex::new(HashMap::new()));

    loop {
        thread::sleep(Duration::from_secs(10));

        // Check if config is in cache
        match cache.lock().unwrap().get("config") {
            Some(_) => continue,
            None => {
                let mut config = Config::new();

                // Load config from file
                match config.load_from_file("path/to/config.json") {
                    Err(e) => println Err(e),
                    Ok(_) => {
                        // Store in cache
                        cache.lock().unwrap().insert("config", config);
                    }
                }
            }
        }
    }
}
```
