["Here's an example of how you might implement this task in C using pthread library for thread safety, rand() function for probabilistic random generator and structs for the data structures. This is a simplified implementation and may need to be adjusted based on your exact requirements. 

Please note that this code does not include all the edge cases you mentioned (like handling memory exhaustion) because it would require extensive error checking and handling which can make the code quite complex. Also, remember to compile with -pthread flag for thread safety features in C.

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUeInfoTag;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    time_t lastAccessedTime;  // For periodic cleanup of inactive elements
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** list;
    int capacity;
    int size;
    pthread_mutex_t lock;  // For thread safety
} DynamicList;

DynamicList* createDynamicList() {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (list == NULL) return NULL;

    list->capacity = 10;
    list->size = 0;
    list->list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * list->capacity);
    if (list->list == NULL) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);  // Initialize lock

    return list;
}

void addElementToList(DynamicList* dynList, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&dynList->lock);  // Lock for thread safety

    if (dynList->size >= dynList->capacity) {
        dynList->capacity *= 2;
        dynList->list = realloc(dynList->list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * dynList->capacity);
    }

    dynList->list[dynList->size] = element;
    dynList->size++;

    pthread_mutex_unlock(&dynList->lock);  // Unlock
}

NFAPI_CRC_INDICATION_PDU_T* getElementByRNTI(DynamicList* dynList, int rnti) {
    for (int i = 0; i < dynList->size; ++i) {
        if (dynList->list[i]->rxUeInfoTag.RNTI == rnti) return dynList->list[i];
    }

    return NULL;  // Return null if no element found
}

void periodicCleanup(DynamicList* dynList, int timeout) {
    pthread_mutex_lock(&dynList->lock);  // Lock for thread safety

    time_t currentTime = time(NULL);
    for (int i = 0; i < dynList->size; ++i) {
        if ((currentTime - dynList->list[i]->lastAccessedTime) > timeout) {
            free(dynList->list[i]);  // Free inactive elements

            for (int j = i; j < dynList->size - 1; ++j) {  // Shift remaining elements to fill the gap
                dynList->list[j] = dynList->list[j + 1];
            }

            dynList->size--;
        }
    }

    pthread_mutex_unlock(&dynList->lock);  // Unlock
}
