['Here is a simple implementation of a DHT in C++ using a hash table with linked lists as buckets for collision resolution. Please note that this is just a basic implementation and doesn't cover all the aspects mentioned in your problem, such as actual network infrastructure integrations or data replication/deletion mechanisms among peers.

```cpp
#include <iostream>
#include <list>
#include <vector>
#include <stdexcept>

class DHT {
private:
    struct Node{
        std::string key;
        int value;
        bool operator==(const Node& node) const {
            return this->key == node.key && this->value == node.value;
        }
    };

    int partition_size, data_capacity;
    std::vector<std::list<Node>> buckets;

public:
    DHT(int numNodes, int partitionSize, int dataCapacity){
        if(numNodes <= 0 || partitionSize <= 0 || dataCapacity <=0){
            throw std::invalid_argument("All arguments must be positive");
        }
        buckets.resize(numNodes * partitionSize);
        this->partition_size = partitionSize;
        this->data_capacity = dataCapacity;
    }

    size_t hashFunction(std::string key){
        return std::hash<std::string>{}(key) % buckets.size();
    }

    void insert(Node node){
        try {
            if (buckets[hashFunction(node.key)].size() >= data_capacity) {
                rebalance(node);
            } else {
                buckets[hashFunction(node.key)].push_back(node);
            }
        } catch (std::bad_alloc& e){
            std::cerr << "Memory allocation failed : " << e.what() << "\n";
        }
    }

    bool find(Node node){
        auto &bucket = buckets[hashFunction(node.key)];
        for (const auto& n: bucket) {
            if(n == node) return true;
        }
        return false;
    }

    void erase(Node node){
        auto &bucket = buckets[hashFunction(node.key)];
        bucket.remove_if([&](const Node& n) {return n == node;});
    }

    void rebalance(Node node){
        // A very simple rebalancing strategy: doubling the size of the table. 
        int oldSize = buckets.size();
        std::vector<std::list<Node>> newBuckets (oldSize * 2);

        for (auto &bucket : buckets) {
            while (!bucket.empty()) {
                Node n = bucket.front();
                bucket.pop_front();
                newBuckets[hashFunction(n.key) % (newBuckets.size())].push_back(n);
            }
        }
        buckets = std::move(newBuckets);
    }
};
```
This code implements a very basic DHT where each node can hold a certain amount of data before rebalancing (doubling the table size) to maintain performance. This is a simplistic approach and might not be suitable for all use cases as it does not cover potential network failures, data replication/deletion across peers etc.
']

