['Here is an example of how such a class might be implemented in C# using System.Random, Dictionary for caching, and custom Range structure:
```csharp
using System;
using System.Collections.Generic;

public struct Range
{
    public int Min { get; set; }
    public int Max { get; set; }
    public bool Closed { get; set; }
}

public class AdvancedRandomValueGenerator
{
    private readonly Random _random;
    private Dictionary<Range, List<int>> _cache = new Dictionary<Range, List<int>>();
    private int _seed;

    public Range CurrentRange { get; set; }

    public AdvancedRandomValueGenerator(int seed)
    {
        this._random = new Random(this._seed = seed);
    }

    public int NextInt()
    {
        if (_cache.ContainsKey(CurrentRange))
        {
            var list = _cache[CurrentRange];
            if (list.Count == 0) return GenerateNewRandomValueAndCacheIt();

            var index = _random.Next(0, list.Count);
            var value = list[index];
            list.RemoveAt(index);
            return value;
        }

        return GenerateNewRandomValueAndCacheIt();
    }

    private int GenerateNewRandomValueAndCacheIt()
    {
        if (CurrentRange.Min > CurrentRange.Max) throw new InvalidOperationException("Invalid range");

        var value = _random.Next(
            CurrentRange.Closed ? CurrentRange.Min : CurrentRange.Min + 1, 
            CurrentRange.Closed ? CurrentRange.Max + 1 : CurrentRange.Max);

        if (!_cache.ContainsKey(CurrentRange))
        {
            _cache[CurrentRange] = new List<int>();
        }

        _cache[CurrentRange].Add(value);
        return value;
    }

    public int[] NextInts(int length)
    {
        var values = new int[length];
        for (var i = 0; i < length; i++)
        {
            values[i] = NextInt();
        }

        return values;
    }

    public override string ToString() => $"Seed: {_seed}, CurrentRange: {CurrentRange}";

    public void Reset()
    {
        _cache.Clear();
        // seed should be preserved
        this._random = new Random(_seed);
    }
}
```
This is a simplified example and might not cover all the edge cases or logging requirements mentioned in your problem description, but it gives an idea of how to start building such a class. Please note that for real-world applications, you'd likely want to use a mature logging library like NLog or Serilog instead of writing directly to console.
