            {"output", required_argument, 0, 'o'},
            {"log", no_argument, 0, 'l'}
        };

        int c = getopt_long(argc, argv, "i:o:l", long_options, &option_index);
        if (c == -1) break;

        switch (c) {
            case 'i': opts.input_file = optarg; break;
            case 'o': opts.output_file = optarg; break;
            case 'l': opts.log_enabled = 1; break;
            default: exit(EXIT_FAILURE);
