        return EXIT_FAILURE;
    }

    char *line = NULL;
    size_t len = 0;
    while (getline(&line, &len, input_file) != -1) {
        pthread_t thread;
        // Dynamically allocate memory for line. This can be optimized depending on the use case.
        char *copy = malloc(strlen(line) + 1); 
        strcpy(copy, line);
