#define MAX_THREADS 10 // Adjust this to suit your system's capacity

typedef struct {
    char *filename;
    /* Add other necessary data for each file */
} FileData;

void *processFile(void *arg) {
    FileData *data = (FileData *) arg;

    /* Process the file here. You may want to use error handling here too */

    free(data->filename); // Clean up allocated memory
    free(data);
    return NULL;
}

int processDirectory(char *directory) {
    DIR *dir = opendir(directory);
    if (dir == NULL) return 1; // Handle error here

    pthread_t threads[MAX_THREADS];
    int threadCount = 0, ret = 0;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue; // Skip '.' and '..' directories

        FileData *data = malloc(sizeof(FileData));
        data->filename = malloc(strlen(entry->d_name) + 1);
        strcpy(data->filename, entry->d_name); // Allocate and copy filename

        /* Fill in other necessary data for each file */

        if (threadCount >= MAX_THREADS) {
            pthread_join(threads[--threadCount], NULL); // Wait for one thread to finish before adding another
        }

        ret = pthread_create(&threads[threadCount++], NULL, processFile, data);
        if (ret != 0) return 1; // Handle error here
    }

    closedir(dir);

    for (int i = 0; i < threadCount; ++i) {
        pthread_join(threads[i], NULL); // Wait for all threads to finish
    }

    return 0;
}
```

This code uses POSIX threads to concurrently process the files in a directory. It assumes that each file is small enough to be processed by one thread without causing excessive memory usage, and that you are running this on a system where you can safely create many threads. For handling errors more gracefully, you might want to add some error checking code.

