    }

    structArray = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * totalStructures);

    fpIn = fopen(inputFile, "rb");
    pthread_t* threadsRead = malloc(totalStructures * sizeof(pthread_t));

    // create threads for reading structures from file
    for (int i = 0; i < totalStructures; i++) {
        pthread_create(&threadsRead[i], NULL, processStructure, (void*)i);
    }

    fpOut = fopen(outputFile, "wb");
    pthread_t* threadsWrite = malloc(totalStructures * sizeof(pthread_t));

    // create threads for writing structures to file
    for (int i = 0; i < totalStructures; i++) {
        pthread_create(&threadsWrite[i], NULL, writeToFile, (void*)i);
    }

    // wait for all read and write threads to finish
    for(int i = 0; i < totalStructures; i++) {
        pthread_join(threadsRead[i], NULL);
        pthread_create(&threadsWrite[i], NULL, transformStructure, (void*)i);
        pthread_join(threadsWrite[i], NULL);
