    size_t capacity;
    pthread_mutex_t lock;
} ConnectionPoolManager;

ConnectionPoolManager manager = {{0, 0}, 0, PTHREAD_MUTEX_INITIALIZER};

DB_CONNECTION_POOL_T* get_connection_pool(int id) {
    for (size_t i = 0; i < manager.capacity; ++i) {
        if (manager.pools[i].id == id) {
            return &manager.pools[i];
        }
    }
    return NULL;
}

int add_connection_pool(DB_CONNECTION_POOL_T pool) {
    pthread_mutex_lock(&manager.lock);
    ++manager.capacity;
    manager.pools = realloc(manager.pools, sizeof(*manager.pools)*manager.capacity);
    if (NULL == manager.pools) {
        // Error handling
        pthread_mutex_unlock(&manager.lock);
        return -1;
    }
    manager.pools[manager.capacity-1] = pool;
    pthread_mutex_unlock(&manager.lock);
    return 0;
}
