```cpp
#include <unordered_map>
#include <memory>
#include <mutex>
#include <shared_mutex>  // Need for shared_lock in c++14 and higher.

// Forward declaration to resolve circular dependency.
class ConfigManager;

struct ValueBase {
    virtual ~ValueBase() = default; 
};
template<typename T>
struct TypedValue : public ValueBase {
    explicit TypedValue(T value) : value_(std::move(value)) {}
    T value_;
};

class ConfigSection {
public:
    template <typename T>
    void Set(const std::string& key, T value) {
        std::lock_guard<std::shared_mutex> lock(mtx_);
        data_[key] = std::make_unique<TypedValue<T>>(value);
    }

    template <typename T>
    T Get(const std::string& key) const {
        std::shared_lock<std::shared_mutex> lock(mtx_); 
        auto it = data_.find(key);
        if (it != data_.end()) {
            if (auto* typedValue = dynamic_cast<TypedValue<T>*>(it->second.get()))
                return typedValue->value_;
        }
        throw std::runtime_error("Key not found");
    }

private:
    mutable std::shared_mutex mtx_;  // For multiple readers or single writer.
    std::unordered_map<std::string, std::unique_ptr<ValueBase>> data_;
};

class ConfigManager {
public:
    static ConfigManager& GetInstance() {
        static ConfigManager instance;
        return instance;
    }

    ConfigSection& GetSection(const std::string& name) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sections_.find(name);
        if (it != sections_.end()) 
            return *it->second;
        auto section = std::make_unique<ConfigSection>();
        auto* rawPtr = section.get();
        sections_[name] = std::move(section);
        return *rawPtr;
    }

private:
    ConfigManager() = default;  // Private constructor to prevent instantiation from outside the class.
    mutable std::mutex mtx_;  // For exclusive write access.
    std::unordered_map<std::string, std::unique_ptr<ConfigSection>> sections_;
};
```
