['```csharp
using System;
using System.IO;
using System.Diagnostics;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

public class WebAppManager
{
    private readonly ILogger _logger;

    public WebAppManager(ILogger<WebAppManager> logger) => _logger = logger;

    public async Task AddAndStartWebApplicationAsync(string directoryPath, string configDataSource)
    {
        if (string.IsNullOrWhiteSpace(directoryPath)) 
            throw new ArgumentException("Directory path cannot be null or whitespace", nameof(directoryPath));

        var webConfigFile = Path.Combine(directoryPath, "web.config");

        if (!File.Exists(webConfigFile))
        {
            _logger.LogInformation("Web.config file is missing in directory: {Directory}", directoryPath);
            return;
        }

        var runningApp = Process.GetProcessesByName(directoryPath);
        if (runningApp.Length > 0) 
        {
            _logger.LogInformation("Application already running in directory: {Directory}", directoryPath);
            return;
        }

        await Task.Run(() => AddWebApplication(webConfigFile));

        try
        {
            var configData = await GetExternalDataAsync(configDataSource);
            Process.Start($"{directoryPath}/application.exe", JsonConvert.SerializeObject(configData, Formatting.Indented));
        }
        catch (Exception ex) 
        {
            _logger.LogError(ex, "Failed to start application in directory: {Directory}", directoryPath);
        }
    }

    private async Task AddWebApplication(string webConfigFile)
    {
        var webApp = File.ReadAllText("webapp_template");

        try 
        { 
            await using var fileStream = new FileStream(webConfigFile, FileMode.Append);
            await using var streamWriter = new StreamWriter(fileStream);

            await streamWriter.WriteAsync(webApp);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to write web application into directory: {Directory}", Path.GetDirectoryName(webConfigFile));
        }
    }

    private async Task<dynamic> GetExternalDataAsync(string configSource)
    {
        try 
        {
            var externalData = await new HttpClient().GetStringAsync(configSource);

            return JsonConvert.DeserializeObject<dynamic>(externalData);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to retrieve data from source: {Source}", configSource);
            throw;
        }
    }
}
```
Please note that for security purposes the code above does not include robust validation mechanism such as directory traversal attacks or external data sources reliability check, it is only a simplified example of how to handle these aspects in more complex scenarios. Always remember about security and safety when developing software.
