['Here is the code that achieves the task described in C language using cJSON library for parsing and validating JSON object:
```c
#include <stdbool.h>
#include <string.h>
#include "cJSON.h"

// function to check if string has only lowercase letters
bool isLower(char *str) {
    while(*str != '\0'){
        if(!((*str >= 'a' && *str <= 'z'))) return false;
        str++;
    }
    return true;
}

// function to validate email format
bool isValidEmail(char *email) {
   // you can use a regex or a simpler method for checking the valid email address format
   // here we just check if it contains "@" and a domain
   char* atPos = strchr(email, '@');
   return (atPos != NULL && strchr(atPos + 1, '.') != NULL);
}

bool validateAuthMetadata(const char *jsonString) {
    cJSON *root = cJSON_Parse(jsonString);

    if(root == NULL){
        return false; // JSON is malformed
    }

    cJSON *username = cJSON_GetObjectItemCaseSensitive(root, "username");
    cJSON *email = cJSON_GetObjectItemCaseSensitive(root, "email");
    cJSON *role = cJSON_GetObjectItemCaseSensitive(root, "role");
    cJSON *preferences = cJSON_GetObjectItemCaseSensitive(root, "preferences");

    if(!username || !email || !role || strlen(username->valuestring) > 50 || strlen(username->valuestring) == 0 ||
       !isValidEmail(email->valuestring) || 
       (strcmp(role->valuestring, "admin") && strcmp(role->valuestring, "moderator") && strcmp(role->valuestring, "user"))){
        cJSON_Delete(root); // free the memory before returning false
        return false; 
    }

    if(preferences != NULL) {
        char **keys = cJSON_GetObjectKeys(preferences);

        for(int i = 0; keys[i]; ++i){
            cJSON *value = cJSON_GetObjectItemCaseSensitive(preferences, keys[i]);

            if(!isLower(keys[i]) || strlen(value->valuestring) > 100 || value->type != cJSON_String){
                cJSON_Delete(root); // free the memory before returning false
                return false; 
            }
        }
    }

    cJSON_Delete(root); // free the allocated JSON memory
    return true;
}
```
This code uses the C library `cJSON` for parsing and validating JSON objects. The `isLower()` function checks if a string contains only lowercase letters, while the `isValidEmail()` function verifies if an email address is in a proper format (it's a simple validation check; you may want to use more thorough methods or regex for professional projects).
The `validateAuthMetadata()` function parses the JSON object and checks each required field as described above. The memory allocated by cJSON is freed when done using `cJSON_Delete(root)`, which prevents memory leaks. If any validation fails, `false` is immediately returned after freeing the allocated memory. If all validations pass, `true` is returned at the end of the function.

Please note: you need to install cJson library (https://github.com/DaveGamble/cJSON) in your system before compiling this code. 
Also ensure that you have #include "cJSON.h" in your code and -lcjson flag while compiling the code. For example, gcc filename.c -o outputfilename -lcjson.
