['Here's an example of how you might structure such a function in C#. This is a simplified version and does not fully encapsulate all points in your requirements, but it gives you a good starting point:

```csharp
public class Decryptor
{
    private static Dictionary<string, byte[]> keyCache = new Dictionary<string, byte[]>();
    private readonly string fallbackKey;
    private readonly ILogger logger;

    public Decryptor(ILogger logger)
    {
        this.logger = logger;

        // load the fallback key from a secure location, such as an environment variable or secure vault service
        fallbackKey = Environment.GetEnvironmentVariable("Fallback_Encryption_Key");
    }

    public byte[] Decrypt(string cipherText, string encryptionKeyName)
    {
        var key = GetKeyFromCacheOrSource(encryptionKeyName);

        using (var aesAlg = Aes.Create())
        {
            // load the IV from secure location, such as an environment variable or secure vault service
            string ivString = Environment.GetEnvironmentVariable("IV");
            var ivBytes = Convert.FromBase64String(ivString);

            aesAlg.Key = key;
            aesAlg.IV = ivBytes;
            aesAlg.Padding = PaddingMode.PKCS7; // replace with your padding scheme

            var cipherTextBytes = Convert.FromBase64String(cipherText);

            using (var decryptor = aesAlg.CreateDecryptor())
            {
                byte[] plainTextBytes;

                try
                {
                    // measure the time taken for decryption and resource usage
                    var stopwatch = Stopwatch.StartNew();

                    using (var msDecrypt = new MemoryStream(cipherTextBytes))
                    {
                        using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                        {
                            using (var srDecrypt = new StreamReader(csDecrypt))
                            {
                                plainTextBytes = Convert.FromBase64String(srDecrypt.ReadToEnd());
                            }
                        }
                    }

                    stopwatch.Stop();
                    this.logger.LogInformation("Decryption took " + stopwatch.ElapsedMilliseconds + "ms");
                }
                catch (CryptographicException e)
                {
                    // handle invalid ciphertext or key errors gracefully
                    this.logger.LogError(e, $"Decryption failed for encryption key '{encryptionKeyName}'.");
                    return null;
                }

                return plainTextBytes;
            }
        }
    }

    private byte[] GetKeyFromCacheOrSource(string encryptionKeyName)
    {
        if (keyCache.ContainsKey(encryptionKeyName))
        {
            return keyCache[encryptionKeyName];
        }

        // load the key from a secure location, such as an environment variable or secure vault service
        var key = Environment.GetEnvironmentVariable(encryptionKeyName);

        if (key == null)
        {
            this.logger.LogWarning("Encryption key not found in cache or source, using fallback key.");
            key = fallbackKey;
        }
        else
        {
            // store the key in the cache for future use
            keyCache[encryptionKeyName] = Convert.FromBase64String(key);
        }

        return keyCache[encryptionKeyName];
    }
}
``` 
This is a simplified example and does not cover all your requirements. For instance, it does not handle partially decrypted data or rotate keys. You'll need to implement these features yourself based on the specifics of your project and use case. Also, please remember to add proper error handling in your application for this code snippet.
