['Sure, here's an example of how you could set up such a function using Node.js with Express. The following code assumes you have a third-party API key for OpenWeatherMap and is written in ES6 syntax:

```javascript
const express = require('express');
const fetch = require('node-fetch');
const rateLimit = require("express-rate-limit");
const NodeCache = require( "node-cache" );
const app = express();
app.use(express.json());

// Define cache and limiters:
let apiRequests = rateLimit({ windowMs: 15 * 60 * 1000, max: 100 });
let myCache = new NodeCache();

app.post('/weather', apiRequests, async (req, res) => {
    const cityName = req.body.city;

    // Input validation
    if(!/^[a-zA-Z\s]+$/.test(cityName)) {
        return res.status(400).json({ error: 'Invalid city name' });
    }

    try{
        let weatherData = myCache.get(cityName);

        if (weatherData) {
            return res.status(200).send(weatherData);
        } else {
            const apiResponse = await fetch(`http://api.openweathermap.org/data/2.5/weather?q=${cityName}&appid=YOUR_API_KEY`);

            if (!apiResponse.ok) throw new Error('Network response was not ok');

            weatherData = await apiResponse.json();

            myCache.set(cityName, weatherData, 60 * 60); // Cache for one hour

            return res.status(200).send(weatherData);
        }
    } catch (error) {
        console.log('Error: ', error);
        return res.status(500).json({ error: 'Failed to fetch weather data' });
    }
});
```
This is a simple example and doesn't include all the features you mentioned, but it should be a good starting point for your web application. You would need to replace `YOUR_API_KEY` with your actual API key from OpenWeatherMap. Also note that Node.js caching libraries like 'node-cache' are in-memory and may not be the best choice for a production environment, you might want to consider something more robust for such use cases.
']

