        self.name = name
        self.age = age

handler = JSONHandler()
p1 = Person('John Doe', 35)
serialized_data = handler.to_json(p1)

def create_person():
    return Person()

handler.register('person', create_person)

deserialized_obj = handler.from_json(serialized_data)
```
