function validateCityName(city) {
    const regexp = /^[a-zA-Z\s]*$/; 
    return city.match(regexp);
}

async function fetchWeatherData(city, apiKey) {
    if (!validateCityName(city)) {
        throw new Error('Invalid City Name');
    }

    const cachedResponse = myCache.get(city);

    if (cachedResponse) {
        console.log("Fetching from cache...");
        return Promise.resolve(JSON.parse(cachedResponse));
    } else {
        try {
            console.log('Making a new API call...');

            const response = await fetch(`http://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${apiKey}`);
            const data = await response.json();

            if (!response.ok) {
                throw new Error('Network response was not ok');
            }

            myCache.set(city, JSON.stringify(data), 10000); // Cache for 10 seconds
            return data;
        } catch (error) {
            console.log("Error: ", error.message);
            throw new Error('Unable to fetch weather data');
        }
    }
}
