const apiKey = process.env.WEATHER_API_KEY;
const weatherEndpoint = `http://api.openweathermap.org/data/2.5/weather?q={CITY}&appid=${apiKey}`;

app.get('/currentWeather', async (req, res) => {
  const city = req.query.city;
  if (!city || typeof city !== 'string') {
    return res.status(400).send('Invalid city name');
  }

  const cacheKey = `weather:${city}`;
  client.get(cacheKey, async (err, cachedData) => {
    if (cachedData) {
      console.log("Serving from Cache");
      return res.status(200).send({ weather: JSON.parse(cachedData), source: 'Cache' });
    } else { 
      try {
        const response = await axios.get(weatherEndpoint.replace('{CITY}', city));
        client.setex(cacheKey, 60 * 5, JSON.stringify(response.data), redis.print); // Cache for 5 minutes
        console.log("Serving fresh data");
        return res.status(200).send({ weather: response.data, source: 'API' });
      } catch (error) {
        if (error.response) {
          return res.status(error.response.status).send(error.response.data); // Forward API errors
        } else {
          console.log(error);
          return res.status(500).send('Internal Server Error');
        }
      }
    }
  });
});

const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Server running on ${port}, http://localhost:${port}`));
