['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

struct Line {
    char* content;
    double weighted_average;
};

void* processLine(void* arg) {
    struct Line* line = (struct Line*)arg;
    int i = 0, count = 0;
    double sum = 0.0;

    char* token = strtok(line->content, ",");
    while (token != NULL) {
        if (count >= 5 && isdigit(*token)) {
            sum += atof(token) * (i - 5 + 1);
        }

        i++;
        token = strtok(NULL, ",");
    }

    line->weighted_average = sum / 15.0;
    return NULL;
}

int main(int argc, char** argv) {
    FILE* inputFile = fopen("input.txt", "r"); // Change this to the file path you want
    if (inputFile == NULL) {
        printf("Failed to open input file\n");
        return 1;
    }

    char* lineBuffer = malloc(LINE_MAX);
    if (lineBuffer == NULL) {
        printf("Memory allocation failed\n");
        fclose(inputFile);
        return 2;
    }

    struct Line** lines = malloc(sizeof(struct Line*));
    int lineCount = 0, allocatedLines = 1;

    while (fgets(lineBuffer, LINE_MAX, inputFile)) {
        if (lines == NULL) {
            printf("Memory allocation failed\n");
            break;
        }

        struct Line* newLine = malloc(sizeof(struct Line));
        if (newLine == NULL) {
            printf("Memory allocation failed\n");
            free(lines);
            fclose(inputFile);
            return 2;
        }

        newLine->content = strdup(lineBuffer);
        lines[lineCount] = newLine;
        lineCount++;

        if (lineCount == allocatedLines) {
            struct Line** temp = realloc(lines, sizeof(struct Line*) * allocatedLines * 2);
            if (temp == NULL) {
                printf("Memory allocation failed\n");
                free(lines);
                fclose(inputFile);
                return 2;
            }

            lines = temp;
            allocatedLines *= 2;
        }
    }

    pthread_t* threads = malloc(sizeof(pthread_t) * lineCount);
    if (threads == NULL) {
        printf("Memory allocation failed\n");
        free(lines);
        fclose(inputFile);
        return 2;
    }

    for (int i = 0; i < lineCount; i++) {
        pthread_create(&threads[i], NULL, processLine, lines[i]);
    }

    for (int i = 0; i < lineCount; i++) {
        pthread_join(threads[i], NULL);
        printf("%s => %.2f\n", lines[i]->content, lines[i]->weighted_average);

        free(lines[i]->content);
        free(lines[i]);
    }

    fclose(inputFile);
    free(lineBuffer);
    free(threads);
    free(lines);
    return 0;
}
```
