#include <pthread.h>
#include <stdlib.h>

typedef struct frame_t {
    int RX_FRAME_TAG;
    float RX_POWER_LEVEL_TAG;
    unsigned RNTI;
    size_t crc32;
    time_t timestamp;
} frame_t;

struct node {
    frame_t *frame;
    struct node *next, *prev;
};

typedef struct {
    pthread_mutex_t lock;
    struct node *head, *tail;
    size_t count;
    float max_sum;
} list_t;

// This function computes the checksum of a frame (placeholder)
size_t compute_crc32(frame_t* frame);

void add_node(list_t *list, frame_t* frame) {
    pthread_mutex_lock(&list->lock);

    struct node *new_node = malloc(sizeof(*new_node));
    new_node->frame = frame;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        new_node->prev = NULL;
        list->head = list->tail = new_node;
    }

    frame->crc32 = compute_crc32(frame); // Compute and store CRC32
    ++list->count;

    float sum = frame->RX_FRAME_TAG * frame->RX_POWER_LEVEL_TAG;
    if (sum > list->max_sum) {
        list->max_sum = sum;
    }

    pthread_mutex_unlock(&list->lock);
}
