typedef struct {
    int ue_id;
    void *tx_data; // This could be any type, adjust as needed
} NFAPI_MESSAGE_T;

struct dynamic_array {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    NFAPI_MESSAGE_T *messages;
};
typedef struct dynamic_array DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *arr = malloc(sizeof(*arr));
    if (arr == NULL) return NULL; // Handle allocation failure.

    arr->messages = calloc(initial_capacity, sizeof(*arr->messages));
    if (arr->messages == NULL) {
        free(arr);
        return NULL;
    }

    pthread_mutex_init(&arr->lock, NULL); // Initialize mutex to handle concurrent access.
    arr->capacity = initial_capacity;
    arr->count = 0;
    return arr;
}

void add(DynamicArray *arr, int ue_id, void *tx_data) {
    pthread_mutex_lock(&arr->lock); // Lock to handle concurrent access.

    if (arr->count == arr->capacity) {
        size_t new_capacity = arr->capacity * 2; // Double capacity on resize.

        NFAPI_MESSAGE_T *new_messages = realloc(arr->messages, new_capacity * sizeof(*arr->messages));
        if (new_messages == NULL) {
            pthread_mutex_unlock(&arr->lock); // Unlock on allocation failure.
            return;
        }

        arr->messages = new_messages;
        arr->capacity = new_capacity;
    }

    arr->messages[arr->count].ue_id = ue_id;
    arr->messages[arr->count].tx_data = tx_data; // Assume the message data is dynamically allocated.
    ++arr->count;

    pthread_mutex_unlock(&arr->lock); // Unlock after adding item.
}

void destroy(DynamicArray *arr) {
    for (size_t i = 0; i < arr->count; ++i) {
        free(arr->messages[i].tx_data); // Free the tx_data for each message.
    }

    pthread_mutex_lock(&arr->lock); // Lock before freeing to avoid data corruption.
    free(arr->messages); // Free the messages array.
    arr->count = 0;
    arr->capacity = 0;
    pthread_mutex_unlock(&arr->lock);

    pthread_mutex_destroy(&arr->lock); // Destroy mutex to handle concurrent access.
    free(arr); // Free the array struct itself.
}
```
