DynamicLogList* createList() {
    DynamicLogList* list = malloc(sizeof(DynamicLogList));
    if (list == NULL) return NULL;

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    list->entries = malloc(INITIAL_CAPACITY * sizeof(LogEntry*));

    if (list->entries == NULL) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

int addToList(DynamicLogList* list, LogEntry* entry) {
    if (entry == NULL || list == NULL) return -1; // invalid input parameters

    pthread_mutex_lock(&list->mutex);

    if ((double)list->size / list->capacity * 100 > CAPACITY_THRESHOLD) {
        LogEntry** newEntries = realloc(list->entries, list->capacity * RESIZE_FACTOR * sizeof(LogEntry*));

        if (newEntries == NULL) return -2; // memory allocation failure

        list->entries = newEntries;
    }

    list->entries[list->size++] = entry;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void freeList(DynamicLogList* list) {
    if (list == NULL) return;

    for (int i = 0; i < list->size; ++i) {
        free(list->entries[i]->message);
        free(list->entries[i]->payload);
        free(list->entries[i]);
    }

    free(list->entries);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
