void* processFile(void *arg) {
    FileInfo *fileInfo = (FileInfo*) arg;
    char line[MAX_LINE_LEN];

    FILE *fp = fopen(fileInfo->filePath, "r");
    if (fp == NULL) {
        return NULL;
    }

    while (fgets(line, MAX_LINE_LEN, fp)) {
        int len = strlen(line);

        // Remove trailing newline character
        if (len > 0 && line[len-1] == '\n') {
            line[--len] = 0;
        }

        if (len > fileInfo->sizeLimit) {
            fclose(fp);
            return NULL;
        }

        // Append slash only if it doesn't exist
        if (line[len-1] != '/') {
            line[len++] = '/';
            line[len] = 0;
        }

        pthread_mutex_lock(&logMutex);
        write(fdLogFile, line, len);
        logSize += len;
        pthread_mutex_unlock(&logMutex);
    }

    fclose(fp);
    return NULL;
}

void* processFiles(char *configPath, int maxThreads, char **filePaths, 
                  int fileCount, int sizeLimit) {
