    // Read config file and set logFilePath

    fdLogFile = open(logFilePath, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fdLogFile == -1) {
        return NULL;
    }

    pthread_t threads[maxThreads];
    FileInfo fileInfos[fileCount];

    for (int i = 0; i < fileCount; ++i) {
        fileInfos[i].filePath = filePaths[i];
        fileInfos[i].sizeLimit = sizeLimit;

        if (pthread_create(&threads[i % maxThreads], NULL, processFile, &fileInfos[i]) != 0) {
            return NULL;  // Error creating thread
        }

        if ((i+1) % maxThreads == 0 || i == fileCount-1) {
            for (int j = i - maxThreads + 1; j <= i; ++j) {
                pthread_join(threads[j % maxThreads], NULL);
            }
        }
    }

    close(fdLogFile);
    return NULL;
}
