bool processAccessToken(const char *json) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if(!root) {
        fprintf(stderr, "Error: on line %d: %s\n", error.line, error.text);
        return false;
    }

    // Field checks
    json_t *access_token = json_object_get(root, "access_token");
    if(!json_is_string(access_token)) {
        fprintf(stderr, "Error: access_token is missing or invalid\n");
        return false;
    }

    json_t *expires_in = json_object_get(root, "expires_in");
    if(!json_is_integer(expires_in) || json_integer_value(expires_in) <= 0) {
        fprintf(stderr, "Error: expires_in is missing or invalid\n");
        return false;
    }

    json_t *token_type = json_object_get(root, "token_type");
    if(!json_is_string(token_type) || strcmp(json_string_value(token_type), "Bearer") != 0) {
        fprintf(stderr, "Error: token_type is missing or invalid\n");
        return false;
    }

    json_decref(root);

    pthread_mutex_lock(&lock);
    if(size >= MAX_ARRAY_SIZE) {
        fprintf(stderr, "Error: array is full\n");
        pthread_mutex_unlock(&lock);
        return false;
    }

    // Allocate memory for new element and populate it
    NFAPI_CRC_INDICATION_PDU_T *newElement = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if(!newElement) {
        fprintf(stderr, "Error: memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return false;
    }

    // Populate newElement fields here...

    array[size++] = *newElement;
    pthread_mutex_unlock(&lock);

    free(newElement);
    return true;
}
```
