public class DatabaseOperationService
{
    private readonly string connectionString;
    private static SqlConnection connection = null;

    public DatabaseOperationService(string connectionString)
    {
        this.connectionString = connectionString;
    }

    // Define a policy to handle transient failures.
    private AsyncPolicy retryPolicy => Policy
       .Handle<Exception>()
       .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

    // Define a policy to handle connection pool exhaustion.
    private AsyncPolicy<SqlConnection> connectionPoolPolicy = Policy<SqlConnection>
        .Handle<InvalidOperationException>()
        .FallbackAsync(async cancelToken => await CreateNewConnectionAsync(), 
            onFallbackAsync: (exception, context) => 
                { Trace.WriteLine("Fallback to new connection."); });

    private async Task<SqlConnection> OpenConnectionAsync()
    {
        if (connection == null || connection.State != System.Data.ConnectionState.Open)
            await CreateNewConnectionAsync();

        return connection;
    }

    private async Task<SqlConnection> CreateNewConnectionAsync()
    {
        connection = new SqlConnection(connectionString);
        await connection.OpenAsync();
        return connection;
    }

    public async Task ExecuteBatchOperationAsync(IEnumerable<string> operations)
    {
        var tasksToExecuteInParallel = new List<Task>();

        foreach (var operation in operations)
            tasksToExecuteInParallel.Add(PerformDatabaseOperationAsync(operation));

        await Task.WhenAll(tasksToExecuteInParallel);
    }

    private async Task PerformDatabaseOperationAsync(string query)
    {
        var stopwatch = new Stopwatch();
        stopwatch.Start();

        // Retry policy applied here. 
        await retryPolicy.ExecuteAsync(async () =>
        {
            using (var command = new SqlCommand(query, await connectionPoolPolicy.ExecuteAsync(() => OpenConnectionAsync())))
                await command.ExecuteNonQueryAsync();

        });

        stopwatch.Stop();
        Trace.WriteLine($"Operation '{query}' completed in {stopwatch.ElapsedMilliseconds}ms.");
    }

    public async Task PublishToQueue(string message)
    {
        var factory = new ConnectionFactory() { HostName = "localhost" };

        using (var connection = factory.CreateConnection())
        using (var channel = connection.CreateModel())
        {
            // Declare a queue - this is idempotent and will only be created if it doesn't already exist.
            channel.QueueDeclare(queue: "my_microservices_queue", durable: false, exclusive: false, autoDelete: false, arguments: null);

            var body = System.Text.Encoding.UTF8.GetBytes(message);

            // Publish a message to the queue.
            channel.BasicPublish(exchange: "", routingKey: "my_microservices_queue", basicProperties: null, body: body);
        }

        await Task.CompletedTask;
    }
}
```
