    char extra_sample_info[1024];
} ImageData;

ImageData parseTiff(const char *filepath) {
    TIFF* tif = TIFFOpen(filepath, "r");
    if (tif == NULL) {
        fprintf(stderr, "Error opening file\n");
        exit(-1);
    }

    ImageData data;
    // Parse image metadata
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &data.bps);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &data.spp);
    TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &data.extra_samples);

    if (data.bps != 1 && data.bps != 2 && data.bps != 4 && data.bps != 8 && data.bps != 16) {
        fprintf(stderr, "Unsupported bits per sample\n");
        exit(-1);
    } 

    // Handle extra samples information
    if (data.extra_samples > 0) {
        uint16 *sampleInfo = _TIFFmalloc(data.extra_samples * sizeof(uint16));
        TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &sampleInfo);
        snprintf(data.extra_sample_info, 1024, "%d", sampleInfo[0]); // Assuming one sample per pixel for simplicity
    } else {
        strcpy(data.extra_sample_info, "No extra samples");
    }

    TIFFClose(tif);
    return data;
}

void updateDatabase(PGconn *conn, int clinicID, const char *status, const char *ip) {
    PGresult *res = PQexec(conn, "UPDATE clinics SET status = $1, last_modified_ip = $2, last_modified_date = current_timestamp WHERE id = $3");
    if (PQresultStatus(res) != PGRES_COMMAND_OK) {
        fprintf(stderr, "%s", PQerrorMessage(conn));
        exit(-1);
    }

    PQclear(res);
}

void updateTiffAndDatabase(const char *filepath, int clinicID, const char *status, const char *ip) {
    ImageData data = parseTiff(filepath);

    // Establish connection to the database
    PGconn *conn = PQconnectdb("dbname=your_database user=username password=password");
