```c
#include <stdio.h>
#include <stdint.h>
#include <tiffio.h>

typedef struct {
    uint16_t bitsPerSample;  // Bits per sample, typically 1 to 8
    uint16_t samplesPerPixel;  // Number of channels in the image
    tsampleformat_t format;  // Sample format (INT, UINT, IEEEFP)
    uint16_t bytesPerSample;  // Derived from bitsPerSample and format
    char* colorProfile;  // Color profile, if available
} TiffImageInfo;

TiffImageInfo parseTIFF(const char *filePath) {
    TiffImageInfo imageInfo = {0};

    // Open the TIFF file
    TIFF *tif = TIFFOpen(filePath, "r");
    if (tif == NULL) {
        fprintf(stderr, "Failed to open TIFF file\n");
        return imageInfo;
    }

    // Read bits per sample and number of samples per pixel
    uint16_t config;
    if (TIFFGetField(tif, TIFFTAG_SAMPLEFORMAT, &config) != 1) {
        fprintf(stderr, "Failed to read SAMPLEFORMAT tag\n");
        return imageInfo;
    }

    // Extract and assign the bits per sample and samples per pixel
    imageInfo.bitsPerSample = config & 0xFF;
    imageInfo.samplesPerPixel = (config >> 8) & 0xFFFF;

    // Determine the format of each sample, based on bits per sample
    if (imageInfo.bitsPerSample <= 8) {
        imageInfo.format = SAMPLEFORMAT_UINT;
    } else if (imageInfo.bitsPerSample == 32 && imageInfo.samplesPerPixel == 1) {
        imageInfo.format = SAMPLEFORMAT_IEEEFP;
    } else {
        fprintf(stderr, "Unsupported bits per sample\n");
        return imageInfo;
    }

    // Compute bytes per sample from bits per sample
    switch (imageInfo.bitsPerSample) {
        case 1: case 2: case 4: case 8:
            imageInfo.bytesPerSample = 1;
            break;
        case 16:
            imageInfo.bytesPerSample = 2;
            break;
    }

    // TODO: Read and assign color profile, byte order, compression type
    // This is a complex task that requires specific library support or custom implementation

    TIFFClose(tif);  // Close the file

    return imageInfo;
}
```

