        // No arguments, read from stdin.
        pthread_t thread;
        char *arg = "-"; // Use a non-empty string as argument for count_lines().
        pthread_create(&thread, NULL, &count_lines, arg);
        pthread_join(thread, NULL);
    } else {
        // Process all provided files.
        pthread_t threads[argc - optind];

        for (int i = optind; i < argc; ++i) {
            pthread_create(&threads[i - optind], NULL, &count_lines, argv[i]);
        }

        for (int i = 0; i < argc - optind; ++i) {
