```C
#include <stdlib.h>
#include <string.h>
#include <netdb.h> 
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define HOSTNAME_BUFFER_SIZE 256
#define IP_ADDRESS_BUFFER_SIZE INET6_ADDRSTRLEN

char* resolveHostname(const char *hostname) {
    struct addrinfo hints, *res;
    int errcode;
    char addrstr[INET6_ADDRSTRLEN];
    void *ptr;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo(hostname, NULL, &hints, &res);

    if (errcode != 0) {
        perror("Failed to resolve hostname");
        return NULL;  // or handle error as you see fit
    }

    while (res) {
        inet_ntop(res->ai_family, res->ai_addr->sa_data, addrstr, sizeof(addrstr));

        switch (res->ai_family) {
            case AF_INET:
                ptr = &((struct sockaddr_in *)res->ai_addr)->sin_addr;
                break;
            case AF_INET6:
                ptr = &((struct sockaddr_in6 *)res->ai_addr)->sin6_addr;
                break;
        }

        inet_ntop(res->ai_family, ptr, addrstr, sizeof(addrstr));
        printf("IPv%d address: %s (%s)\n", res->ai_family == AF_INET6 ? 6 : 4, addrstr, res->ai_canonname);

        res = res->ai_next;
    }

    freeaddrinfo(res);

    char *ipAddress = malloc(IP_ADDRESS_BUFFER_SIZE);

    if (ipAddress == NULL) {
        perror("Failed to allocate memory");
        return NULL;  // or handle error as you see fit
    }

    strncpy(ipAddress, addrstr, IP_ADDRESS_BUFFER_SIZE - 1);
    ipAddress[IP_ADDRESS_BUFFER_SIZE - 1] = '\0';  // Ensure null termination.

    return ipAddress;
}
```
This function takes a hostname as input and returns the IP address in dynamically allocated memory. If there's an error during DNS resolution, it prints an error message to `stderr` and returns NULL.

Remember that you need to free the memory returned by this function when no longer needed using `free()`:
```C
char *ip = resolveHostname("example.com");
if (ip != NULL) {
    printf("%s\n", ip);
    free(ip);
}
```
The function also has a buffer overflow protection if the address is longer than `INET6_ADDRSTRLEN` bytes, by setting the last byte to null character.
