import java.security.MessageDigest;
import java.util.concurrent.ConcurrentHashMap;
import org.apache.commons.codec.digest.DigestUtils;

public class MD5Computer {
    private ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();

    public synchronized ConcurrentHashMap<String, String> computeMD5Hashes(String... strings) {
        ConcurrentHashMap<String, String> results = new ConcurrentHashMap<>();

        for (String s : strings) {
            String hash = cache.get(s);

            if (hash != null) {  // If already computed and cached, use the cached value
                results.put(s, hash);
            } else {
                try {
                    MessageDigest md = MessageDigest.getInstance("MD5");
                    byte[] digest = md.digest(s.getBytes());
                    hash = DigestUtils.md5Hex(digest);  // Apache Commons library function to convert bytes to hex string

                    results.put(s, hash);
                    cache.put(s, hash);  // Cache the result for future use
                } catch (Exception e) {
                    System.err.println("Error: " + e.getMessage());
                }
            }
        }

        return results;
    }
}
