        self.Max = max_val
        self.Closed = closed

    def __repr__(self):
        if self.Closed:
            return f"[{self.Min}, {self.Max}]"
        else:
            return f"({self.Min}, {self.Max})"

class AdvancedRandomFileHasher:
    def __init__(self, seed=None):
        self._seed = seed if seed is not None else random.randint(0, 2**31 - 1)
        self._cache = {}
        logging.basicConfig(filename='logfile.log', level=logging.INFO)

    def _get_random_value(self):
        rng = range if len(self._cache) == 0 else self._cache[max(self._cache)][1]
        return random.randint(rng.Min, rng.Max)

    def generate_hash(self, filepath):
        hasher = hashlib.md5()
        with open(filepath, 'rb') as afile:
            buf = afile.read(65536)
            while len(buf) > 0:
                hasher.update(buf)
                buf = afile.read(65536)
        return hasher.hexdigest()

    def generate_random_values(self, rng, count):
        random_values = []
        for _ in range(count):
            random_value = self._get_random_value()
            while not (rng.Min <= random_value <= rng.Max):
                random_value = self._get_random_value()
            random_values.append(random_value)
        return random_values

    def __str__(self):
        return f"Current state: Range={repr(list(self._cache.values())[-1])}, Seed={self._seed}"
