// Forward declaration of the collection to break circular dependency
typedef struct Collection Collection;

typedef struct Node {
    NICP* nicp;
    struct Node* next;
    pthread_mutex_t lock; // Ensure thread safety
} Node;

struct Collection {
    Node* head; 
    pthread_rwlock_t rwlock; // For concurrent read and write operations
};

Collection* create_collection() {
    Collection* collection = malloc(sizeof(Collection));
    if (collection == NULL) return NULL;

    collection->head = NULL;
    pthread_rwlock_init(&collection->rwlock, NULL);

    return collection; 
}

void add_nicp(Collection* collection, NICP* nicp) {
    // Create new node and assign data
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return;

    node->nicp = nicp; 
    pthread_mutex_init(&node->lock, NULL);

    // Lock for write operation and add new node to the head
    pthread_rwlock_wrlock(&collection->rwlock);
    node->next = collection->head;
    collection->head = node; 
    pthread_rwlock_unlock(&collection->rwlock);
}

NICP* get_nicp(Collection* collection, const char* ip) {
    // Lock for read operation and retrieve NICP data
    pthread_rwlock_rdlock(&collection->rwlock); 
    Node* cur = collection->head;

    while (cur != NULL) {
        if (!strcmp(cur->nicp->ip, ip)) {
            pthread_mutex_lock(&cur->lock); // Lock for thread safety during reading 
            NICP* nicp = cur->nicp; 
            pthread_mutex_unlock(&cur->lock);

            return nicp;
        }

        cur = cur->next;
    }

    pthread_rwlock_unlock(&collection->rwlock);
    return NULL; // NICP not found 
}

void update_nicp(Collection* collection, const char* ip, NICP* newNicp) {
    // Lock for write operation and retrieve node
    pthread_rwlock_wrlock(&collection->rwlock); 
    Node* cur = collection->head;

    while (cur != NULL) {
        if (!strcmp(cur->nicp->ip, ip)) {
            // Lock for thread safety during writing and update NICP data 
            pthread_mutex_lock(&cur->lock); 
            free(cur->nicp);
            cur->nicp = newNicp; 
            pthread_mutex_unlock(&cur->lock);

            break;
        }

        cur = cur->next;
    }

    pthread_rwlock_unlock(&collection->rwlock);
}
```

