['Below is the C code for the problem described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct AccessLog {
    int requestSize;
    char* timestamp;
} AccessLog;

AccessLog *parseLogLine(char *line) {
    // Assuming log line is in format "size:timestamp"
    AccessLog *log = (AccessLog *)malloc(sizeof(AccessLog));

    if(log == NULL) {
        printf("Memory allocation failure.\n");
        exit(1);
    }

    char *token;
    token = strtok(line, ":");
    log->requestSize = atoi(token);

    token = strtok(NULL, ":");
    log->timestamp = (char *)malloc((strlen(token) + 1) * sizeof(char));

    if(log->timestamp == NULL) {
        printf("Memory allocation failure.\n");
        exit(1);
    }

    strcpy(log->timestamp, token);

    return log;
}

void processLogFile(char *fileName, int bandwidthLimit, double rateLimit) {
    FILE *file = fopen(fileName, "r");
    char line[256];
    int totalBandwidth = 0;

    if (file == NULL){
        printf("Could not open file.\n");
        return;
    }

    while (fgets(line, sizeof(line), file)) {
        AccessLog *log = parseLogLine(line);

        // Check if request size is within bandwidth limit and rate limit
        if(log->requestSize <= bandwidthLimit) {
            totalBandwidth += log->requestSize;
            printf("Processing: Request Size - %d, Timestamp - %s\n", log->requestSize, log->timestamp);

            // Sleep to maintain rate limit
            sleep(1/rateLimit);
        } else {
            printf("Request size exceeded bandwidth limit. Ignoring...\n");
        }

        free(log->timestamp);
        free(log);
    }

    fclose(file);

    if (totalBandwidth == 0)
        printf("No valid requests found in log file.\n");
    else
        printf("Total bandwidth usage: %d\n", totalBandwidth);
}
```
The code provided above includes a function `parseLogLine` to process each line from the log file. It allocates memory for the `AccessLog` struct and parses the size of the request and timestamp from the line. If memory allocation fails, it prints an error message and terminates the program with an exit status of 1.

The function `processLogFile` reads each line from a log file, parses it into an `AccessLog` struct, checks if the request size exceeds the bandwidth limit and if so processes it by adding its size to the total bandwidth usage. If not, it ignores the request and moves on to the next one. It also implements rate limiting by sleeping for 1/rateLimit seconds after processing each valid request. At the end of the function, it prints out the total bandwidth usage or an error message if no valid requests were processed.
