char* processFilePath(const char *filePath, unsigned long maxSize, bool strictMode, unsigned long *resultSize, unsigned int *fileSize) {
    if (filePath == NULL || fileSize == NULL || (*resultSize > maxSize && !strictMode))  return NULL; // Handle null pointers and large input

    size_t len = strlen(filePath);
    char *baseName = malloc((len + 3) * sizeof(*baseName));  // Allocate memory for base name, including potential appends
    if (baseName == NULL || resultSize == NULL) return NULL; // Handle allocation failure and null pointers

    strcpy(baseName, filePath); // Copy the file path to baseName
    char *lastSlash = strrchr(baseName, '/'); // Find the last slash in the string
    if (lastSlash != NULL) {
        strcpy(baseName, lastSlash + 1);  // If a slash was found, copy from it to the end
    }

    size_t baseLen = strlen(baseName);
    *resultSize = baseLen;

    if (*fileSize <= maxSize) {
        baseName[baseLen] = '_'; // Append underscore
