['Here is a C code snippet fulfilling your requirements. This solution uses dynamic memory allocation where necessary, to ensure efficient use of system resources. However, it's crucial to remember that memory allocated should always be freed when it's no longer needed, which this function does not do in its current state.

```c
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#ifdef _WIN32
    #define PATH_SEP "\\"
#else
    #define PATH_SEP "/"
#endif

char* processFilePath(const char *filePath, unsigned long maxSize, bool strictMode, 
                      unsigned long *resultSize, unsigned int *fileSize, char *buffer, size_t bufferSize) {

    if (filePath == NULL || resultSize == NULL || fileSize == NULL || (*resultSize > maxSize)) return NULL;

    bool pathIsAbsolute = false;
#ifdef _WIN32
    pathIsAbsolute = strchr(filePath, ':') != NULL;
#else
    pathIsAbsolute = filePath[0] == '/';
#endif

    char *lastSlashPos = pathIsAbsolute ? (char*)strchr(filePath + 2, PATH_SEP) : strrchr(filePath, PATH_SEP);
    const char* baseName;
    size_t baseNameLen;
    if (lastSlashPos != NULL) {  // file path contains a directory
        baseName = lastSlashPos + 1;
        baseNameLen = strlen(baseName);
    } else {  // file path is in the current directory
        baseName = filePath;
        baseNameLen = strlen(baseName);
    }

    if (buffer == NULL || bufferSize < (baseNameLen + (strictMode && *fileSize > maxSize ? 3 : 2))){
        bufferSize = baseNameLen + (strictMode && *fileSize > maxSize ? 3 : 2); // add 2 for '_' or '__', 1 for '\0'
        buffer = realloc(buffer, bufferSize);
    }

    if (*fileSize <= maxSize){
       strncpy(buffer, baseName, baseNameLen);
       buffer[baseNameLen] = '_';
       buffer[baseNameLen + 1] = '\0';
    } else {  // File size exceeded and strictMode is enabled
        if (strictMode && *fileSize > maxSize) return NULL;

        strncpy(buffer, baseName, baseNameLen);
        buffer[baseNameLen] = '_';
        buffer[baseNameLen + 1] = '_';
        buffer[baseNameLen + 2] = '\0';
    }

    *resultSize = strlen(buffer) + 1; // +1 for null terminator
    return buffer;
}
```
This function first checks if the filePath, resultSize and fileSize pointers are not NULL and that resultSize does not exceed maxSize. Then it determines whether the file path is absolute or relative based on the platform (Windows vs Unix-like). It then locates the last forward or backslash in the file path to determine where the base name begins, allocating memory for a new buffer if needed. Finally, it copies the base name into the buffer and appends an underscore character depending on whether strictMode is enabled and the file size exceeds maxSize. The length of the resulting string (including null terminator) is stored in resultSize.
']

