void processLogFile(const std::string& inputFileName, const std::string& outputFileName, 
    const std::string& criteria, const std::string& insertionString, 
    char delimiter, bool prioritizeMemory) {

    std::ifstream infile(inputFileName);
    std::vector<std::string> lines;
    std::string line;
    while (std::getline(infile, line)) {
        if (line.find(criteria) != std::string::npos) {
            lines.push_back(line);
        }
    }

    infile.close();

    if (prioritizeMemory) {
        std::sort(lines.begin(), lines.end());
    } else {
        std::stable_sort(lines.begin(), lines.end());
    }

    std::fstream outfile;
    bool foundInsertionPoint = false;
    outfile.open(outputFileName, std::ios::in | std::ios::out);
    if (outfile) {
        while (std::getline(outfile, line)) {
            if (line.find(criteria) != std::string::npos) {
                foundInsertionPoint = true;
                break;
            }
        }

        outfile.seekp(0, std::ios_base::end);

        for (const auto& newLine : lines) {
            if (!foundInsertionPoint) {
                outfile << insertionString + delimiter;
            } else {
                foundInsertionPoint = false;
            }
            outfile << newLine + delimiter;
        }
    } else {
        // Handle file open failure here, e.g., throw an exception or print an error message.
    }

    outfile.close();
}
```
