```c
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>

// NICP structure
typedef struct {
    char ip_address[16];
    int port;
    int status;  // Status: up (1), down (-1)
    time_t last_seen;
} NICP;

#define MAX_CONNECTIONS 10000
NICP connections[MAX_CONNECTIONS];
int connCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Add a new connection to the list
void addConnection(char* ip, int port, int status) {
    pthread_mutex_lock(&lock);

    if (connCount >= MAX_CONNECTIONS) {
        printf("Error: Max connections reached!\n");
        return;
    }

    // Check for duplicates
    for(int i = 0; i < connCount; ++i) 
        if(strcmp(connections[i].ip_address, ip) == 0 && connections[i].port == port) {
            printf("Error: Duplicate connection entry!\n");
            pthread_mutex_unlock(&lock);
            return;
        }

    NICP newConn = { .status = status, .last_seen = time(NULL), .port = port };
    strcpy(newConn.ip_address, ip);

    connections[connCount++] = newConn;

    pthread_mutex_unlock(&lock); 
}

// Update an existing connection in the list
void updateConnectionStatus(char* ip, int port, int status) {
    pthread_mutex_lock(&lock);

    for(int i = 0; i < connCount; ++i) 
        if(strcmp(connections[i].ip_address, ip) == 0 && connections[i].port == port) {
            connections[i].status = status;
            connections[i].last_seen = time(NULL);

            pthread_mutex_unlock(&lock); 
            return;
        }

    printf("Error: Connection not found!\n");

    pthread_mutex_unlock(&lock);    
}

// Retrieve a connection by IP address
NICP* getConnectionByIp(char *ip) {
    for(int i = 0; i < connCount; ++i) 
        if(strcmp(connections[i].ip_address, ip) == 0)
            return &connections[i];

    printf("Error: Connection not found!\n");
    return NULL;
}

// Retrieve a connection by port number
NICP* getConnectionByPort(int port) {
    for(int i = 0; i < connCount; ++i) 
        if(connections[i].port == port)
            return &connections[i];

    printf("Error: Connection not found!\n");
    return NULL;
}

// Print connection stats
void printConnectionStats() {
    int upCount = 0, downCount = 0;
    for(int i = 0; i < connCount; ++i) 
        if(connections[i].status == 1)
            upCount++;
        else if(connections[i].status == -1)
            downCount++;

    printf("Active connections: %d\n", upCount);
}
```
