void replaceOrInsert(std::vector<std::string>& vec, const std::string& target, const std::string& replacement) {
    auto it = std::find(vec.begin(), vec.end(), target);

    if (it != vec.end()) {
        *it = replacement;
    } else {
        vec.insert(vec.begin(), target);
    }
}
