aes256cbc_t* setup_aes256cbc(unsigned char *password, size_t password_len, unsigned char *salt, size_t salt_len, int iterations) {
    aes256cbc_t *result = malloc(sizeof(aes256cbc_t));
    if (result == NULL) {
        log_error("setup_aes256cbc: malloc failed");
        return NULL;
    }

    result->ctx = EVP_CIPHER_CTX_new();
    if(result->ctx == NULL || !EVP_CipherInit_ex(result->ctx, EVP_aes_256_cbc(), NULL, NULL, NULL, 1)) {
        log_error("setup_aes256cbc: CipherInit failed");
        goto error;
    }

    unsigned char key[32]; // 256-bit AES key size
    if(!PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len, iterations, EVP_sha256(), sizeof(key), key)) {
        log_error("setup_aes256cbc: Key derivation failed");
        goto error;
    }

    unsigned char iv[16]; // AES-CBC block size
    if(!RAND_bytes(iv, sizeof(iv))) {
        log_error("setup_aes256cbc: IV generation failed");
        goto error;
    }

    if(!EVP_EncryptInit_ex(result->ctx, NULL, NULL, key, iv)) {
        log_error("setup_aes256cbc: Encryption initialization failed");
        goto error;
    }

    return result;

error:
    cleanup_aes256cbc(result);
    return NULL;
}

void cleanup_aes256cbc(aes256cbc_t *ctx) {
  if (ctx != NULL) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
  }
}
