    pthread_mutex_t lock;
    TCP_CONNECTION_RECORDS *connections;
    size_t maxConnections, currentConnections;
};

typedef void (*loggingCallback)(char*);
extern loggingCallback logFunc;
extern int shouldLog;

void logger(char *msg) {
    if (shouldLog) {
        logFunc(msg);
    }
}

struct ConnectionManager *createConnectionManager(size_t maxConnections, loggingCallback cb) {
    struct ConnectionManager* cm = malloc(sizeof(struct ConnectionManager));
    if (!cm) return NULL;

    pthread_mutex_init(&(cm->lock), NULL);

    cm->connections = calloc(maxConnections, sizeof(TCP_CONNECTION_RECORDS));
    if(!(cm->connections)) {
        free(cm);
        return NULL;
    }
    cm->maxConnections = maxConnections;
    cm->currentConnections = 0;

    logFunc = cb;

    logger("Connection manager created.");
    return cm;
}

void destroyConnectionManager(struct ConnectionManager *cm) {
    if (!cm) return;
    pthread_mutex_destroy(&(cm->lock));
    free(cm->connections);
    free(cm);

    logger("Connection manager destroyed.");
}
