from typing import List

logger = logging.getLogger(__name__)

class FileHasher:
    def __init__(self, chunk_size=4096):
        self.chunk_size = chunk_size

    def _update_hash(self, filepath: Path):
        hasher = hashlib.md5()
        with open(filepath, 'rb') as f:
            for byte_block in iter(lambda: f.read(self.chunk_size), b''): 
                hasher.update(byte_block)
        return hasher.digest()

    def _check_disk_space(self, paths: List[Path]):
        for path in paths:
            stat = os.statvfs(path)
            available_bytes = stat.f_bavail * stat.f_frsize  # Available blocks * block size
            if available_bytes < min([p.lstat().st_size for p in paths]):
                raise Exception('Insufficient disk space')

    def _resume(self, state: dict):
        self._state = state

    def hash_files(self, filepaths: List[Path], resume=False):

        if not isinstance(filepaths, list) or not all([isinstance(p, Path) for p in filepaths]): 
            raise ValueError('Input must be a list of pathlib.Path objects')

        self._check_disk_space(filepaths)

        if resume: 
            if not isinstance(resume, dict) or 'state' not in resume: 
                raise ValueError('Invalid state for resuming hashing process')
            self._resume(resume['state'])

        total_files = len(filepaths)

        with ThreadPoolExecutor() as executor:
            futures = {executor.submit(self._update_hash, filepath): idx for idx, filepath in enumerate(filepaths)}

            for future in as_completed(futures):
                file_idx = futures[future]

                try:
