```python
import os
import hashlib
from enum import Enum
from threading import Lock
from socket import gethostbyname
import psutil
import logging

class Mode(Enum):
    APPEND = 1
    TRUNCATE = 2

def process_and_hash_files(file_paths, buffer_size, mode, hostname, network_details):
    lock = Lock()

    def check_disk_space():
        disk_usage = psutil.disk_usage("/")
        return disk_usage.free / (2**30) > 1  # free space in GB

    def get_filepath(f, mode):
        if mode == Mode.APPEND:
            if not f.endswith('.suffix'):
                f += '.suffix'
        elif mode == Mode.TRUNCATE:
            if f.endswith('.suffix'):
                f = f[:-len('.suffix')] + '.new_suffix'
        return f

    def hash_file(f, buffer_size):
        h = hashlib.md5()
        with open(f, 'rb') as file:
            while True:
                chunk = file.read(buffer_size)
                if not chunk:
                    break
                h.update(chunk)
        return h.hexdigest()

    def process_file(i, f):
        try:
            with lock:
                logging.info('Processing file %s', f)
                ip = gethostbyname(hostname)
                network_details[0] = int(ip.replace('.', ''))  # Convert to integer for example purposes

                if check_disk_space():
                    hashed = hash_file(f, buffer_size)
                    logging.info('Hashed file %s: %s', f, hashed)
                else:
                    raise Exception("Insufficient disk space")
        except Exception as e:
            logging.error('Error processing file %s: %s', f, str(e))

    for i, f in enumerate(file_paths):
        process_file(i, get_filepath(f, mode))  # Process each file in sequence to keep state
```
