    Transaction *transactions = malloc(sizeof(Transaction) * n);
    int count = 0;
    while (!feof(input) && count < n) {
        if (fread(&transactions[count], sizeof(Transaction), 1, input) != 1) {
            printf("Failed to read transaction from file.\n");
            break;
        }
        ++count;
    }

    fclose(input);

    FILE *output = fopen(outputFile, "wb");
    if (output == NULL) {
        printf("Failed to open the output file.\n");
        free(transactions);
        return;
    }

    for (int i = 0; i < count; ++i) {
        // Apply filtering and aggregation rules
        // Example: only include transactions above threshold
        if (strcmp(rules, "threshold") == 0 && transactions[i].amount > threshold) {
            fwrite(&transactions[i], sizeof(Transaction), 1, output);
        }
