typedef struct {
    CURL *curl;
    cJSON *json_payload;
} Connection;

Connection* create_connection(const char *url) {
    Connection *conn = malloc(sizeof(Connection));
    conn->curl = curl_easy_init();
    if (conn->curl) {
        curl_easy_setopt(conn->curl, CURLOPT_URL, url);
        // Set up other options like timeout, headers etc.

        // Initialize JSON payload structure
        conn->json_payload = cJSON_CreateObject();
    }
    return conn;
}

void process_request(Connection *conn, const char* request) {
    CURLcode res;

    curl_easy_setopt(conn->curl, CURLOPT_POSTFIELDS, request);

    // Prepare JSON payload with metrics data
    cJSON_AddStringToObject(conn->json_payload, "sessionID", "uniqueSessionID");
    cJSON_AddNumberToObject(conn->json_payload, "latency", 0.1);

    char *response = curl_easy_perform(conn->curl);
    if(res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    } else {
        // Add response data to JSON payload
        cJSON_AddStringToObject(conn->json_payload, "response", response);
    }
}

void destroy_connection(Connection *conn) {
    curl_easy_cleanup(conn->curl);
    free(conn);
}
