void init_tunnel(gtpv2c_tunnel_t* tunnel, char *IMSI, char *APN, unsigned int TEID, char *encryption_key) {
    validate(IMSI);
    validate(APN);

    pthread_mutex_init(&tunnel->lock, NULL);
    pthread_mutex_lock(&tunnel->lock);
    tunnel->info.IMSI = strdup(IMSI);
    tunnel->info.APN = strdup(APN);
    tunnel->info.TEID = TEID;

    validate(encryption_key);
    memcpy(tunnel->ctx.encryption_key, encryption_key, 32);
    pthread_mutex_unlock(&tunnel->lock);
}

void configure_tunnels(int N) {
    // dynamic memory allocation for tunnels
    tunnels = (gtpv2c_tunnel_t*)malloc(sizeof(gtpv2c_tunnel_t) * N);

    // for each tunnel, initialize and configure it with valid data
    for (int i = 0; i < N; i++) {
        init_tunnel(&tunnels[i], "validIMSI", "validAPN", i, "encryptionkey32byteslong");
    }

    numTun = N;
}

void reconfig_tunnel(unsigned int TEID, char *newKey) {
    pthread_mutex_lock(&tunnel_lock);
    validate(newKey);
    for (int i = 0; i < numTun; i++) {
        if (tunnels[i].info.TEID == TEID) {
            pthread_mutex_lock(&tunnels[i].lock);
            memcpy(tunnels[i].ctx.encryption_key, newKey, 32);
            pthread_mutex_unlock(&tunnels[i].lock);
        }
    }
    pthread_mutex_unlock(&tunnel_lock);
}
