#define HASH_SIZE 10007 // Choose a prime number for hash table size.

// Node structure for linked list
typedef struct node{
    int val;
    int count;
    struct node *next;
}Node;

// Hash Table Implementation
Node* hashtable[HASH_SIZE];

unsigned long hash(int value){ // Simple hash function
    return abs(value) % HASH_SIZE;
}

void addToHashTable(int val, Node** head){
    unsigned long index = hash(val);
    while(*head != NULL){
        if((*head)->val == val){
            (*head)->count++;
            return;
        }
        head = &((*head)->next);
    }
    *head = (Node*)malloc(sizeof(Node));
    (*head)->val = val;
    (*head)->count = 1;
    (*head)->next = NULL;
}

// Get input from stdin and process it.
int main(){
    int num, max_num;
    Node *node;

    while(scanf("%d", &num) != EOF){
        if(!isdigit(num)){
            printf("Invalid input!\n");
            continue;
        }

        addToHashTable(num, &hashtable[hash(num)]); // Add to hashtable.

        max_num = (max_num < num)? num: max_num; // Update max number.
    }

    printf("Max integer: %d\n", max_num); // Print the largest integer.

    // Print count of each unique integer present in hash table.
    for(int i = 0; i < HASH_SIZE; ++i){
        node = hashtable[i];
        while(node != NULL){
            printf("Count of %d: %d\n", node->val, node->count);
            node = node->next;
        }
    }

    // Free allocated memory.
    for(int i = 0; i < HASH_SIZE; ++i){
        while(hashtable[i] != NULL){
            Node *tmp = hashtable[i]->next;
            free(hashtable[i]);
            hashtable[i] = tmp;
        }
    }

    return 0;
}
```
