int handle_and_update_resource(char *resourceId, int bufferSize, Mode mode, char *hostname, 
                               char *dependency, u_char *state, FILE *fd, double timeout, 
                               int retryCounter) {
    pthread_mutex_lock(&mutex);
    sem_wait(&semaphore);

    if (strlen(resourceId) > bufferSize || strstr(resourceId, dependency) != NULL) {
        fprintf(fd, "Error: Invalid resource identifier or dependency!\n");
        pthread_mutex_unlock(&mutex);
        sem_post(&semaphore);
        return -1;
