void process_and_cache_network_request(char* requestID, int maxCacheSize, Priority priorityLevel, 
                                       char* sourceIP, char* resourceID, u_char **responseData, FILE* fd) {
    if (strlen(requestID) > maxCacheSize || priorityLevel < MEDIUM) {
        log_error(fd, "Request identifier and/or cache size constraints not met.");
        return;
    }

    pthread_mutex_lock(&cacheMutex);
    u_char* cachedData = get_cached_data(requestID);
    if (priorityLevel == LOW && cachedData != NULL) {
        *responseData = cachedData;
        log_error(fd, "Retrieved data from cache.");
    } else {
        for (int i = 0; i < 5; ++i) {  // retry up to 5 times.
            if (perform_HTTP_get(sourceIP, resourceID, responseData) == 0) {
                add_to_cache(requestID, *responseData);
                log_error(fd, "Successfully performed HTTP GET and cached data.");
                break;
            } else {
                log_error(fd, "HTTP request failed. Retrying...");
            }
        }
    }
    pthread_mutex_unlock(&cacheMutex);
}
