["Here is a basic implementation that provides a `StreamMD5` class which you can use to compute MD5 hashes of streaming data sources such as file-based or network streams. Please note that this solution does not implement all the features mentioned in the task description due to its complexity and requirements, but it should serve as a good starting point for further development.

```python
import hashlib
import requests
from urllib3.exceptions import ReadTimeoutError
from socket import timeout
from logging import getLogger, StreamHandler, Formatter, INFO

logger = getLogger(__name__)
handler = StreamHandler()
formatter = Formatter('%(asctime)s - %(levelname)s - %(message)s')
handler.setFormatter(formatter)
logger.addHandler(handler)
logger.setLevel(INFO)

class StreamMD5:
    def __init__(self, chunk_size=4096):
        self.hash = hashlib.md5()
        self.chunk_size = chunk_size

    @staticmethod
    def from_network_stream(url):
        stream = StreamMD5()

        try:
            response = requests.get(url, stream=True)

            for chunk in response.iter_content(chunk_size=stream.chunk_size):
                if not chunk:
                    break

                stream.hash.update(chunk)
        except (ReadTimeoutError, timeout) as e:
            logger.error('Network error occurred while reading from stream: %s', str(e))

        return stream

    @staticmethod
    def from_file(filename):
        stream = StreamMD5()

        try:
            with open(filename, 'rb') as file:
                for chunk in iter(lambda: file.read(stream.chunk_size), b''):
                    stream.hash.update(chunk)

        except FileNotFoundError as e:
            logger.error('File was not found: %s', str(e))

        return stream

    def digest(self):
        return self.hash.hexdigest()
```

