import java.security.*;
import java.util.*;
public class MD5Hash {
   private static Map<String, String> hashes = new HashMap<>(); // Thread-safe map for storing computed hashes
    public synchronized static void computeMD5(String input) throws NoSuchAlgorithmException{
        MessageDigest md = MessageDigest.getInstance("MD5"); // Create MD5 instance
        byte[] messageDigest = md.digest(input.getBytes()); 
        BigInteger no = new BigInteger(1, messageDigest); 
        String hashtext = no.toString(16); 
        while (hashtext.length() < 32) { 
            hashtext = "0" + hashtext; 
        } 
        hashes.put(input, hashtext); // Store the hash in the map
    }
}
