['Here is a basic solution in C# using System.Xml namespace for xml parsing, System.Security.Cryptography for MD5 hash calculation, and StreamReader for reading large files in chunks of 64 KB:

```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Xml;

public class Program
{
    static void Main()
    {
        try
        {
            XmlDocument doc = new XmlDocument();
            doc.Load("config.xml");

            int tileSize = int.Parse(doc.SelectSingleNode("/Configuration/TileSize").InnerText);
            int width = int.Parse(doc.SelectSingleNode("/Configuration/WorldWidth").InnerText);
            int height = int.Parse(doc.SelectSingleNode("/Configuration/WorldHeight").InnerText);
            int speedOfCamera = int.Parse(doc.SelectSingleNode("/Configuration/SpeedOfCamera").InnerText);

            string filePath = doc.SelectSingleNode("/Configuration/FilePath").InnerText;

            MD5 md5Hash = MD5.Create();

            using (var stream = new BufferedStream(new FileStream(filePath, FileMode.Open), 64 * 1024)) //Buffering in 64 KB chunks
            {
                byte[] buffer = new byte[64 * 1024]; // 64 KB buffer
                int read;

                while ((read = stream.Read(buffer, 0, buffer.Length)) > 0)
                {
                    md5Hash.TransformBlock(buffer, 0, read, buffer, 0);
                }

                md5Hash.TransformFinalBlock(new byte[0], 0, 0);
            }

            Console.WriteLine("MD5 Hash: " + BitConverter.ToString(md5Hash.Hash).Replace("-", "").ToLower());
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error occurred while processing file: " + ex);
        }
    }
}
```

