['Here is a Java solution implementing your requirements using Random objects to generate random numbers with caching mechanism. Log4j library is used for logging. 
```java
import java.security.MessageDigest;
import java.util.*;
import org.apache.log4j.Logger;

public class AdvancedRandomValueGenerator {
    private static final Logger logger = Logger.getLogger(AdvancedRandomValueGenerator.class);
    private Random random;
    private int seed;
    private Map<Integer, Integer> cache = new HashMap<>();

    public void setSeed(int seed) {
        this.seed = seed;
        random = new Random(this.seed);
    }

    public class Range {
        int min;
        int max;
        boolean closed;

        public Range(int value1, int value2, boolean closed) {
            if (value1 < value2) {
                this.min = value1;
                this.max = value2;
            } else {
                this.min = value2;
                this.max = value1;
            }
            this.closed = closed;
        }
    }

    public int generateValue(Range range) {
        if (range == null || range.min > range.max) {
            logger.error("Invalid Range");
            return -1; // error handling as per requirement
        }

        Integer cached = cache.get(range);
        if (cached != null) {
            return cached;
        } else {
            int generatedValue = range.closed ? random.nextInt((range.max-range.min) + 1) + range.min : random.nextInt((range.max-range.min)) + range.min;
            cache.put(generatedValue, generatedValue);
            logger.info("Generated value: " + generatedValue);

            return generatedValue;
