    private Random random;
    private HashMap<String, Integer> cache;

    public AdvancedRandomValueGenerator(int min, int max, boolean closed) {
        this.min = min;
        this.max = max;
        this.closed = closed;
        this.seed = new Date().getTime();
        this.random = new Random(this.seed);
        this.cache = new HashMap<>();
    }

    public int getNext() {
        String key = min + ":" + max + ":" + closed;
        if (!cache.containsKey(key)) {
            cache.put(key, generate());
        }
        return cache.get(key);
    }

    public int[] getArray(int length) {
        int[] array = new int[length];
        for (int i = 0; i < length; i++) {
            array[i] = getNext();
        }
        return array;
    }

    private int generate() {
        if (!closed && max - min <= 1) {
            throw new IllegalArgumentException("Invalid range for open interval");
        } else if (max < min) {
            throw new IllegalArgumentException("Minimum is greater than maximum");
        }
        return random.nextInt(max + 1 - min) + min;
    }

    @Override
    public String toString() {
        return "AdvancedRandomValueGenerator [min=" + min + ", max=" + max 
            + ", closed=" + closed + ", seed=" + seed 
            + ", cache size=" + cache.size() + "]";
    }
}

class PokemonTypeWeaknessChecker {
    private static final Log LOG = LogFactory.getLog(PokemonTypeWeaknessChecker.class);

    public String checkWeaknesses(String pokemonFile) throws NoSuchAlgorithmException, Exception {
        MessageDigest md5Digest = MessageDigest.getInstance("MD5");
        byte[] buffer = new byte[8192];
        try (InputStream in = new FileInputStream(pokemonFile)) {
            for (int read = 0; read != -1; read = in.read(buffer)) {
                md5Digest.update(buffer, 0, read);
            }
        } catch (IOException e) {
            LOG.error("Error reading file", e);
            throw new Exception("Failed to read file", e);
        }
        return bytesToHex(md5Digest.digest());
    }

    private String bytesToHex(byte[] hashInBytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : hashInBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
