    private Random random;
    private int seed;
    private Range range;
    private Map<Range, List<Number>> cache = new HashMap<>();

    public AdvancedRandomValueGenerator(int seed) {
        this.seed = seed;
        this.random = new Random(this.seed);
    }

    public void setRange(Range range) {
        this.range = range;
    }

    private Number generateRandom() {
        if (this.cache.containsKey(this.range)) {
            List<Number> cachedValues = this.cache.get(this.range);
            return cachedValues.isEmpty() ? null : cachedValues.remove(0);
        }

        Number randomValue;
        if (this.range.closed) {
            int minInt = this.range.min.intValue();
            int maxInt = this.range.max.intValue();

            if (this.range.min instanceof Integer && this.range.max instanceof Integer) {
                randomValue = random.nextInt((maxInt - minInt) + 1) + minInt;
            } else {
                double minDouble = this.range.min.doubleValue();
                double maxDouble = this.range.max.doubleValue();
                randomValue = minDouble + (maxDouble - minDouble) * random.nextDouble();
            }
        } else {
            if (this.range.min instanceof Integer && this.range.max instanceof Integer) {
                int minInt = Math.toIntExact(Math.round(this.range.min.doubleValue()));
                int maxInt = Math.toIntExact(Math.round(this.range.max.doubleValue()));

                randomValue = this.random.nextInt(maxInt - minInt) + minInt + 1;
            } else {
                double minDouble = this.range.min.doubleValue();
                double maxDouble = this.range.max.doubleValue();
                randomValue = (this.random.nextDouble() * (maxDouble - minDouble)) + minDouble;
            }
        }

        return randomValue;
    }

    public Number generateRandomOnce() {
        if (this.range == null) {
            throw new IllegalStateException("Range not set");
        }

        return this.generateRandom();
    }

    public List<Number> generateRandom(int count) {
        if (this.range == null) {
            throw new IllegalStateException("Range not set");
        }

        List<Number> randomValues = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            Number randomValue = this.generateRandom();
            if (randomValue == null) {
                throw new IllegalStateException("No more values in cache");
            }

            randomValues.add(randomValue);
        }

        return randomValues;
    }

    @Override
    public String toString() {
        return "AdvancedRandomValueGenerator{" +
                "seed=" + seed +
                ", range=" + range +
                ", cacheSize=" + cache.size() +
                '}';
    }

    private class Range {
        Number min;
        Number max;
        boolean closed;

        public Range(Number min, Number max, boolean closed) {
            this.min = min;
            this.max = max;
            this.closed = closed;
        }
    }
}
