```java
import java.util.*;
import java.io.*;
import java.nio.file.*;
import java.security.*;
import org.apache.commons.math3.distribution.*;

public class AdvancedRandomValueGenerator {
    private static final SecureRandom random = new SecureRandom();
    private static final Map<Range, List<Integer>> cache = new HashMap<>();
    private static final Path logFilePath = Paths.get("random-value-generator.log");

    public void generateAndCache(Range range) {
        if (!cache.containsKey(range)) {
            synchronized (this) {
                if (!cache.containsKey(range)) {
                    List<Integer> values = new ArrayList<>();

                    for (int i = 0; i < Math.abs(range.getMax() - range.getMin()) + 1; ++i) {
                        int randomValue = generateRandomWithinRange(range);

                        while (values.contains(randomValue)) {
                            randomValue = generateRandomWithinRange(range);
                        }

                        values.add(randomValue);
                    }

                    cache.put(range, values);
                }
            }
        }
    }

    public int getCachedRandom(Range range) {
        if (!cache.containsKey(range)) generateAndCache(range);

        List<Integer> cachedValues = cache.get(range);
        Collections.shuffle(cachedValues, random);

        return cachedValues.remove(0);
    }

    public int[] getRandomArray(Range range, int length) {
        if (!cache.containsKey(range)) generateAndCache(range);

        List<Integer> values = new ArrayList<>();

        for (int i = 0; i < length; ++i) {
            values.add(getCachedRandom(range));
        }

        return values.stream().mapToInt(i -> i).toArray();
    }

    public int getRandomWithDistribution(Range range, Distribution distribution) {
        if (!cache.containsKey(range)) generateAndCache(range);

        List<Integer> cachedValues = cache.get(range);
        Collections.shuffle(cachedValues, random);

        double[] quantiles = new double[cumulativeProbabilities.length];
        distribution.reverseCumulativeProbability(0.5, quantiles);

        int index = 0;
        for (int i = 0; i < cachedValues.size(); ++i) {
            if (cachedValues.get(i) <= quantiles[index]) {
                return cachedValues.remove(i);
            }

            index = Math.min(index + 1, quantiles.length - 1);
        }

        throw new IllegalStateException("No random value available");
    }

    public void logOperation(String message) {
        try (BufferedWriter writer = Files.newBufferedWriter(logFilePath, StandardOpenOption.APPEND)) {
            writer.write(message);
            writer.newLine();
        } catch (IOException e) {
            // Log to console or some other fallback mechanism
        }
    }

    private int generateRandomWithinRange(Range range) {
        if (range.isClosed()) {
            return random.nextInt((range.getMax() - range.getMin()) + 1) + range.getMin();
        } else {
            return random.nextInt((range.getMax() - range.getMin())) + range.getMin() + 1;
        }
    }

