public class AdvancedRandomValueGenerator {
    private static final Logger logger = Logger.getLogger(AdvancedRandomValueGenerator.class);

    private Random random;
    private Map<Range, Integer[]> cache = new HashMap<>();

    public AdvancedRandomValueGenerator() {
        this.random = new Random();
    }

    public AdvancedRandomValueGenerator(long seed) {
        this.random = new Random(seed);
    }

    // Add a range to the cache and generate random values within it
    private Integer[] addToCacheAndGenerateValues(Range range, int length) {
        Integer[] generatedValues = new Integer[length];
        for (int i = 0; i < length; i++) {
            if (range.isClosed()) {
                generatedValues[i] = random.nextInt((int)(range.getMax() - range.getMin() + 1)) + (int)range.getMin();
            } else {
                generatedValues[i] = random.nextInt((int)(range.getMax() - range.getMin())) + (int)range.getMin() + 1;
            }
        }
        cache.put(range, generatedValues);
        return generatedValues;
    }

    // Generate a single random value within the specified range
    public int nextInt(Range range) {
        if (!cache.containsKey(range)) {
            addToCacheAndGenerateValues(range, 1000);
        }
        Integer[] cachedValues = cache.get(range);
        return (cachedValues != null && cachedValues.length > 0) ? cachedValues[random.nextInt(cachedValues.length)] : -1;
    }

    // Generate an array of random values within the specified range
    public Integer[] nextInts(Range range, int length) {
        if (cache.containsKey(range)) {
            Integer[] cachedValues = cache.get(range);
            return Arrays.copyOf(cachedValues, Math.min(length, cachedValues.length));
        } else {
            return addToCacheAndGenerateValues(range, length);
