    private MessageDigest md5Digest;
    private final static Logger logger = Logger.getLogger(AdvancedFileHasher.class.getName());

    public AdvancedFileHasher() throws Exception{
        this.md5Digest = MessageDigest.getInstance("MD5");
    }

    //Calculate MD5 hash of a file in chunks with a progress indicator.
    void calculateMd5(Path path, int chunkSize, long startPos) {
        try (FileChannel fc = FileChannel.open(path)) {
            ByteBuffer buffer = ByteBuffer.allocate(chunkSize);

            //Skip to the start position if specified
            fc.position(startPos);
            int bytesRead;
            while ((bytesRead = fc.read(buffer)) != -1) {
                md5Digest.update(buffer.array(), 0, bytesRead);
                logger.info("Processed " + bytesRead + " bytes");
                buffer.clear(); //clear the buffer for next read
            }
        } catch (Exception e) {
            logger.severe("Error processing file: "+e);
        }
    }

    public byte[] getHash() {
        return md5Digest.digest(); 
    }
}
