Python function for calculating MD5 hash of a file given its path in chunks with a progress indicator callback function:
```python
import hashlib
from typing import Callable

def calculate_md5(file_path: str, chunk_size: int=8192, start_pos: int=0, progress_callback: Callable[[int], None]=None):
    md5 = hashlib.md5()

    with open(file_path,'rb') as f:
        f.seek(start_pos)
        while True:
            data = f.read(chunk_size)

            if not data:
                break

            md5.update(data)
            if progress_callback is not None:
                progress_callback(f.tell())  # call the callback with current position in file
    return md5.digest()
```
