import javax.crypto.*;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.io.*;
import java.security.*;
import org.json.*;

public class CryptographyUtils {
    private static final String ALGORITHM = "DESede";
    private static final int KEY_SIZE = 24;
    private static final int READ_WRITE_BUFFER_SIZE = 1024;

    public static JSONObject decryptAndHashFile(File file, String encryptedBase64Data, byte[] keyBytes, byte[] iv) throws Exception {
        SecretKey secretKey = new SecretKeySpec(keyBytes, ALGORITHM);
        IvParameterSpec ivParams = new IvParameterSpec(iv);

        Cipher cipher = Cipher.getInstance(ALGORITHM + "/CBC/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, secretKey, ivParams);

        byte[] decryptedData;
        try (InputStream encryptedInputStream = new ByteArrayInputStream(Base64.getDecoder().decode(encryptedBase64Data));
             FileOutputStream outputFileStream = new FileOutputStream(file)) {
            CipherInputStream cis = new CipherInputStream(encryptedInputStream, cipher);
            MessageDigest md = MessageDigest.getInstance("MD5");

            byte[] buffer = new byte[READ_WRITE_BUFFER_SIZE];
            int bytesRead;
            while ((bytesRead = cis.read(buffer)) != -1) {
                outputFileStream.write(buffer, 0, bytesRead);
                md.update(buffer, 0, bytesRead);
            }

            decryptedData = Files.readAllBytes(file.toPath());
        } catch (Exception e) {
            throw new Exception("Error during file decryption and MD5 hash calculation: " + e.getMessage(), e);
        }

        byte[] hashInBytes = md.digest();
        StringBuilder sb = new StringBuilder();
        for (byte b : hashInBytes) {
            sb.append(String.format("%02x", b));
        }

        JSONObject result = new JSONObject();
        result.put("decryptedData", new String(decryptedData));
        result.put("md5Hash", sb.toString());

        return result;
    }

