import java.util.*;
import java.io.*;
import java.lang.Math;
import java.nio.file.*;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;

public class AdvancedRandomValueGenerator {
    private static final Logger logger = LogManager.getLogger(AdvancedRandomValueGenerator.class);
    private float min;
    private float max;
    private boolean closed;
    private long seed;
    private Random rand;
    private Map<String, List<Float>> cache;
    private Gson gson = new Gson();

    public AdvancedRandomValueGenerator(float min, float max, boolean closed) {
        this.min = min;
        this.max = max;
        this.closed = closed;
        this.rand = new Random();
        this.cache = new HashMap<>();
        logger.info("AdvancedRandomValueGenerator initialized with range: " + toString());
    }

    public AdvancedRandomValueGenerator(Range range) {
        this(range.getMin(), range.getMax(), range.isClosed());
    }

    public void setSeed(long seed) {
        this.seed = seed;
        rand.setSeed(seed);
        logger.info("Seed set to: " + seed);
    }

    private float nextFloat() {
        return min + (max - min) * rand.nextFloat();
    }

    public float generateRandomValue() {
        String key = this.toString();
        if (!cache.containsKey(key)) cache.put(key, new ArrayList<>());
        float value = nextFloat();
        cache.get(key).add(value);
        logger.info("Generated random value: " + value);
        return value;
    }

    public List<Float> generateRandomValues(int length) {
        String key = this.toString();
        if (!cache.containsKey(key)) cache.put(key, new ArrayList<>());
        List<Float> values = new ArrayList<>();
        for (int i = 0; i < length; i++) {
            float value = nextFloat();
            values.add(value);
            cache.get(key).add(value);
        }
        logger.info("Generated " + length + " random values");
        return values;
    }

