using System.Linq;

public class FileProcessor
{
    private readonly ConcurrentDictionary<string, string> _fileCache = new ConcurrentDictionary<string, string>();

    public void ProcessFile(string path)
    {
        int retryCount = 0;
        while (retryCount < 3)
        {
            try
            {
                using var fileStream = File.OpenRead(path);
                byte[] buffer = new byte[64 * 1024]; // Read in chunks of 64 KB
                int bytesRead;
                MD5 md5 = MD5.Create();
                do
                {
                    bytesRead = fileStream.Read(buffer, 0, buffer.Length);
                    if (bytesRead > 0)
                    {
                        md5.TransformBlock(buffer, 0, bytesRead, null, 0);
                    }
                } while (bytesRead > 0);
                md5.TransformFinalBlock(buffer, 0, 0);

                _fileCache[path] = BitConverter.ToString(md5.Hash).Replace("-", "").ToLower(); // Store MD5 hash in cache
            }
            catch (IOException ex)
            {
                Console.WriteLine($"Error processing file: {ex.Message}");
                retryCount++;
                Thread.Sleep(1000); // Wait for 1 second before retrying
            }
        }

        if (retryCount == 3)
        {
            Console.WriteLine("Failed to process file after 3 retries");
        }
    }
}
