Here's a simple C function for a dynamic list with thread-safe concurrent access:
```c
#include <stdio.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    int CELL_ID;
    int PCI;
    double RSRP_LEVEL;
    long TIMESTAMP;
} NR_CELL_INFO_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    size_t size;
    size_t capacity;
    NR_CELL_INFO_PDU_T* data;
} DynamicList;

void init(DynamicList *list) {
    list->size = 0;
    list->capacity = 2;
    list->data = malloc(sizeof(NR_CELL_INFO_PDU_T) * list->capacity);
    pthread_mutex_init(&list->mutex, NULL);
}

void append(DynamicList *list, NR_CELL_INFO_PDU_T value) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->data = realloc(list->data, sizeof(NR_CELL_INFO_PDU_T) * list->capacity);
    }

    memcpy(&list->data[list->size], &value, sizeof(value));
    list->size++;

    pthread_mutex_unlock(&list->mutex);
}
```
This code defines a `DynamicList` structure to hold the array and its size/capacity. The append function locks the mutex before accessing the data, ensuring that only one thread can access it at a time. If the list is full, it doubles the capacity by reallocating memory. It then copies the new value into the list and increments the size. Finally, it unlocks the mutex so other threads may access the data.
"]

