    if((*keyFile = fopen(request->privateKeyLocation, "r")) == NULL) return -1;
    return 0;
}

// Function to combine cert and key into PEM file
int combinePEM(OAuthRequest *request, char* outputFileName) {
    FILE *certFile, *keyFile, *pemFile;

    if (fetchCertificateAndPrivateKey(request, &certFile, &keyFile) != 0) return -1;
    if((pemFile = fopen(outputFileName, "w")) == NULL) {
        fclose(certFile);
        fclose(keyFile);
        return -1;
    }

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), certFile) != NULL) {
        fputs(buffer, pemFile);
    }
    fputs("\n", pemFile); // Certificate and private key must be separated by a newline in PEM format

    while (fgets(buffer, sizeof(buffer), keyFile) != NULL) {
        fputs(buffer, pemFile);
    }

    fclose(certFile);
    fclose(keyFile);
    fclose(pemFile);
