import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import com.pokeapi.PokemonService; // assuming you're using a library to fetch Pokémon data

public class AdvancedRandomValueGenerator {
    private static final Logger logger = LogManager.getLogger(AdvancedRandomValueGenerator.class);

    private int min, max;
    private boolean closedMin, closedMax;
    private long seed;
    private Random random;
    private Map<Range, List<Number>> cache;

    public AdvancedRandomValueGenerator(int min, int max, boolean closedMin, boolean closedMax, Long seed) {
        this.min = min;
        this.max = max;
        this.closedMin = closedMin;
        this.closedMax = closedMax;
        this.seed = (seed == null) ? new Random().nextLong() : seed;
        this.random = new Random(this.seed);
        this.cache = new HashMap<>();
    }

    public float getRandomFloat() {
        float value = min + random.nextFloat() * (max - min);
        logger.info("Generated float: {}", value);
        return value;
    }

    public int getRandomInt() {
        int value = closedMin ? min : min + 1;
        value += random.nextInt(max - value + ((closedMax) ? 1 : 0));
        logger.info("Generated integer: {}", value);

        // Caching mechanism
        Range range = new Range(min, max, closedMin, closedMax);
        if (cache.containsKey(range)) {
            cache.get(range).add(value);
        } else {
            List<Number> numbers = new ArrayList<>();
            numbers.add(value);
            cache.put(range, numbers);
        }

        return value;
    }

    public float[] getRandomFloats(int length) {
        float[] values = new float[length];
        for (int i = 0; i < length; ++i) {
            values[i] = getRandomFloat();
        }
        return values;
    }

    public int[] getRandomInts(int length) {
        int[] values = new int[length];
        for (int i = 0; i < length; ++i) {
            values[i] = getRandomInt();
        }
        return values;
    }

    public List<Number> getCachedValues(Range range) {
        return cache.getOrDefault(range, new ArrayList<>());
    }

    @Override
    public String toString() {
        int totalCached = 0;
        for (List<Number> numbers : cache.values()) {
            totalCached += numbers.size();
        }
        return "AdvancedRandomValueGenerator: min=" + min + ", max=" + max + ", seed=" + seed 
                + ", cached values count=" + totalCached;
    }

    public static String getPokemonWeaknesses(String type) {
        PokemonService pokemonService = new PokemonService();
        return pokemonService.getTypeWeaknesses(type);
    }
}
