void error_callback(const char *str) {
    fprintf(stderr, "%s\n", str);
}

int setup_ssl_connection(SSL_CTX **ctx, SSL **ssl, const char* cert, const char* key, int optimize_speed) {
    OpenSSL_add_all_algorithms();
    SSL_load_error_strings();
    *ctx = SSL_CTX_new(optimize_speed ? TLS_method() : TLSv1_2_method());  // Select the method based on optimization flag

    if (*ctx == NULL) { error_callback("Error creating context"); return -1; }

    if (!SSL_CTX_use_certificate_file(*ctx, cert, SSL_FILETYPE_PEM)) { error_callback("Error loading certificate file"); return -2; }
    if (!SSL_CTX_use_PrivateKey_file(*ctx, key, SSL_FILETYPE_PEM)) { error_callback("Error loading private key file"); return -3; }

    *ssl = SSL_new(*ctx);  // Create new SSL connection object using the context
    if (*ssl == NULL) { error_callback("Error creating SSL"); return -4; }

    // Configure SSL for PFS and optimize performance based on flag
    SSL_CTX_set_options(*ctx, optimize_speed ? SSL_OP_NO_COMPRESSION : 0);

    return 0;
}

void cleanup(SSL *ssl, SSL_CTX *ctx) {
    if (ssl != NULL) { SSL_free(ssl); }
    if (ctx != NULL) { SSL_CTX_free(ctx); }
}

