    pthread_t threads[numPackets];

    for (int i = 0; i < numPackets; i++) {
        pthread_create(&threads[i], NULL, populatePacket, (void*)(long)i);
    }

    // Wait for all threads to complete before returning control back to the main thread
    for (int i = 0; i < numPackets; i++) {
        sem_wait(&semaphore);  // Wait until each thread has completed its task
    }
}
