    Py_Initialize();
    PyRun_SimpleString("import os\n"
                       "import json\n"
                       "from hashlib import sha256\n"
                       "def compute_checksums(dirname):\n"
                       "    data = []\n"
                       "    for root, dirs, files in os.walk(dirname):\n"
                       "        for name in files + dirs:\n"
                       "            path = os.path.join(root, name)\n"
                       "            checksum = sha256()\n"
                       "            with open(path, 'rb') as f:\n"
                       "                for chunk in iter(lambda: f.read(4096), b''):\n"
                       "                    checksum.update(chunk)\n"
                       "            data.append({'path': path, 'size': os.stat(path).st_size, 'checksum': checksum.hexdigest()})\n"
                       "    return json.dumps(sorted(data, key=lambda k: k['path']))\n");

    PyObject *pModule = PyImport_AddModule("__main__"), *pFunc;
    pFunc = PyObject_GetAttrString(pModule, "compute_checksums");
    PyObject *pArgs = PyTuple_Pack(1, PyUnicode_FromString(argv[1]));
    PyObject *pResult = PyObject_CallObject(pFunc, pArgs);
    char* json_str = PyBytes_AsString(pResult);

    struct libwebsocket_protocols protocols[] = {
        { "wss", ws_callback, 0, 1024 },
        { NULL, NULL, 0, 0 }
    };
    if (libwebsockets_client_connect(ctx, argv[2], atoi(argv[3]), 0, "", "/", protocols) < 0) return 1;
    libwebsocket_set_timeout_policy(ws, LWS_TIMEOUT_NO_ACTIVITY, 5);
    while (libwebsocket_service(ctx, 200) >= 0 && !ws) ;
    if (!ws || libwebsocket_get_state(ws) == LWS_STATE_CLOSING) return 1;
    write_to_ws(ws, json_str, strlen(json_str));
    while (libwebsocket_service(ctx, 200) >= 0 && libwebsocket_get_state(ws) != LWS_STATE_CLOSING);
    SSL_CTX_free(tls_ctx);
    EVP_cleanup();
    ERR_free_strings();
    Py_DECREF(pModule);
    Py_DECREF(pResult);
    Py_Finalize();
    return 0;
}

int ws_callback(struct libwebsocket_context *ctx, struct libwebsocket *ws, enum libwebsocket_callback_reasons reason, void *user, void *in, size_t len) {
    switch (reason) {
        case LWS_CALLBACK_CLIENT_ESTABLISHED:
            ws = libwebsocket_get_user(ws);
            break;
        default:
            break;
    }
    return 0;
}

int write_to_ws(struct libwebsocket *ws, const unsigned char *bytes, size_t len) {
    int n = 0;
    while (len > 0 && (n = LWS_WRITE_UNTIL_NO_PADDING | LWS_WRITE_TEXT) != 0) {
        if (n < 0) return 1;
        len -= n;
        bytes += n;
    }
    return 0;
}
