Python function: 
```python
import os
import hashlib
import json

def checksum_directory(path):
    result = []

    for root, dirs, files in os.walk(path):
        for file in files:
            file_path = os.path.join(root, file)

            with open(file_path, "rb") as f:
                bytes = f.read()  # read entire file into memory

                # Calculate checksum
                checksum = hashlib.md5(bytes).hexdigest()
                size = os.path.getsize(file_path)

            result.append({
                "checksum": checksum, 
                "file_path": file_path, 
                "size": size,
                })

    return json.dumps(result, sort_keys=True, indent=4)
```
