```python
import hashlib
def md5_hash(filepaths):
    total = len(filepaths)
    cumulative_hash = hashlib.md5()
    for i, filepath in enumerate(filepaths):
        with open(filepath, 'rb') as f:
            while True:
                data = f.read(65536)  # read in chunks of 64KB
                if not data:
                    break
                cumulative_hash.update(data)
        print('Percentage completed:', ((i+1)/total)*100, '%')
    return cumulative_hash.hexdigest()
