#define EXAMPLE_PROTOCOL_NAME "example-protocol"

static int callback_example(struct lws *wsi, enum lws_callback_reasons reason, void *user, void *in, size_t len) {
    switch (reason) {
        case LWS_CALLBACK_CLIENT_ESTABLISHED:
            lwsl_notice("Connection established\n");
            break;
        case LWS_CALLBACK_CLIENT_RECEIVE:
            // Handle incoming messages here
            break;
        default:
            break;
    }
    return 0;
}

struct lws_protocols protocols[] = {
    { EXAMPLE_PROTOCOL_NAME, callback_example, sizeof(int), 128, 0 },
    { NULL, NULL, 0, 0 } // End of list
};

void connect_to_server(char *hostname, int port) {
    struct lws_context_creation_info info;
    memset(&info, 0, sizeof(struct lws_context_creation_info));

    // Set up SSL context
    SSL_CTX* ctx = SSL_CTX_new(TLSv1_2_client_method());
    if (ctx == NULL) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    // Set up WebSocket context
    info.port = CONTEXT_PORT_NO_LISTEN;
    info.iface = NULL;
    info.protocols = protocols;
    info.ssl_private_key_password = "passphrase";
    info.options |= LWS_SERVER_OPTION_DO_SSL_GLOBAL_INIT;
    info.ssl_cert_filepath = "client-cert.pem";
    info.ssl_private_key_filepath = "client-key.pem";
    info.options |= LWS_SERVER_OPTION_REQUIRE_VALID_OPENSSL_CLIENT_CERT;

    struct lws_context *context = lws_create_context(&info);
    if (!context) {
        lwsl_err("lws init failed\n");
        return;
    }

    char path[256] = "/";
    struct lws_client_connect_info ccinfo = {0};
    ccinfo.context = context;
    ccinfo.address = hostname;
    ccinfo.port = port;
    ccinfo.path = path;
    ccinfo.host = hostname;
    ccinfo.origin = "libwebsockets-client";
    ccinfo.protocol = EXAMPLE_PROTOCOL_NAME;
    struct lws *wsi = lws_client_connect_via_info(&ccinfo);

    // Main loop to keep the connection alive
    while(1) {
        lws_service(context, 50);
    }
}
```
