// Python wrapper for MD5 hashing function
static PyObject* calculateMD5(PyObject* self, PyObject* args) {
    char *filename;
    int chunkSize;

    if (!PyArg_ParseTuple(args, "si", &filename, &chunkSize))
        return NULL;

    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        PyErr_SetString(PyExc_IOError, "Failed to open the file.");
        return NULL;
    }

    unsigned char buffer[chunkSize];
    size_t bytesRead;

    md5_state_t state;
    md5_byte_t digest[16]; // MD5 has 16 bytes

    md5_init(&state);

    while ((bytesRead = fread(buffer, 1, chunkSize, file)) > 0) {
        md5_append(&state, (const md5_byte_t*)buffer, bytesRead);
    }

    md5_finish(&state, digest);

    char hexDigest[32];
    for(int i = 0; i < 16; ++i) {
        sprintf(&hexDigest[i*2], "%02x", digest[i]);
    }

    return Py_BuildValue("s", hexDigest);
}
```

