import hashlib, os
from threading import Thread

def calculateMD5Hash(filePaths):
    class WorkerThread(Thread):
        def __init__(self, path):
            super().__init__()
            self.path = path

        def run(self):
            md5 = hashlib.md5()
            with open(self.path,'rb') as file:
                while True:
                    chunk = file.read(4096)
                    if not chunk: break
                    md5.update(chunk)
            return self.path, md5.hexdigest()

    threads = [WorkerThread(path) for path in filePaths]
    results = []

    for thread in threads:
        try: 
            thread.start()
        except Exception as e:
            print('Failed to start thread', str(e))

    for thread in threads:
        try: 
            thread.join()
            results.append(thread.run())
        except Exception as e:
            print('Failed to join thread', str(e))

    return results
```
Note: The above Python code assumes that the file paths are valid, and does not handle exceptions related to invalid or inaccessible files. If you want to include such checks, they would need to be added. 

