["Here's how you might solve this task in C using pthread mutexes to manage concurrency:

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int sender_id;
    time_t timestamp;
    char* payload;
} Message;

Message** messages = NULL;
size_t messageCount = 0;
pthread_mutex_t lock;

void add_message(int sender_id, const char* payload) {
    pthread_mutex_lock(&lock);

    // Create new message object
    Message* msg = malloc(sizeof(Message));
    if (msg == NULL) exit(1);  // Handle memory allocation failure
    msg->sender_id = sender_id;
    time(&msg->timestamp);
    msg->payload = strdup(payload);
    if (msg->payload == NULL) exit(1);  // Handle memory allocation failure

    // Add to array
    messages = realloc(messages, sizeof(Message*) * (messageCount + 1));
    if (messages == NULL) exit(1);  // Handle memory allocation failure
    messages[messageCount++] = msg;

    pthread_mutex_unlock(&lock);
}

void remove_by_sender(int sender_id) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < messageCount; ++i) {
        if (messages[i]->sender_id == sender_id) {
            free(messages[i]->payload);  // Free memory associated with the removed message
            messages[i] = messages[--messageCount];  // Shift remaining elements down
            --i;  // Decrease i to account for the shift
        }
    }

    pthread_mutex_unlock(&lock);
}

const Message* get_latest(int sender_id) {
    const Message* latest = NULL;

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < messageCount; ++i) {
        if (messages[i]->sender_id == sender_id && (latest == NULL || messages[i]->timestamp > latest->timestamp))
            latest = messages[i];  // Found a message from the given sender with later timestamp
    }

    pthread_mutex_unlock(&lock);

    return latest;
}
```
This code uses a dynamic array to store `Message` objects. Every time a new message is added, it's appended at the end of the array and `messageCount` is incremented. When removing messages by sender ID or retrieving the latest message, every access to the array is protected by the mutex to ensure thread-safe operation. Note that memory allocation failures are not handled in this code (a real application would do so).
"]

