void* hash_file(void *arg) {
    file_info *fi = (file_info*) arg;
    char buffer[4096];
    MD5_CTX mdContext;

    MD5_Init(&mdContext);
    while (fi->offset < fi->total_size) {
        ssize_t bytes_read = pread(fi->fd, buffer, sizeof(buffer), fi->offset);
        if (bytes_read <= 0) break;

        MD5_Update(&mdContext, buffer, bytes_read);
        fi->offset += bytes_read;
    }

    MD5_Final(fi->data->md5_digest, &mdContext);
    return NULL;
}

