typedef struct {
    TCP_CONNECTION_STATS_T *data;
    size_t size;
    size_t capacity;
} DynamicArray;

void init(DynamicArray *a, size_t initialSize) {
    a->data = malloc(initialSize * sizeof(TCP_CONNECTION_STATS_T));
    a->size = 0;
    a->capacity = initialSize;
}

void insert(DynamicArray *a, TCP_CONNECTION_STATS_T element) {
    if (a->size == a->capacity) {
        a->capacity *= 2;
        a->data = realloc(a->data, a->capacity * sizeof(TCP_CONNECTION_STATS_T));
    }
    a->data[a->size++] = element;
}

int compare(const void* a, const void* b) {
    return ((TCP_CONNECTION_STATS_T*)b)->bytes_received - ((TCP_CONNECTION_STATS_T*)a)->bytes_received;
}

void sortByBytesReceived(DynamicArray *a) {
    qsort(a->data, a->size, sizeof(TCP_CONNECTION_STATS_T), compare);
}

