    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error opening file %s\n", filename);
        return;
    }

    MD5_CTX context;
    MD5_Init(&context);

    const int bufferSize = 8192; // or any other chunk size you find appropriate
    unsigned char* buffer = malloc(bufferSize);

    while (!feof(file)) {
        size_t bytesRead = fread(buffer, 1, bufferSize, file);
        MD5_Update(&context, buffer, bytesRead);
    }

    free(buffer);
    fclose(file);

    MD5_Final(result, &context);
}
