#include <unordered_map>
#include <thread>
#include <mutex>
#include <chrono>
#include <sstream>

class NfadRandValGen {
private:
    struct Range {
        int min;
        int max;
        bool isOpen;
    };

    std::unordered_map<int, int> cache;
    std::mutex mtx;

    Range range = {0, 100, false}; // Default range
    unsigned seed = std::time(nullptr); // Current time as a default seed

public:
    NfadRandValGen() {}

    void setRange(int min, int max, bool isOpen) {
        if (min > max || min == max && !isOpen) {
            std::cerr << "Invalid range inputs. Please provide valid range.";
            return;
        }

        this->range = {min, max, isOpen};
    }

    void setSeed(unsigned seed) {
        this->seed = seed;
    }

    int generate() {
        std::lock_guard<std::mutex> lock(mtx); // Lock the mutex to ensure thread safety.

        if (cache.size() >= 10000) { // Alert developer if cache size exceeds limit.
            std::cerr << "Cache usage is high, consider evicting some entries.";
            return -1; 
        }

        static std::default_random_engine generator(seed); // Initialize the random engine with seed.
        std::uniform_int_distribution<int> distribution(range.min, range.max); // Define the distribution.

        int number = distribution(generator); // Generate a new random number from cache or generate one.

        if (cache.find(number) == cache.end()) {
            cache[number] = 1; // Store generated number in cache.
        } else {
            cache[number]++; // Increment the count of previously used numbers.
        }

        return number;
    }

    std::vector<int> generate(int size) {
        std::lock_guard<std::mutex> lock(mtx); // Lock the mutex to ensure thread safety.

        if (size > 10000 * cache.size()) { // Alert developer if cache size exceeds limit.
            std::cerr << "Requested size is too large, consider using a larger cache.";
            return {}; 
        }

        std::vector<int> numbers(size);

        for (int i = 0; i < size; ++i) {
            numbers[i] = generate();
        }

        return numbers;
    }

    void ToString() const {
        std::stringstream ss;

        ss << "Current range is from " << range.min 
            << " to " << (range.isOpen ? "infinity" : std::to_string(range.max)) << ". ";

        ss << "Seed: " << seed << ". ";

        ss << cache.size() << " entries in cache.";

        std::cout << ss.str();
    }

    // Methods to handle external logging service and potential resource exhaustion scenarios. 
};
```
