```python
import hashlib

def compute_md5(filepath):
    buffer_size = 8192  # You may choose a different size if needed

    try:
        md5 = hashlib.md5()

        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(buffer_size), b''):
                md5.update(chunk)

        return md5.digest()
    except IOError as e:
        print("I/O error({0}): {1}".format(e.errno, e.strerror))
