    private long seed;
    private Random random;
    private Map<Range, List<Number>> cache = new HashMap<>();

    public AdvancedRandomValueGenerator(float min, float max, long seed) {
        this.min = min;
        this.max = max;
        this.seed = seed;
        this.random = new Random(seed);
    }

    // Single random value generation
    public float nextFloat() {
        return getRandomValueFromRange(this.min, this.max);
    }

    // Array of random values generation
    public List<Number> generateArrayOfValues(int length) {
        Range range = new Range(this.min, this.max);
        if (cache.containsKey(range)) {
            return cache.get(range).subList(0, Math.min(length, cache.get(range).size()));
        } else {
            List<Number> values = new ArrayList<>();
            for (int i = 0; i < length; i++) {
                values.add(nextFloat());
            }
            cache.put(range, values);
            return values;
        }
    }

    private float getRandomValueFromRange(float min, float max) {
        if (min >= max) {
            throw new IllegalArgumentException("Min must be less than Max");
        }
        return min + random.nextFloat() * (max - min);
    }

