typedef struct {
    char *filePath;
    unsigned char *md5Digest;
} FileHashStruct;

void *calculateMD5(void *args) {
    FileHashStruct *fhs = (FileHashStruct*) args;
    FILE *inFile = fopen(fhs->filePath, "rb");
    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];

    if (inFile == NULL) {
        printf("%s can't be opened.\n", fhs->filePath);
        return NULL;
    }

    MD5_Init(&mdContext);
    while ((bytes = fread(data, 1, 1024, inFile)) != 0) {
        MD5_Update(&mdContext, data, bytes);
    }
    MD5_Final(fhs->md5Digest, &mdContext);

    fclose(inFile);
    return NULL;
}

