std::vector<PaymentProcessingRequest> populateArray(const char* fileName) {
    std::mutex mtx;
    std::ifstream infile(fileName, std::ios::binary);
    tinyxml2::XMLDocument doc;
    doc.LoadFile(fileName);

    int size = doc.FirstChildElement("root")->IntAttribute("size");

    std::vector<PaymentProcessingRequest> array(size);

    auto populateSegment = [&](int start, int end) {
        for (int i = start; i < end; ++i) {
            std::lock_guard<std::mutex> lock(mtx);  // Thread-safe access

            // Populate array segment here
        }
    };

    // Use multiple threads to populate the array in parallel
    int numThreads = std::thread::hardware_concurrency();
    std::vector<std::thread> threads(numThreads);
    for (int i = 0; i < numThreads; ++i) {
        int start = i * size / numThreads;
        int end = (i + 1) * size / numThreads;
        threads[i] = std::thread(populateSegment, start, end);
    }

    // Wait for all threads to finish
    std::for_each(threads.begin(), threads.end(), [](std::thread &t) { t.join(); });

    return array;
}
```

