import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import org.apache.commons.lang3.tuple.Pair;

public class EnhancedFileAndDataHandler {
    private String filePaths[];
    private int minValue, maxValue;
    private long seed;
    private Map<String, Pair<Integer, Exception>> hashingHistory = new HashMap<>();
    private boolean closedRange;

    public EnhancedFileAndDataHandler(String[] filePaths, Range range) {
        this.filePaths = filePaths;
        this.minValue = range.getMin();
        this.maxValue = range.getMax();
        this.seed = new Random().nextLong();
        this.closedRange = range.isClosed();
    }

    public float generateRandomFloat() {
        return getNextFloatInRange(minValue, maxValue);
    }

    public int generateRandomInt() {
        return getNextIntInRange(minValue, maxValue);
    }

    private float getNextFloatInRange(int min, int max) {
        Random r = new Random();
        if (closedRange) {
            return min + ((max - min) * r.nextFloat());
        } else {
            return min + ((max - min - 1) * r.nextFloat());
        }
    }

    private int getNextIntInRange(int min, int max) {
        Random r = new Random();
        if (closedRange) {
            return r.nextInt((max - min) + 1) + min;
        } else {
            return r.nextInt((max - min)) + min;
        }
    }

    public float[] generateRandomFloats(int count) {
        float[] values = new float[count];
        for (int i = 0; i < count; i++) {
            values[i] = getNextFloatInRange(minValue, maxValue);
        }
        return values;
    }

    public int[] generateRandomInts(int count) {
        int[] values = new int[count];
        for (int i = 0; i < count; i++) {
            values[i] = getNextIntInRange(minValue, maxValue);
        }
        return values;
    }

    public Pair<String, Map<String, Pair<Integer, Exception>>> generateMd5Hash() throws IOException {
        String cumulativeHashValue = "";
        for (int i = 0; i < filePaths.length; i++) {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                Path path = FileSystems.getDefault().getPath(filePaths[i]);
                long size = Files.size(path);
                InputStream is = Files.newInputStream(path);
                byte[] buffer = new byte[8192];
                int len;
                while ((len = is.read(buffer)) != -1) {
                    md.update(buffer, 0, len);
                }
                cumulativeHashValue += bytesToHex(md.digest());
                System.out.println("Processed " + (((i+1)*100)/filePaths.length) + "%");
            } catch (Exception ex) {
                hashingHistory.put(filePaths[i], Pair.of(i, ex));
            }
        }
        return Pair.of(cumulativeHashValue, hashingHistory);
    }

    private static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }
}
```
