```java
import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import org.apache.commons.lang3.tuple.Pair;

public class EnhancedFileAndDataHandler {
    private List<String> filePaths = new ArrayList<>();
    private int minValue, maxValue, seed;
    private boolean closedRange;
    private Random rand;
    private MessageDigest md5Hasher;

    public EnhancedFileAndDataHandler(List<String> paths, int min, int max, boolean closed, int seed) throws NoSuchAlgorithmException {
        this.filePaths = paths;
        this.minValue = min;
        this.maxValue = max;
        this.closedRange = closed;
        this.seed = seed;

        rand = new Random(this.seed);
        md5Hasher = MessageDigest.getInstance("MD5");
    }

    public float generateRandomFloat() {
        if (closedRange) 
            return minValue + rand.nextFloat() * (maxValue - minValue);
         else
            return minValue + rand.nextFloat() * (maxValue - minValue + 1);
    }

    public int generateRandomInt() {
        if (closedRange) 
            return minValue + rand.nextInt(maxValue - minValue + 1);
         else
            return minValue + rand.nextInt(maxValue - minValue);
    }

    public float[] generateArrayOfRandomFloats(int length) {
        float[] array = new float[length];
        for (int i = 0; i < length; i++) 
            array[i] = generateRandomFloat();
         return array;
    }

    public int[] generateArrayOfRandomInts(int length) {
        int[] array = new int[length];
        for (int i = 0; i < length; i++) 
            array[i] = generateRandomInt();
         return array;
    }

    public Pair<String, Map<String, String>> calculateMD5HashOfFiles() {
        StringBuilder hashValueBuilder = new StringBuilder();
        Map<String, String> fileStatusMap = new HashMap<>();

        for (String path : filePaths) {
            try(FileInputStream fis = new FileInputStream(new File(path))) {
                byte[] buffer = new byte[1024];
                int read = 0;

                while ((read = fis.read(buffer)) != -1) 
                    md5Hasher.update(buffer, 0, read);

                String hashValue = new BigInteger(1, md5Hasher.digest()).toString(16);
                hashValueBuilder.append(hashValue);
                fileStatusMap.put(path, "Successfully hashed");
            } catch (IOException e) {
                fileStatusMap.put(path, "Error during hashing: " + e.getMessage());
            } finally {
                md5Hasher.reset();
            }
        }

        return Pair.of(hashValueBuilder.toString(), fileStatusMap);
    }

    public void logActivity() {
        // Implement your logging mechanism here, e.g., using a logger such as java.util.logging.Logger
    }
}
```
Please note that error handling and edge case handling are minimal in this example, you may need to implement additional measures according to your needs. 
Also, the use of `MessageDigest` for MD5 hashing is not included in this solution because it is a complex topic with nuances and potential security implications. If you require more advanced features, consider using a library like Bouncy Castle.
