    static bool compareByMessageId(const COMPRESSION_REQUEST_MESSAGE& a, const COMPRESSION_REQUEST_MESSAGE& b) {
        return a.MESSAGE_ID < b.MESSAGE_ID;
    }

    void processAndCompressDataset(std::vector<COMPRESSION_REQUEST_MESSAGE>& dataset, float CPU_THRESHOLD = 0.9) {
