        std::sort(dataset.begin(), dataset.end(), compareByMessageId);

        // Calculate average DATA_SIZE and COMPRESSION_LEVEL
        size_t totalDataSize = 0;
        float totalCompressionLevel = 0.0f;
        for (const auto& message : dataset) {
            totalDataSize += message.DATA_SIZE;
            totalCompressionLevel += message.COMPRESSION_LEVEL;
        }

        size_t averageDataSize = totalDataSize / dataset.size();
        float averageCompressionLevel = totalCompressionLevel / dataset.size();

        // Initialize compression context and allocate memory for the sliding window buffer
        void* compressionContext = initializeCompressionContext(averageDataSize, averageCompressionLevel);

