    struct Node* prev;
    struct Node* next;
}Node;

// Struct for managing nodes
typedef struct List {
    Node *head;
    Node *tail;
    int count;
    pthread_mutex_t lock;
}List;

void initList(List *list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&(list->lock), NULL);
}

void addNode(List *list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&(list->lock));

    Node *node = (Node*) malloc(sizeof(Node));
    node->data = data;  // Assume proper assignment is implemented.
    node->prev = list->tail;
    node->next = NULL;

    if(list->tail == NULL) {
        list->head = node;
    } else {
        list->tail->next = node;
    }

    list->tail = node;
    list->count++;

    pthread_mutex_unlock(&(list->lock));
}

// Custom HashTable
typedef struct NodeHash {
    int key;
    struct NodeHash *next;
}NodeHash;

NodeHash* hashTable[SIZE];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

