}

void insert_in_table(NodeHash *node, int key) {
    pthread_mutex_lock(&lock);

    unsigned long index = create_hash(key);
    node->next = hashTable[index];
    node->key = key;
    hashTable[index] = node;

    pthread_mutex_unlock(&lock);
}

NodeHash* search_in_table(int value) {
