```java
import java.sql.*;
import java.util.*;
import java.util.function.*;

public class BatchDataProcessor {
    private String dbUrl;
    private Properties props;
    private Connection conn;

    // cache map, with keys as the range of indices and values as list of records in that range
    private Map<Pair<Integer, Integer>, List<Record>> cache = new HashMap<>(); 
    private int hits = 0;
    private int misses = 0;

    // Query parameters
    private RecordFilter filter;

    public BatchDataProcessor(String dbUrl, Properties props) {
        this.dbUrl = dbUrl;
        this.props = props;

        try {
            conn = DriverManager.getConnection(dbUrl, props);
        } catch (SQLException e) {
            System.err.println("Invalid database connection: " + e.getMessage());
        }
    }

    public List<Record> executeQuery(int startIndex, int endIndex) throws SQLException {
        if (startIndex < 0 || endIndex < startIndex) {
            throw new IllegalArgumentException("Invalid indices");
        }

        Pair<Integer, Integer> key = new Pair<>(startIndex, endIndex);
        List<Record> records;
        // Try to get the data from cache first
        if (cache.containsKey(key)) {
            hits++;
            records = cache.get(key);
        } else {
            misses++;

            String query = "SELECT * FROM Records WHERE index >= ? AND index <= ?";
            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setInt(1, startIndex);
            stmt.setInt(2, endIndex);

            ResultSet resultSet = stmt.executeQuery();
            records = new ArrayList<>();
            while (resultSet.next()) {
                // assuming Record has a constructor that accepts a ResultSet object
                records.add(new Record(resultSet)); 
            }
            cache.put(key, records);
        }

        if (filter != null) {
            records = records.stream()
                .filter(filter::apply)
                .collect(Collectors.toList());
        }

        return records;
    }

    public void insertRecord(Record record) throws SQLException {
        String query = "INSERT INTO Records VALUES (?)";
        PreparedStatement stmt = conn.prepareStatement(query);
        // assuming Record has a toSql() method that returns the correct SQL values string
        stmt.setString(1, record.toSql()); 

        stmt.executeUpdate();
    }

    public void updateRecord(Record record) throws SQLException {
        String query = "UPDATE Records SET field=? WHERE index=?";
        PreparedStatement stmt = conn.prepareStatement(query);
        // assuming Record has appropriate getters for each field
        stmt.setString(1, record.getField()); 
        stmt.setInt(2, record.getIndex());

        stmt.executeUpdate();
    }

    public void setFilter(RecordFilter filter) {
        this.filter = filter;
    }

    @Override
