#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>
#include <stdio.h>

typedef struct {
    char *name;
} Name;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity, count;
    Name **data;
} NamesList;

NamesList *names_list_create(size_t initialCapacity) {
    NamesList *list = malloc(sizeof(NamesList));
    if (list == NULL) {
        fprintf(stderr, "Out of memory: %s\n", strerror(errno));
        return NULL;
    }
    list->capacity = initialCapacity;
    list->count = 0;
    list->data = malloc(sizeof(Name *) * initialCapacity);
    if (list->data == NULL) {
        fprintf(stderr, "Out of memory: %s\n", strerror(errno));
        free(list);
        return NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void names_list_add(NamesList *list, Name *name) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        Name **newData = realloc(list->data, sizeof(Name *) * newCapacity);
        if (newData == NULL) {
            fprintf(stderr, "Out of memory: %s\n", strerror(errno));
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->data = newData;
        list->capacity = newCapacity;
    }
    list->data[list->count++] = name;
    pthread_mutex_unlock(&list->lock);
}

void names_list_free(NamesList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->data[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list->data);
    free(list);
}
```
