#include <stdio.h>
#include <sys/types.h>
#include <arpa/inet.h>
#include <netdb.h>

void resolve_hostname(const char *hostname, const struct in6_addr *preferred_interface) {
    // Create hints for getaddrinfo()
    struct addrinfo hints;
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;  // Use IPv4 and IPv6 address family
    hints.ai_socktype = SOCK_STREAM;

    struct addrinfo *servinfo;  // Will point to the results

    int rv = getaddrinfo(hostname, NULL, &hints, &servinfo);
    if (rv != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(rv));
        return;
    }

    // Traverse the linked list of addrinfos and print the IP address
    for (struct addrinfo *p = servinfo; p != NULL; p = p->ai_next) {
        char ip[INET6_ADDRSTRLEN];  // Space to hold the IPv6 string

        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        void *addr;

        if (p->ai_family == AF_INET) {  // IPv4
            addr = &(ipv4->sin_addr);
        } else {  // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ip, sizeof ip);
        printf("%s: %s\n", (p->ai_family == AF_INET) ? "IPv4" : "IPv6", ip);
    }

    freeaddrinfo(servinfo);  // Free the linked list
}
```
