int counter = 0;

void* incrementCounter(void *arg) {
    pthread_mutex_lock(&mutex); 
    int localCounter = counter;
    ++localCounter;
    sleep(1); // Simulate long operation
    counter = localCounter;
    printf("Incremented counter by thread ID: %lu to %d\n", pthread_self(), counter);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

