typedef struct LTE_DL_FRAME_TRANSPORT_CHANNEL_PDU {
    int TRANSPORT_CHANNEL_TAG;
    int RADIO_FRAME;
    // ... other members as required 
} LTE_DL_FRAME_TRANSPORT_CHANNEL_PDU;

typedef struct list {
    pthread_mutex_t lock;
    LTE_DL_FRAME_TRANSPORT_CHANNEL_PDU **data;
    int size;
    int capacity;
} List;

List *init_list(int initialCapacity) {
    List *list = malloc(sizeof(*list));
    if (list == NULL) return NULL;

    list->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;

    // Allocate initial memory 
    list->data = malloc(sizeof(LTE_DL_FRAME_TRANSPORT_CHANNEL_PDU *) * initialCapacity);
    if (list->data == NULL) {
        free(list);
        return NULL;
    }

    list->capacity = initialCapacity;
    list->size = 0;

    return list;
}

void add_to_list(List *list, LTE_DL_FRAME_TRANSPORT_CHANNEL_PDU *item) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        // Grow the array when it's full 
        list->capacity *= 2;
        LTE_DL_FRAME_TRANSPORT_CHANNEL_PDU **newData = realloc(list->data, sizeof(LTE_DL_FRAME_TRANSPORT_CHANNEL_PDU *) * list->capacity);

        if (newData == NULL) {
            // Error handling 
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->data = newData;
    }

    list->data[list->size] = item;
    list->size++;
    // Logging the addition 
    printf("Added element to the list\n");

    pthread_mutex_unlock(&list->lock);
}

LTE_DL_FRAME_TRANSPORT_CHANNEL_PDU *get_from_list(List *list, int index) {
    assert(index < list->size);

    pthread_mutex_lock(&list->lock);
    LTE_DL_FRAME_TRANSPORT_CHANNEL_PDU *item = list->data[index];
    pthread_mutex_unlock(&list->lock);

    return item;
}

void free_list(List *list) {
    for (int i = 0; i < list->size; ++i) {
        free(list->data[i]);
    }
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
``` 
This code provides a basic dynamic list that grows automatically when it's full. It also protects all operations with mutexes for thread safety and includes logging for each addition operation. Please note, this is only the very beginning of what you asked for; integrating error handling, performance profiling and compression library integration should be done in a more sophisticated way.
