However, I can guide you on how to write the `updateTiffAndDatabase` function in C. It will not be part of a full-fledged system but it is one part of it. 

```c
#include <tiffio.h>
#include <libpq-fe.h>
#include <stdio.h>

struct ImageInfo {
    int bitsPerSample;
    int samplePerPixel;
    int extraSamples;
};

void updateTiffAndDatabase(const char* filePath, const char* clinicId, const char* ipAddress) {
    TIFF* tif = TIFFOpen(filePath, "r");
    if (tif == NULL) {
        printf("Failed to open the TIFF file.\n");
        return;
    }

    struct ImageInfo imageInfo;
    // Parse and extract information about the image's bits per sample and sample per pixel. 
    // Handle cases where the image has 1, 2, 4, 8, or 16 bits per sample. 
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &imageInfo.bitsPerSample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &imageInfo.samplePerPixel);
    TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &imageInfo.extraSamples);

    // Connect to the PostgreSQL database.
    PGconn *conn = PQconnectdb("user=user dbname=test password=password hostaddr=127.0.0.1 port=5432");
    if (PQstatus(conn) != CONNECTION_OK) {
        printf("Connection to database failed: %s", PQerrorMessage(conn));
        PQfinish(conn);
        return;
    }

    // Update the specific table with a new status, last modified IP address, and last modified date for a given clinic ID.
    char sql[512];
    sprintf(sql, "UPDATE ClinicTable SET status='updated', ip_address='%s', last_modified=NOW() WHERE id=%s", ipAddress, clinicId);
    PGresult *res = PQexec(conn, sql);

    if (PQresultStatus(res) != PGRES_COMMAND_OK) {
        printf("UPDATE command failed: %s", PQerrorMessage(conn));
        PQclear(res);
        return;
    }

    // Close the database connection and TIFF file.
    PQclear(res);
    PQfinish(conn);
    TIFFClose(tif);
    printf("TIFF update and Database update successful!\n");
}
```
This code is a simple example and lacks error handling and security measures such as input validation, secure database connections, etc. It doesn't demonstrate the high performance or real-time aspect you mentioned in your requirements. 

