    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init(DynamicArray* da) {
    assert(da != NULL);

    da->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10); // Initial capacity
    if (da->array == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    da->size = 0;
    da->capacity = 10;

    pthread_mutex_init(&da->lock, NULL);
}

void push_back(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T value) {
    assert(da != NULL);

    pthread_mutex_lock(&da->lock);

    if (da->size == da->capacity) {
        // Reallocate array with double the capacity
        NFAPI_CRC_INDICATION_PDU_T* newArray = realloc(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * da->capacity * 2);

        if (newArray == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        da->array = newArray;
        da->capacity *= 2;
    }

    // Assign value to the array and increase size
    da->array[da->size++] = value;

    pthread_mutex_unlock(&da->lock);
}
