['Below is a simple C code snippet that uses the getaddrinfo() function of the standard library to perform DNS resolution. Please keep in mind that this code does not include error handling for all possible errors, but it should give you a good starting point. 

```c
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <errno.h>

// Limit concurrent queries to prevent resource exhaustion
#define MAX_QUERIES 100
int num_queries = 0;

// Function to perform DNS resolution for a given hostname
u_char* resolve(const char *node) {
    // Check if maximum number of queries has been reached
    if (num_queries >= MAX_QUERIES) {
        printf("Too many concurrent DNS queries.\n");
        return NULL;
    }

    num_queries++;

    struct addrinfo hints, *res = NULL;
    int errcode;
    char addrstr[100];
    void *ptr;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo(node, NULL, &hints, &res);
    if (errcode != 0) {
        perror("getaddrinfo");
        num_queries--;
        return NULL;
    }

    printf("Host: %s\n", node);
    while(res) {
        inet_ntop(res->ai_family, res->ai_addr->sa_data, addrstr, 100);

        switch (res->ai_family) {
            case AF_INET:
                ptr = &((struct sockaddr_in *)res->ai_addr)->sin_addr;
                break;
            case AF_INET6:
                ptr = &((struct sockaddr_in6 *)res->ai_addr)->sin6_addr;
                break;
        }

        inet_ntop(res->ai_family, ptr, addrstr, 100);
        printf("IPv%d address: %s (%s)\n", res->ai_family == PF_INET6 ? 6 : 4,
               addrstr, res->ai_canonname);

        res = res->ai_next;
    }

    freeaddrinfo(res);

    num_queries--;

    return (u_char *)addrstr;
}
```

Please note that the IP address is returned as a `const char*` for simplicity. In an actual implementation, it would be better to manage memory allocation and handle potential delays from external DNS servers explicitly. Also, real-world applications often need to support IPv6 as well. This code snippet only deals with IPv4 addresses.
']

