#include <regex.h>

typedef struct {
    char *path;
    int limit;
} FileInfo;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int bookCounts[172] = {0}; // assuming there are 172 books in the bible
char *books[172]; // initialize this with actual books names
regex_t regexes[172]; // initialize this with compiled regex for each book

void progressCallback(FileInfo *file) {
    printf("Processed %s\n", file->path);
}

void *processFile(void *arg) {
    FileInfo *file = (FileInfo *) arg;

    FILE *f = fopen(file->path, "r");
    if (!f) return NULL;

    char chunk[file->limit];
    int nread = 0;
    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);

    while ((nread = fread(chunk, 1, file->limit, f)) > 0) {
        MD5_Update(&ctx, chunk, nread);

        for (int i = 0; i < 172; i++) { // Assuming we have all the regex compiled and ready
            int match = regexec(&regexes[i], chunk, 0, NULL, 0);

            if (!match) {
                pthread_mutex_lock(&lock);
                ++bookCounts[i];
                pthread_mutex_unlock(&lock);
            }
        }

    }

    MD5_Final(md5, &ctx);
    char md5str[MD5_DIGEST_LENGTH*2+1];
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i)
        sprintf(&md5str[i*2], "%02x", (unsigned int) md5[i]);

    fclose(f);

    FILE *result = fopen("results.txt", "a"); // assuming results are stored in a file
    if (!result) return NULL;

    fprintf(result, "%s: %s\n", file->path, md5str);
    for (int i = 0; i < 172; i++) {
        fprintf(result, "Book: %s Count: %d\n", books[i], bookCounts[i]);
    }

    fclose(result);
    progressCallback(file);
    return NULL;
}

void process_and_check_directory(char *dirPath, int limit) {
    DIR *d = opendir(dirPath);
    if (!d) return;

    struct dirent *dir;
    while ((dir = readdir(d)) != NULL) {
        if (strcmp(dir->d_name, ".") == 0 || strcmp(dir->d_name, "..") == 0) continue;

        FileInfo *file = malloc(sizeof(FileInfo));
        file->path = dir->d_name;
        file->limit = limit;

        pthread_t thread;
        pthread_create(&thread, NULL, processFile, (void *) file);
    }

    closedir(d);
}
```
