import hashlib
import threading
from concurrent.futures import ThreadPoolExecutor, as_completed
from bz2 import BZ2File
from gzip import GzipFile

class FileProcessor:
    def __init__(self, max_memory):
        self.max_memory = max_memory
        self.book_names = ['Genesis', 'Exodus', 'Leviticus', 'Numbers', 
                           'Deuteronomy', 'Joshua', 'Judges', 'Ruth', 
                           '1 Samuel', '2 Samuel', '1 Kings', '2 Kings', 
                           'Isaiah', 'Jeremiah', 'Ezekiel', 'Hosea', 
                           'Joel', 'Amos', 'Obadiah', 'Jonah', 
                           'Micah', 'Nahum', 'Habakkuk', 'Zephaniah', 
                           'Haggai', 'Zechariah', 'Malachi']
        self.book_counts = {name: 0 for name in self.book_names}

    def process_and_hash_files(self, filepaths):
        hashes = {}
        executor = ThreadPoolExecutor(max_workers=len(filepaths))
        futures = [executor.submit(self._process_single_file, path) for path in filepaths]
        for future in as_completed(futures):
            path, result = future.result()
            hashes[path] = result

        # Aggregate book counts across all files
        aggregated_counts = {name: 0 for name in self.book_names}
        for file_results in hashes.values():
            for book, count in file_results['book_counts'].items():
                aggregated_counts[book] += count

        return {'hashes': hashes, 'aggregated_counts': aggregated_counts}

    def _process_single_file(self, path):
        # Error handling for invalid file paths or access issues
        try:
            if os.path.splitext(path)[1] == '.bz2':
                with BZ2File(path) as f:
                    return self._process_compressed_file(f, path)
            elif os.path.splitext(path)[1] in ('.gz', '.gzip'):
                with GzipFile(path) as f:
                    return self._process_compressed_file(f, path)
            else:
                with open(path, 'rb') as f:
                    return self._process_file(f, path)
        except Exception as e:
            print(f"Error processing file {path}: {e}")

    def _process_compressed_file(self, f, path):
        hasher = hashlib.md5()
        while True:
            chunk = f.read1(self.max_memory)  # read in chunks of max_memory size
            if not chunk:
                break
            hasher.update(chunk)
        return path, {'md5': hasher.hexdigest(), 'book_counts': self._analyze_file_content(f)}

    def _process_file(self, f, path):
        # implement the same way as _process_compressed_file
        pass

    def _analyze_file_content(self, file):
        book_counts = self.book_counts.copy()
        for line in file:
            for name in self.book_names:
                pattern = r'\b' + re.escape(name) + r'\b'  # regex pattern to match whole word only
                matches = re.findall(pattern, str(line), flags=re.IGNORECASE)
                book_counts[name] += len(matches)
        return book_counts
```

