['Here is a skeleton code for your requirement written with Java 8 CompletableFuture, Guava's RateLimiter to manage backpressure, and Jedis (Redis client) for persisting hash in an external data store Redis. Also used a ConcurrentHashMap to track the total number of hash computations performed since service startup:

```java
import redis.clients.jedis.Jedis;
import java.util.*;
import java.security.*;
import com.google.common.util.concurrent.*;
import java.nio.charset.*;
import java.math.BigInteger;
import java.util.logging.*;
import javax.xml.bind.DatatypeConverter;

public class HashService {
    private static final Logger logger = Logger.getLogger(HashService.class.getName());
    private RateLimiter rateLimiter = RateLimiter.create(10_000);
    private Jedis jedis = new Jedis("localhost"); // replace with your Redis server IP and port
    private ConcurrentHashMap<String, String> hashMap = new ConcurrentHashMap<>();
    private int totalComputations = 0;

    public void processHashes(List<String> strings) {
        CompletableFuture.supplyAsync(() -> 
            strings.parallelStream().map(this::computeAndStoreMD5).count()
        ).thenAccept(total -> totalComputations += total);
    }

    private String computeAndStoreMD5(String str){
        if (!rateLimiter.tryAcquire()) {
            logger.severe("Rate Limit Exceeded");
            return "";
        }
        try{
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(str.getBytes(StandardCharsets.UTF_8));
            String hash = DatatypeConverter.printHexBinary(digest);
            jedis.set(hash, str); // set the string in Redis with MD5 as key for recovery/reliability 
            return hash;
        } catch (NoSuchAlgorithmException e){
            logger.severe("Unsupported Algorithm: " + e);
        }
        return "";
    }

    public String getHash(String str) {
        return hashMap.getOrDefault(str, "Not Found");
    }
}
``` 
