int main(int argc, char** argv) {
    if (argc != 6) {
        printf("Usage: %s input_dir output_file hostname username isFast\n", argv[0]);
        return 1;
    }

    const char* input_dir = argv[1];
    const char* output_file = argv[2];
    const char* hostname = argv[3];
    const char* username = argv[4];
    int isFast = atoi(argv[5]);

    ssh_session session;
    int rc;
    int port = 22;

    session = ssh_new();
    if (session == NULL) {
        return 1;
    }

    ssh_options_set(session, SSH_OPTIONS_HOST, hostname);
    ssh_options_set(session, SSH_OPTIONS_USER, username);
    ssh_options_set(session, SSH_OPTIONS_PORT, &port);

    rc = ssh_connect(session);
    if (rc != SSH_OK) {
        fprintf(stderr, "Error connecting to %s: %s\n", hostname, ssh_get_error(session));
        return 1;
    }

    // Authenticate using public key
    rc = ssh_userauth_publickey_auto(session, NULL, NULL);
    if (rc != SSH_AUTH_SUCCESS) {
        fprintf(stderr, "Error authenticating with public key: %s\n", ssh_get_error(session));
        return 1;
    }

    // Compress the directory tree using tar command
    char tarCommand[500];
    if (isFast) {
        sprintf(tarCommand, "tar -cf %s -C %s .", output_file, input_dir);
    } else {
        sprintf(tarCommand, "tar -cJf %s -C %s .", output_file, input_dir);
    }

    FILE* pipe = popen(tarCommand, "r");
    if (pipe == NULL) {
        fprintf(stderr, "Error opening the pipe.\n");
        return 1;
    }

    ssh_scp scp;
    int access_type = O_WRONLY | O_CREAT | O_TRUNC;
    mode_t permissions = S_IRUSR | S_IWUSR | S_IXUSR;
    scp = ssh_scp_new(session, access_type, output_file);

    if (scp == NULL) {
        fprintf(stderr, "Error creating new SCP session: %s\n", ssh_get_error(session));
        return 1;
    }

    rc = ssh_scp_init(scp);
    if (rc != SSH_OK) {
        fprintf(stderr, "Error initializing SCP session: %s\n", ssh_get_error(session));
        return 1;
    }

    char buffer[4096];
    size_t readBytes;
    while ((readBytes = fread(buffer, sizeof(char), sizeof(buffer) - 1, pipe)) > 0) {
        ssh_scp_push_data(scp, buffer, readBytes);
    }

    pclose(pipe);
    ssh_scp_close(scp);
    ssh_scp_free(scp);
    ssh_disconnect(session);
    ssh_finalize();

    return 0;
}
```
In this code, the tar command is used to compress the directory tree. The `-cf` options are used for a faster compression but not as compressed as `-cJf` which uses xz compression. The SSH connection is established using public key authentication. Once connected, the SCP protocol is used to transfer the compressed archive file to the remote server.

Please note that this code requires LibSSH library and tar command installed on your machine. Also, you need to have a valid public-private key pair setup for public key authentication.
