import org.apache.commons.lang3.StringUtils;
import org.json.JSONObject;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class OAuth2TokenValidatorService {

    private final ExecutorService executor = Executors.newFixedThreadPool(10); // Adjust the thread pool size based on your system resources and requirements
    private final Logger logger = Logger.getLogger(OAuth2TokenValidatorService.class.getName()); 
    private long totalChecks = 0;
    private boolean isLoggingEnabled = true; // Default logging enabled, can be toggled dynamically

    public Map<String, Boolean> validateTokens(List<String> tokenJsonStrings) throws InterruptedException, ExecutionException {
        CountDownLatch latch = new CountDownLatch(tokenJsonStrings.size());
        List<Callable<Map.Entry<String,Boolean>>> tasks = new ArrayList<>();

        for (String jsonString : tokenJsonStrings) {
            Callable<Map.Entry<String,Boolean>> task = () -> validateToken(jsonString);
            tasks.add(task);
            totalChecks++; // Increment total checks count per each submitted task
        }

        List<Future<Map.Entry<String, Boolean>>> futures = executor.invokeAll(tasks);
        latch.await();

        Map<String, Boolean> results = new HashMap<>();
        for (Future<Map.Entry<String, Boolean>> future : futures) {
            Map.Entry<String, Boolean> entry = future.get(); // May throw ExecutionException if the task execution throws an exception
            results.put(entry.getKey(), entry.getValue());
        }

        return results;
    }

    private Map.Entry<String,Boolean> validateToken(String jsonString) {
        JSONObject tokenJson = new JSONObject(jsonString);
        boolean isValid = true;
        try {
            if (!tokenJson.has("access_token") || StringUtils.isBlank(tokenJson.getString("access_token"))) {
                isValid = false;
            } else if (!tokenJson.has("expires_in") || tokenJson.getInt("expires_in") <= 0) {
                isValid = false;
            } else if (!tokenJson.has("token_type") || !"Bearer".equals(tokenJson.getString("token_type"))) {
                isValid = false;
            } else if (tokenJson.has("refresh_token") && StringUtils.isBlank(tokenJson.getString("refresh_token"))) {
                isValid = false;
            }
        } catch (Exception e) {
            // Handles potential deserialization attacks by catching exceptions thrown during JSON parsing
            if (isLoggingEnabled) {
                logger.log(Level.WARNING, "Error while validating token: " + jsonString, e);
            } else {
                System.err.println("Error while validating token: " + jsonString + ". Enable logging for more details.");
            }
            isValid = false;
        }

        return new AbstractMap.SimpleEntry<>(jsonString, isValid);
    }

    public long getTotalChecks() {
        return totalChecks;
    }

    public void toggleLogging() {
        isLoggingEnabled = !isLoggingEnabled;
    }

    // Dynamically adjust the logging level without requiring application restarts
    public void setLogLevel(String logLevel) {
        logger.setLevel(Level.parse(logLevel));
    }
}
```
To use the service, you would create a new instance of OAuth2TokenValidatorService and call validateTokens() with a list of JSON token strings. The method will return a map where each key is an input JSON string and each value indicates whether the corresponding token was valid or not. 

The logging level can be adjusted by calling setLogLevel().
Note: This code assumes that you're using Apache Commons Lang3 for StringUtils and JSON in Java (org.json). You would need to include these dependencies in your project if they are not already available.
