    NfaPiCrcIndicationPdu crc_indication;
} NfaPiPdu;

NfaPiPdu* initializeAndPopulate(int n, pthread_mutex_t* mutex) {
    NfaPiPdu* pduArray = malloc(n * sizeof(NfaPiPdu));
    if (!pduArray) {
        perror("Failed to allocate memory");
