        NfaPiPdu pdu = {tag, crcIndication};
        memcpy(&pduArray[i], &pdu, sizeof(NfaPiPdu));
        pthread_mutex_unlock(mutex);
    }
    return pduArray;
}

void configureSequenceNumber(const char* configFilePath, int* sequenceNumber) {
    FILE* file = fopen(configFilePath, "r");
    if (!file) {
        perror("Failed to open configuration file");
        exit(EXIT_FAILURE);
