    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%d", sequenceNumber) == 1) {
            break;
        }
    }
    fclose(file);
}

void readBinaryFileAndTransform(const char* inputPath, const char* outputPath) {
    int fd = open(inputPath, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open binary file");
        exit(EXIT_FAILURE);
    }

    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("Failed to get file status");
        exit(EXIT_FAILURE);
    }

    NfaPiPdu* pduArray = mmap(NULL, sb.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (pduArray == MAP_FAILED) {
        perror("Failed to map file into memory");
        exit(EXIT_FAILURE);
    }

    FILE* outputFile = fopen(outputPath, "wb");
    if (!outputFile) {
        perror("Failed to open output file");
        exit(EXIT_FAILURE);
    }

    // Assume a simple transformation rule that doubles the rnti of each PDU
    for (size_t i = 0; i < sb.st_size / sizeof(NfaPiPdu); ++i) {
        pduArray[i].rx_ue_information.rnti *= 2;
        fwrite(&pduArray[i], sizeof(NfaPiPdu), 1, outputFile);
    }

    // Generate a checksum at the end of the file
    int checksum = 0;
    for (size_t i = 0; i < sb.st_size / sizeof(NfaPiPdu); ++i) {
        checksum += pduArray[i].rx_ue_information.rnti;
    }
    fwrite(&checksum, sizeof(int), 1, outputFile);

    fclose(outputFile);
}
