    if (errcode != 0) {
        perror("Failed to resolve hostname");
        return;
    }

    printf("Host: %s\n", hostname);
    while (res) {
        inet_ntop(res->ai_family, res->ai_addr->sa_data, addrstr, 100);

        switch (res->ai_family) {
            case AF_INET: // IPv4
                ptr = &((struct sockaddr_in *) res->ai_addr)->sin_addr;
                break;
            case AF_INET6: // IPv6
                ptr = &((struct sockaddr_in6 *) res->ai_addr)->sin6_addr;
                break;
            default:
                printf("Unknown address family\n");
                return;
        }

        inet_ntop(res->ai_family, ptr, addrstr, 100);
        printf("\tIPv%d address: %s (%s)\n", res->ai_family == PF_INET6 ? 6 : 4,
            addrstr, res->ai_canonname);
        res = res->ai_next;
    }

    freeaddrinfo(res);
}

int main() {
    resolve_hostname("www.example.com");
    return 0;
}
```
This code snippet is a simple hostname resolution function which uses the `getaddrinfo` function from netdb.h library in C, which resolves a given hostname into its IP address using a configurable DNS backend (OS's default configured DNS server by default). It also handles both IPv4 and IPv6 addresses.
