typedef struct {
    int transaction_id;
    float value;
    char status;
} TransactionRecord;

typedef struct {
    TransactionRecord records[];
} TransactionLog;

TransactionLog* loadTransactionLog(const char* logFilePath, size_t maxEntries, pthread_mutex_t* mutex) {
    TransactionLog* logArray = mmap(NULL, maxEntries * sizeof(TransactionRecord), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYX, -1, 0);
    if (!logArray) {
        perror("Failed to map memory");
        exit(EXIT_FAILURE);
    }

    FILE* file = fopen(logFilePath, "r");
    if (!file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);

    if (fileSize > maxEntries * sizeof(TransactionRecord)) {
        fclose(file);
        munmap(logArray, maxEntries * sizeof(TransactionRecord));
        perror("File size exceeds maximum allowed entries");
        exit(EXIT_FAILURE);
    }

    fread(logArray, 1, fileSize, file);
    fclose(file);

    return logArray;
}

void analyzeTransactionLog(TransactionLog* logArray, size_t entries, pthread_mutex_t* mutex) {
    for (size_t i = 0; i < entries; ++i) {
        pthread_mutex_lock(mutex);
        if (logArray[i].status == 'F' && logArray[i].value > 1000.0) {
            printf("Flagged transaction detected: ID %d, Value %.2f\n", logArray[i].transaction_id, logArray[i].value);
        }
        pthread_mutex_unlock(mutex);
    }
}

