['Here is a python solution using multiprocessing for concurrent hashing, logging for error reporting, and asyncio for asynchronous file reading. Please note that this function requires Python 3.5 or later due to usage of async/await syntax. Also, it uses an external logging service which must be implemented by the user.

```python
import os
import hashlib
from concurrent.futures import ThreadPoolExecutor
import asyncio

# Assuming that you have a LogService class with log method for logging errors
log_service = LogService()  # Replace it with your real logger implementation

def calculate_md5(filepath, expected):
    hash_md5 = hashlib.md5()
    try:
        with open(filepath, "rb") as f:
            for chunk in iter(lambda: f.read(8192), b""):
                hash_md5.update(chunk)
    except Exception as e:
        log_service.log("Error while reading file {}: {}".format(filepath, str(e)))
        return None, False

    calculated = hash_md5.hexdigest()
    if expected != calculated:
        log_service.log("Hash mismatch for file {}. Expected {}, got {}.".format(filepath, expected, calculated))
        return (calculated, False)

    return (calculated, True)

async def process_files(loop, files):
    results = {}
    with ThreadPoolExecutor(max_workers=10) as executor:
        for filepath, expected in files.items():
            # Check if the file exists and is not locked
            while True:
                try:
                    size = os.stat(filepath).st_size
                    break
                except FileNotFoundError:
                    log_service.log("File {} does not exist.".format(filepath))
                    await asyncio.sleep(1)  # Wait for a bit before retrying
                except OSError as e:
                    if "Device or resource busy" in str(e):
                        await asyncio.sleep(1)  # File is locked, wait and retry
                    else:
                        raise

            # Check if file size is more than 1GB
            if size > 1073741824:  
                futures = []
                with open(filepath, 'rb') as f:
                    for _ in range(size // (1024 * 1024 * 512)):  # 512MB segments
                        chunk = f.read(1024 * 1024 * 512)
                        future = loop.run_in_executor(executor, calculate_md5, (filepath, expected), chunk)
                        futures.append(future)
                for response in await asyncio.gather(*futures):
                    results[filepath] = response
            else:
                future = loop.run_in_executor(executor, calculate_md5, (filepath, expected))
                results[filepath] = await future
    return results

def main():
    files = {"/path/to/your/files": "expected-hash", "/another/path": "another-hash"}  # Replace with your real file paths and hashes
    loop = asyncio.get_event_loop()
    result = loop.run_until_complete(process_files(loop, files))
    print(result)

if __name__ == "__main__":
    main()
```
This code uses a custom thread pool to handle multiple files concurrently and memory-efficient chunked reading for large files. It also logs errors with an external logging service and retries in case of temporary file issues. This function should work well under most scenarios, but for extreme cases or specific performance requirements further optimization may be needed.
