#include <sys/stat.h>
#include <fcntl.h>

void usage() {
    printf("Usage: ./a.out -i input_file [-o output_file] [--manpage]\n");
}

unsigned char* computeMD5(const char* file, long *size) {
    unsigned char c[MD5_DIGEST_LENGTH];
    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];

    MD5_Init(&mdContext);
    int in = open(file, O_RDONLY);
    if (in == -1) {
        perror("Error while opening the file.\n");
        return NULL;
    }

    *size = 0L;
    for (;;) {
        bytes = read(in, data, 1024);
        if (bytes <= 0) break;

        MD5_Update(&mdContext, data, bytes);
        (*size) += bytes;
    }

    close(in);
    unsigned char *digest = malloc(MD5_DIGEST_LENGTH);
    MD5_Final(digest, &mdContext);

    return digest;
}

int main(int argc, char** argv) {
    if (argc < 3) {  // at least input and output file is expected.
        usage();
        return -1;
    }

    int inIndex = -1, outIndex = -1;
    for (int i = 0; i < argc; ++i) {
        if (strcmp(argv[i], "-i") == 0) 
            inIndex = i + 1;
        else if (strcmp(argv[i], "-o") == 0)
            outIndex = i + 1;
    }

    if (inIndex < 0 || inIndex >= argc) {
        usage();
        return -1;
    }

    long size = 0L;
    unsigned char *digest = computeMD5(argv[inIndex], &size);
    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i) 
        printf("%02x", digest[i]);

    printf("\n");
    free(digest);

    return 0;
}
