import java.security.MessageDigest;
import java.util.Map;
import java.util.HashMap;
import java.nio.charset.StandardCharsets;
import java.math.BigInteger;

public class MyClass {
    private static BigInteger hashComputations = BigInteger.ZERO;

    public synchronized static String md5Hasher(String input) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");

        byte[] digest = md.digest(input.getBytes(StandardCharsets.UTF_8));
        String hash = new BigInteger(1, digest).toString(16);

        hashComputations = hashComputations.add(BigInteger.ONE);  // Increment counter

        return hash;
    }

    public static Map<String, String> md5Hasher(List<String> inputs) throws Exception {
        Map<String, String> results = new HashMap<>();

        for (String input : inputs) {
            results.put(input, md5Hasher(input));
        }

        return results;
    }
}
