private static final Semaphore SEMAPHORE = new Semaphore(10000, true); // limit to 10000 concurrent threads
private long hashCount = 0;

public Map<String, String> md5Hasher(List<String> inputs) throws InterruptedException {
    SEMAPHORE.acquire(); // acquire permit
    try{
        for (String input : inputs){
            incrementHashCountAndGetMD5(input);
        }
    } finally {
        SEMAPHORE.release();  // release permit
    }
