['```python
import json
import csv
import codecs
import logging
from multiprocessing import Pool

logging.basicConfig(filename='processing_logs.log', level=logging.INFO)

def transform_line(config, line):
    try:
        return config['transform'](line)
    except Exception as e:
        logging.error("Transformation error at line : {}".format(line), exc_info=True)
        return None

def process_large_text_file(filename, config, output_format):
    transformed_lines = []
    interrupted = False
    last_completed_line = 0

    with open(filename, 'r', encoding=config.get('encoding','utf-8'), errors='replace') as f:
        lines = f.readlines()

        if config.get('resume'):
            last_completed_line = int(open("last_completed_line", "r").read())

    with Pool(config.get('parallel', 1)) as p:
        transformed_chunks = p.starmap(transform_line, [(config, line) for i, line in enumerate(lines[last_completed_line:]) if i % config['resume'] == 0 or not config['resume'])

    for chunk in transformed_chunks:
        for line in chunk:
            transformed_lines.append(line)

    with open("last_completed_line", "w") as f:
        f.write(str(len(transformed_lines)))

    if output_format == 'json':
        json.dump(transformed_lines, codecs.open('output.json', 'w', encoding='utf-8'), ensure_ascii=False)
    elif output_format == 'csv':
        csv.writer(open("output.csv", "w")).writerows(transformed_lines)
    else:  # plain text
        with open('output.txt', 'w') as f:
            for line in transformed_lines:
                f.write("%s\n" % line)

    return transformed_lines, logging.info("Processing completed")
```
This code uses Python's multiprocessing module to handle parallel processing. The transform_line function is applied to each line using a Pool of worker processes. After the transformation process is complete, the results are written to an output file in the specified format (either JSON, CSV, or plain text). If any errors occur during the transformation process, they are logged and the error message is printed to the console.
