import hashlib
import os
from concurrent.futures import ThreadPoolExecutor

class HashManager:
    def __init__(self):
        self._algorithm = 'md5'  # Default algorithm

    def switch_hash(self, algorithm):
        if algorithm in ['md5', 'sha256']:
            self._algorithm = algorithm

    def compute_hash(self, filepath):
        hash_function = getattr(hashlib, self._algorithm)()
        chunk_size = 8192  # Define an initial chunk size.

        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(chunk_size), b''):
                hash_function.update(chunk)

        return hash_function.hexdigest()

    def compute_hashes(self, filepaths, workers=os.cpu_count()):
        with ThreadPoolExecutor(max_workers=workers) as executor:
            futures = {executor.submit(self.compute_hash, fp): fp for fp in filepaths}

            for future in concurrent.futures.as_completed(futures):
                yield futures[future], future.result()  # Yields (filepath, hash) tuple as it completes.
```
This class manages the hashing process using a ThreadPoolExecutor to compute multiple files simultaneously while keeping memory efficiency and cache efficiency high. It uses Python's built-in `hashlib` for MD5 and SHA256 hashing algorithms, which are highly optimized in C. This code does not include error handling, logging, or resource monitoring as these would be complex and application specific.
