["Here's an example implementation in C using POSIX Threads (pthreads). It uses a linked list structure with pthread_mutex locks for synchronization and efficient session storage in memory. Sessions are evicted when they have not been active for the specified duration, which you can adjust in `SESSION_EXPIRY_TIME` constant.

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define SESSION_EXPIRY_TIME 60 // In seconds

typedef struct UserSession {
    int sessionId;
    time_t lastActiveTimestamp;
    char connectionStatus[256]; // Adjust according to your requirements
    struct UserSession *next;
} UserSession;

UserSession* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addOrUpdateSession(int sessionId, char* connectionStatus) {
    pthread_mutex_lock(&lock);

    UserSession *currentNode = head;
    while (currentNode != NULL) {
        if (currentNode->sessionId == sessionId) {
            currentNode->lastActiveTimestamp = time(NULL); // Update timestamp
            strncpy(currentNode->connectionStatus, connectionStatus, sizeof(currentNode->connectionStatus)); // Update status
            pthread_mutex_unlock(&lock);
            return;
        }
        currentNode = currentNode->next;
    }

    UserSession *newUserSession = (UserSession*)malloc(sizeof(UserSession));
    newUserSession->sessionId = sessionId;
    newUserSession->lastActiveTimestamp = time(NULL);
    strncpy(newUserSession->connectionStatus, connectionStatus, sizeof(newUserSession->connectionStatus));
    newUserSession->next = head;

    head = newUserSession; // New sessions are added at the head of the list

    pthread_mutex_unlock(&lock);
}

time_t getLastActiveTimestamp(int sessionId) {
    pthread_mutex_lock(&lock);

    UserSession *currentNode = head;
    while (currentNode != NULL) {
        if (currentNode->sessionId == sessionId) {
            time_t timestamp = currentNode->lastActiveTimestamp;
            pthread_mutex_unlock(&lock);
            return timestamp;
        }
        currentNode = currentNode->next;
    }

    pthread_mutex_unlock(&lock);
    return -1; // Session not found
}

void evictInactiveSessions() {
    pthread_mutex_lock(&lock);

    UserSession *currentNode = head, *prevNode = NULL;
    time_t currentTime = time(NULL);
    while (currentNode != NULL) {
        if ((int)(difftime(currentTime, currentNode->lastActiveTimestamp)) > SESSION_EXPIRY_TIME) { // Session expired
            if (prevNode == NULL) { // This means the head node needs to be removed
                UserSession *temp = head;
                head = head->next;
                free(temp);
                currentNode = head;
            } else {
                prevNode->next = currentNode->next;
                free(currentNode);
                currentNode = prevNode->next;
            }
        } else { // Move to the next node
            prevNode = currentNode;
            currentNode = currentNode->next;
        }
    }

    pthread_mutex_unlock(&lock);
}
```
Note: This is a simplified example and lacks many important aspects like thread safety, memory management or error handling. You should adapt this to your specific needs.
