['Here is an example implementation in C using pthreads for threads synchronization and glib for hash map:
```c
#include <glib.h>
#include <pthread.h>
#include <time.h>

typedef struct UserSession {
    int sessionId;
    time_t lastActiveTimestamp;
    char* connectionStatus; // or whatever type you want for this field
} UserSession;

// Dynamic collection of sessions
GHashTable *sessions = NULL;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
time_t inactiveThreshold = 3600; // Default inactivity threshold is 1 hour

// Initialize session collection
void initSessions() {
    if (sessions == NULL) {
        sessions = g_hash_table_new(g_direct_hash, g_direct_equal);
    }
}

// Add new user session
void addSession(UserSession* session) {
    pthread_rwlock_wrlock(&rwlock);
    g_hash_table_insert(sessions, GINT_TO_POINTER(session->sessionId), session);
    pthread_rwlock_unlock(&rwlock);
}

// Update existing user session
void updateSession(UserSession* session) {
    pthread_rwlock_wrlock(&rwlock);
    gpointer oldValue = NULL;
    if (g_hash_table_lookup_extended(sessions, GINT_TO_POINTER(session->sessionId), NULL, &oldValue)) {
        free(oldValue); // Assuming UserSession is allocated dynamically and needs to be freed.
    }
    g_hash_table_insert(sessions, GINT_TO_POINTER(session->sessionId), session);
    pthread_rwlock_unlock(&rwlock);
}

// Get last active timestamp of a user session
time_t getLastActiveTimestamp(int sessionId) {
    time_t result = 0;
    pthread_rwlock_rdlock(&rwlock);
    UserSession* session = g_hash_table_lookup(sessions, GINT_TO_POINTER(sessionId));
    if (session != NULL) {
        result = session->lastActiveTimestamp;
    }
    pthread_rwlock_unlock(&rwlock);
    return result;
}

// Set eviction policy and inactivity threshold
void setInactiveThreshold(time_t newThreshold) {
    inactiveThreshold = newThreshold;
}

// Evict sessions that have been inactive for more than the threshold
void evictSessions() {
    time_t now = time(NULL);
    pthread_rwlock_wrlock(&rwlock);
    GHashTableIter iter;
    gpointer key, value;
    g_hash_table_iter_init (&iter, sessions);
    while (g_hash_table_iter_next (&iter, &key, &value)) {
        UserSession* session = (UserSession*)value;
        if (now - session->lastActiveTimestamp > inactiveThreshold) {
            g_hash_table_remove(sessions, key);
            free(session); // Assuming UserSession is allocated dynamically and needs to be freed.
        }
    }
    pthread_rwlock_unlock(&rwlock);
}
``` 
Please note that this code does not include the actual session management logic which you mentioned in your task, such as updating `connectionStatus` based on network events or handling of large numbers of sessions. You would need to implement these parts according to your specific requirements and constraints. This is just a basic skeleton for the required functionality.
