        $data = json_decode((string)$response->getBody(), true);

        // store access token in session variable
        $_SESSION['access_token'] = $data['access_token']; 
    } catch (RequestException $e) {
        error_log($e->getMessage()); // log the error message
        return false;
    }

    return true;
}

function getUserInfo(Client $http, string $userUrl) {
    $accessToken = $_SESSION['access_token']; 

    try {
        $cachedResponse = $cache->get('user_info'); // check if user info is cached

        if ($cachedResponse === null) { // if not, fetch from API
            $response = $http->request('GET', $userUrl, [
                'headers' => [
                    'Authorization' => "Bearer $accessToken"
                ]
            ]);

            $data = json_decode((string)$response->getBody(), true); 
            $cache->set('user_info', $data, 3600); // cache the response for an hour
        } else {
            $data = $cachedResponse;
        }
    } catch (RequestException $e) {
        error_log($e->getMessage());
        return false;
    }

    return $data;
}

