function processTransaction($apiKey, $orderId, $amount, $currency) {
    $retries = 3;
    $rateLimitDelay = false;

    // Validate inputs
    if(!is_numeric($amount)) {
        throw new Exception("Invalid amount");
    }

    if(!in_array($currency, ['USD', 'EUR'])) { // replace with valid currencies
        throw new Exception("Invalid currency");
    }

    $report = [];

    while($retries > 0) {
        $response = $this->sendRequestToGateway($apiKey, $orderId, $amount, $currency);

        if(!$response['success']) {
            $retries--;
            if($response['code'] == 429 && !$rateLimitDelay) {
                sleep(60); // delay for 1 minute (adjust as needed)
                $rateLimitDelay = true;
            }
        } else {
            $report = $this->generateReport($orderId, $response['data']);
            break;
        }
    }

    if(!$retries) {
        throw new Exception("Failed to process transaction after 3 attempts");
    }

    return $report;
}
