Node *createNewNode(int tag, int length, char* data) {
    Node *newNode = (Node *) malloc(sizeof(Node));
    if (!newNode) {
        // Handle memory allocation failure
        logError("Failed to allocate memory for a new node.");
        return NULL;
    }

