```python
from flask import Flask, request
from celery import Celery
from Crypto.Hash import SHA256
import subprocess

app = Flask(__name__)
celery_app = Celery('tasks', broker='pyamqp://guest@localhost//')
total_hash = 0

class HTTPRequest:
    def __init__(self, type, size):
        self.type = type
        self.size = size

http_requests = [HTTPRequest('GET', 1024), HTTPRequest('POST', 512)]

@celery_app.task
def compute_hash(data):
    global total_hash
    hash = SHA256.new()
    hash.update(data)
    total_hash += 1
    return hash.hexdigest()

@app.route('/compute-hashes', methods=['POST'])
def compute_all_hashes():
    results = []
    for http_request in http_requests:
        result = compute_hash.delay(http_request.type)
        results.append({'data': http_request.type, 'hash': result.get()})

    return {'results': results}

@app.route('/grep', methods=['POST'])
def execute_grep():
    data = request.json
    command = f"grep {data['pattern']} {data['file']}"
    try:
        output = subprocess.check_output(command, shell=True)
        return {'success': True, 'output': output.decode('utf-8')}
    except subprocess.CalledProcessError as e:
        return {'success': False, 'error': str(e)}

@app.route('/hash-count', methods=['GET'])
def get_total_hashes():
    return {'total': total_hash}
```

