import sys
from queue import PriorityQueue

class PQueue(PriorityQueue):
    def __init__(self):
        PriorityQueue.__init__(self)
        self.counter = 0

    def put(self, item, priority):
        PriorityQueue.put(self, (priority, self.counter, item))
        self.counter += 1

    def get(self, *args, **kwargs):
        _, _, item = PriorityQueue.get(self, *args, **kwargs)
        return item

def sort_lines(file_path, priority_func):
    q = PQueue()
    with open(file_path, 'r') as file:
        for line in file:
            try: 
                seq_num = int(line.split(':')[0]) # parse sequence number from each line
                priority = priority_func(seq_num)
                q.put(line, priority)
            except ValueError:
                print("Invalid sequence number found in the configuration file")  # handles non-integer values by ignoring them.
    while not q.empty():
        print(q.get())
```
