import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed

def calculate_md5(file):
    md5 = hashlib.md5()

    with open(file,'rb') as f: 
        for chunk in iter(lambda: f.read(4096), b""): 
            md5.update(chunk)

    return file, md5.hexdigest()

def calculate_multiple_md5s(files):
    with ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
        future_to_file = {executor.submit(calculate_md5, file): file for file in files}

        for future in as_completed(future_to_file):
            file = future_to_file[future]

            try:
                print(f"File: {file}, MD5: {future.result()[1]}")
            except Exception as exc:
                print('%r generated an exception: %s' % (file, exc))
```

And the C function for calculating MD5 could be something like this:

```c
#include <stdio.h>
#include <openssl/md5.h>

int calculate_md5(const char *filename, unsigned char md5sum[MD5_DIGEST_LENGTH]) {
    FILE *inFile = fopen (filename, "rb");

    if (inFile == NULL) {
        return -1; // Error opening file
    }

    MD5_CTX mdContext;
    unsigned char data[1024];

    int bytes;

    MD5_Init (&mdContext);

    while ((bytes = fread (data, 1, 1024, inFile)) != 0) {
        MD5_Update (&mdContext, data, bytes);
    }

    MD5_Final (md5sum, &mdContext);

    fclose (inFile);

    return 0; // Success
}
```

