public class TemperatureReading
{
    public string SensorId { get; set; }
    public DateTime TimeStamp { get; set; }
    public double TempValue { get; set; }
}

public class TemperatureReadingsManager
{
    private List<TemperatureReading> _readings = new List<TemperatureReading>();

    // Add a new reading to the collection
    public void AddReading(string sensorId, DateTime timeStamp, double tempValue)
    {
        var reading = new TemperatureReading()
        {
            SensorId = sensorId,
            TimeStamp = timeStamp,
            TempValue = tempValue
        };

        _readings.Add(reading);
    }

    // Retrieve a reading by sensor ID
    public List<TemperatureReading> GetReadingsBySensorId(string sensorId)
    {
        return _readings.Where(r => r.SensorId == sensorId).ToList();
    }

    // Calculate the average temperature for a given time period
    public double CalculateAverageTemperature(DateTime startTime, DateTime endTime)
    {
        var filteredReadings = _readings.Where(r => r.TimeStamp >= startTime && r.TimeStamp <= endTime);

        if (!filteredReadings.Any()) return 0;

        return filteredReadings.Average(r => r.TempValue);
    }

    // Filter readings based on a specified temperature threshold
    public List<TemperatureReading> FilterReadingsByThreshold(double tempThreshold)
    {
        return _readings.Where(r => r.TempValue > tempThreshold).ToList();
    }

    // Override ToString method to display the number of readings and the average temperature
    public override string ToString()
    {
        if (!_readings.Any()) return "No readings available.";

        var avgTemp = _readings.Average(r => r.TempValue);

        return $"Total readings: {_readings.Count}, Average temperature: {avgTemp}";
    }
}
```
