['Here is an implementation using Python with the `hashlib` library for SHA256 hashing, `concurrent.futures` to manage threads, and `io` for reading in chunks of a specified size:

```python
import hashlib
import concurrent.futures
from io import BytesIO

def process_file(filename, block_size=65536):
    file_hash = hashlib.sha256()
    try:
        with open(filename, 'rb') as f:
            buf = f.read(block_size)
            while len(buf) > 0:
                file_hash.update(buf)
                buf = f.read(block_size)
    except Exception as e:
        return {'filename': filename, 'error': str(e)}

    return {'filename': filename, 'hash': file_hash.hexdigest()}

def process_files(filenames, checksums=None, block_size=65536, num_threads=1):
    if checksums and len(checksums) != len(filenames):
        raise ValueError("The length of 'checksums' must match the number of files.")

    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=num_threads) as executor:
        future_to_filename = {executor.submit(process_file, filename, block_size): filename for filename in filenames}

        for future in concurrent.futures.as_completed(future_to_filename):
            result = future.result()

            if 'error' not in result:  # File was successfully read and hashed
                filename = result['filename']

                verification_result = None
                if checksums:
                    index = filenames.index(filename)
                    provided_checksum = checksums[index]
                    calculated_checksum = result['hash']

                    if provided_checksum == calculated_checksum:
                        verification_result = "Success"
                    else:
                        verification_result = "Failure"

                results.append({'filename': filename, 'hash': result['hash'], 'verification_result': verification_result})
            else:  # There was an error reading the file
                results.append(result)

    return results
```

The function `process_file` calculates SHA256 hash of a given file in streaming fashion to handle large files without excessive memory usage and returns a dictionary containing filename, calculated hash or error message. The function `process_files` concurrently processes multiple files using specified number of threads and checks if the provided checksum matches the calculated hash for each file. It also verifies integrity of the file against a provided checksum and returns a list of dictionaries containing filenames, hashes, verification results (success or failure) and error messages (if any).
']

