```python
import pandas as pd

def process_large_dataset(filepath, chunk_size=100000, filter_condition=None, agg_columns=None):
    # Initialize aggregation results dictionary
    agg_results = {}

    # Read CSV file in chunks
    for chunk in pd.read_csv(filepath, chunksize=chunk_size):
        # If a filter condition is specified, apply it to the chunk
        if filter_condition:
            chunk = chunk[eval(filter_condition)]

        # If aggregation columns are specified, perform the aggregation on each column
        if agg_columns:
            for col in agg_columns:
                if col not in agg_results:
                    agg_results[col] = []

                agg_results[col].append(chunk[col])

    # If aggregation was performed, convert the aggregated lists to pandas Series for efficient memory utilization
    if agg_columns:
        for col in agg_columns:
            agg_results[col] = pd.concat(agg_results[col])

    return agg_results
```

