['Here is an implementation of such a C function in C99:

```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    int LTE_RRC_UE_ID;
    int PHYCELL_ID;
    char* buffer;
} LTE_RRC_CCH_UE_CONFIG_DRRS_TAG;

typedef struct Node {
    LTE_RRC_CCH_UE_CONFIG_DRRS_TAG data;
    struct Node* next;
} Node;

Node* head = NULL;
int successCount = 0;
int failCount = 0;

void addUci(int ueId, int phyCellId, char* buffer) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        failCount++;
        return;
    }

    new_node->data.LTE_RRC_UE_ID = ueId;
    new_node->data.PHYCELL_ID = phyCellId;

    size_t bufferLen = strlen(buffer);
    new_node->data.buffer = (char*)malloc((bufferLen + 1) * sizeof(char));
    if (!new_node->data.buffer) {
        failCount++;
        free(new_node);
        return;
    }

    strcpy(new_node->data.buffer, buffer);

    new_node->next = head;
    head = new_node;

    successCount++;
}

void updateUci(int ueId, int phyCellId, char* buffer) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.LTE_RRC_UE_ID == ueId && current->data.PHYCELL_ID == phyCellId) {
            free(current->data.buffer);

            size_t bufferLen = strlen(buffer);
            current->data.buffer = (char*)malloc((bufferLen + 1) * sizeof(char));
            if (!current->data.buffer) {
                failCount++;
                return;
            }

            strcpy(current->data.buffer, buffer);

            successCount++;
            return;
        }

        current = current->next;
    }

    failCount++;
}
```
This code firstly creates a linked list to manage `LTE_RRC_CCH_UE_CONFIG_DRRS_TAG` structures. When adding or updating UCI, it allocates memory for the buffer and copies the new data into it. If any allocation fails, it increments the fail count and returns.
It also keeps track of successful and failed operations using global counters `successCount` and `failCount` respectively. 
Finally, when a node is no longer needed, it frees all associated memory to prevent leaks.
']

