['The task requires some assumptions as no specific context is provided but assuming that NFAPI_CRC_INDICATION_PDU_T, RX_UE_INFORMATION_TAG and RNTI are defined in a way similar to:

```c
typedef struct {
    int rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned char crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_information;
    CRC_INDICATION_REL8_TAG indication_tag;
} NFAPI_CRC_INDICATION_PDU_T;
```

The function could be written as:

```c
#include <stdlib.h>
#include <pthread.h>
#define MAX_SIZE 10000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* list;
    size_t size;
    size_t capacity;
    unsigned long long averageRNTI;
    pthread_mutex_t lock;
} NFAPILIST;

void initList(NFAPILIST* nfapi) {
    nfapi->list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfapi->capacity = 1;
    nfapi->size = 0;
    nfapi->averageRNTI = 0;
    pthread_mutex_init(&nfapi->lock, NULL);
}

void addElement(NFAPILIST* nfapi, int rnti) {
    pthread_mutex_lock(&nfapi->lock);

    if (nfapi->size > 0 && nfapi->list[nfapi->size - 1].ue_information.rnti == rnti) {
        --rnti; // Ensure that no two consecutive structures in the list have the same RNTI value
    }

    if (nfapi->capacity <= nfapi->size) {
        size_t newCapacity = nfapi->capacity * 2;
        if (newCapacity > MAX_SIZE) {
            pthread_mutex_unlock(&nfapi->lock);
            return;
        }

        nfapi->list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfapi->list, newCapacity * sizeof(NFAPI_CRS_INDICATION_PDU_T));
        nfapi->capacity = newCapacity;
    }

    NFAPI_CRC_INDICATION_PDU_T newElement;
    newElement.ue_information.rnti = rnti;
    newElement.indication_tag.crcflag = rand() % 256; // Randomly set CRCFLAG

    nfapi->list[nfapi->size++] = newElement;

    unsigned long long sumRNTI = 0;
    for (int i = 0; i < nfapi->size; ++i) {
        sumRNTI += nfapi->list[i].ue_information.rnti;
    }

    nfapi->averageRNTI = sumRNTI / nfapi->size;

    pthread_mutex_unlock(&nfapi->lock);
}
```
The `addElement` function is thread-safe and ensures that no two consecutive structures in the list have the same RNTI value, the list can grow up to a maximum size of 10,000 structures. It also maintains a rolling average of the number of unique RNTI values used across all created structures.
']
